# ============================================================
# STEP 4: Create SFI Spatial Maps in ArcGIS Pro
# Hanumakonda Macro-, Micro- and Overall SFI Workflow
#
# Run in ArcGIS Pro Python / ArcGIS Pro Notebook
#
# This code will:
# 1. Read Step 2 prediction table
# 2. Extract best model predictions:
#       Overall_SFI = Lasso
#       MNI         = ElasticNet
#       MiNI        = ElasticNet
#       SFI_5core   = Lasso
# 3. Create mapping point feature class
# 4. Interpolate observed and predicted SFI surfaces using IDW
# 5. Create residual raster for Overall_SFI
# 6. Create relative fertility-zone rasters
# 7. Calculate area distribution of fertility zones
# 8. Add final rasters to ArcGIS Pro map
# ============================================================

import arcpy
import os
import re
import numpy as np
import pandas as pd

from arcpy.sa import Idw, Raster, Con

# ============================================================
# 1. PATHS
# ============================================================

arcpy.env.overwriteOutput = True

project_root = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML"
gdb = r"D:\SR University\Scieitific Reports\Sci\Sci.gdb"

ml_table_out = os.path.join(project_root, "06_ml_tables")
table_out = os.path.join(project_root, "09_tables")
fig_out = os.path.join(project_root, "08_figures")

os.makedirs(ml_table_out, exist_ok=True)
os.makedirs(table_out, exist_ok=True)
os.makedirs(fig_out, exist_ok=True)

prediction_csv = os.path.join(
    ml_table_out,
    "Hanumakonda_SFI_regularized_ML_predictions.csv"
)

step1_dataset_csv = os.path.join(
    ml_table_out,
    "Hanumakonda_macro_micro_SFI_dataset.csv"
)

mapping_csv = os.path.join(
    ml_table_out,
    "Hanumakonda_SFI_mapping_points.csv"
)

if not os.path.exists(prediction_csv):
    raise FileNotFoundError("Prediction CSV not found: " + prediction_csv)

