# ============================================================

try:
    aprx = arcpy.mp.ArcGISProject("CURRENT")

    if aprx.activeMap is not None:
        m = aprx.activeMap
    else:
        maps = aprx.listMaps()
        if len(maps) > 0:
            m = maps[0]
        else:
            m = aprx.createMap("Hanumakonda SFI Maps")

    # Add boundary and points
    try:
        m.addDataFromPath(boundary)
        m.addDataFromPath(points_utm)
    except Exception:
        pass

    # Add rasters
    add_order = [
        "Overall_SFI_Observed",
        "Overall_SFI_Predicted",
        "Overall_SFI_Residual",
        "MNI_Observed",
        "MNI_Predicted",
        "MiNI_Observed",
        "MiNI_Predicted",
        "SFI_5core_Observed",
        "SFI_5core_Predicted"
    ]

    for key in add_order:
        if key in raster_outputs:
            try:
                m.addDataFromPath(raster_outputs[key])
                print("Added raster to map:", raster_outputs[key])
            except Exception as e:
                print("Could not add raster:", raster_outputs[key])
                print("Reason:", e)

    for target, zone_raster in zone_outputs.items():
        try:
            m.addDataFromPath(zone_raster)
            print("Added zone raster to map:", zone_raster)
        except Exception as e:
            print("Could not add zone raster:", zone_raster)
            print("Reason:", e)

    try:
        aprx.save()
        print("\nArcGIS Pro project saved.")
    except Exception as e:
        print("\nCould not save ArcGIS Pro project:", e)

except Exception as e:
    print("\nMap add warning:")
    print(e)

