# ============================================================
# 10. AREA DISTRIBUTION FOR RELATIVE ZONES
# Corrected version: does not depend on ClassName field
# ============================================================

def zone_value_to_class(value):
    value = int(value)

    if value == 1:
        return "Low relative"
    elif value == 2:
        return "Moderate relative"
    elif value == 3:
        return "High relative"
    else:
        return "Unknown"

area_rows = []

for target, zone_raster in zone_outputs.items():

    print("\nCalculating area for:", target)
    print("Zone raster:", zone_raster)

    # Build raster attribute table, but do not depend on custom fields
    try:
        arcpy.management.BuildRasterAttributeTable(zone_raster, "Overwrite")
    except Exception as e:
        print("Warning: could not build raster attribute table for:", zone_raster)
        print("Reason:", e)

    cell_x = float(arcpy.management.GetRasterProperties(zone_raster, "CELLSIZEX")[0])
    cell_y = float(arcpy.management.GetRasterProperties(zone_raster, "CELLSIZEY")[0])
    cell_area_m2 = abs(cell_x * cell_y)

    total_area_ha = 0.0
    temp_rows = []

    # Only use fields that always exist in a raster attribute table
    fields_available = [f.name for f in arcpy.ListFields(zone_raster)]
    print("Available raster fields:", fields_available)

    if "Value" not in fields_available or "Count" not in fields_available:
        print("Skipping area calculation because Value/Count fields are missing:", zone_raster)
        continue

    with arcpy.da.SearchCursor(zone_raster, ["Value", "Count"]) as cursor:
        for value, count in cursor:

            class_name = zone_value_to_class(value)

            area_ha = (float(count) * cell_area_m2) / 10000.0
            total_area_ha += area_ha

            temp_rows.append({
                "Target": target,
                "Zone_value": int(value),
                "Class": class_name,
                "Cell_count": int(count),
                "Area_ha": area_ha
            })

    for row in temp_rows:
        if total_area_ha > 0:
            row["Percent_area"] = (row["Area_ha"] / total_area_ha) * 100
        else:
            row["Percent_area"] = np.nan

        area_rows.append(row)

area_df = pd.DataFrame(area_rows)

if len(area_df) > 0:
    area_df["Area_ha"] = area_df["Area_ha"].round(4)
    area_df["Percent_area"] = area_df["Percent_area"].round(4)

zone_area_csv = os.path.join(
    table_out,
    "Table_14_relative_fertility_zone_area_distribution.csv"
)

area_df.to_csv(zone_area_csv, index=False)

print("\nSaved relative zone area distribution:")
print(zone_area_csv)

print("\nArea distribution preview:")
print(area_df)

