def plot_continuous_raster(
    raster_path,
    title,
    output_path,
    colorbar_label,
    cmap="viridis",
    vmin=None,
    vmax=None,
    show_points=True
):
    arr, extent = raster_to_array(raster_path)

    fig, ax = plt.subplots(figsize=(7, 7))

    im = ax.imshow(
        arr,
        extent=extent,
        origin="upper",
        cmap=cmap,
        vmin=vmin,
        vmax=vmax
    )

    add_boundary(ax, boundary_parts, linewidth=1.1)

    if show_points:
        add_points(ax, point_xy, size=7)

    set_map_extent(ax, extent)
    add_north_arrow(ax)
    add_scale_bar(ax, extent)
    clean_axis(ax)

    cbar = fig.colorbar(
        im,
        ax=ax,
        fraction=0.035,
        pad=0.02
    )

    cbar.set_label(colorbar_label, fontsize=9)
    cbar.ax.tick_params(labelsize=8)

    ax.set_title(
        title,
        fontsize=13,
        fontweight="bold"
    )

    save_figure(fig, output_path)

