# ============================================================
# 4. HELPER FUNCTIONS
# ============================================================

def get_boundary_parts(feature_class):
    parts_list = []

    with arcpy.da.SearchCursor(feature_class, ["SHAPE@"]) as cursor:
        for row in cursor:
            geom = row[0]

            for part in geom:
                xs = []
                ys = []

                for pnt in part:
                    if pnt is None:
                        if len(xs) > 0:
                            parts_list.append((xs, ys))
                            xs = []
                            ys = []
                    else:
                        xs.append(pnt.X)
                        ys.append(pnt.Y)

                if len(xs) > 0:
                    parts_list.append((xs, ys))

    return parts_list


def get_point_xy(point_fc):
    xy = []

    with arcpy.da.SearchCursor(point_fc, ["SHAPE@XY"]) as cursor:
        for row in cursor:
            x, y = row[0]
            xy.append((x, y))

    return np.array(xy)


def raster_to_array(raster_path):
    """
    Robust raster-to-array conversion for:
    1. continuous float rasters
    2. integer zone rasters

    Important:
    Integer rasters do not support nodata_to_value=np.nan directly.
    Therefore, the raster is read first, then converted to float, then NoData is
    replaced by np.nan.
    """

    r = arcpy.Raster(raster_path)

    arr = arcpy.RasterToNumPyArray(r)
    arr = arr.astype(float)

    nodata = r.noDataValue

    if nodata is not None:
        try:
            arr[arr == float(nodata)] = np.nan
        except Exception:
            pass

    arr[arr <= -999999] = np.nan

    extent = [
        r.extent.XMin,
        r.extent.XMax,
        r.extent.YMin,
        r.extent.YMax
    ]

    return arr, extent


def get_combined_min_max(raster_paths, percentile_clip=False):
    values = []

    for path in raster_paths:
        arr, extent = raster_to_array(path)
        flat = arr[np.isfinite(arr)]

        if len(flat) > 0:
            values.append(flat)

    if len(values) == 0:
        return 0, 1

    values = np.concatenate(values)

    if percentile_clip:
        vmin = float(np.nanpercentile(values, 2))
        vmax = float(np.nanpercentile(values, 98))
    else:
        vmin = float(np.nanmin(values))
        vmax = float(np.nanmax(values))

    if vmin == vmax:
        vmin = vmin - 0.01
        vmax = vmax + 0.01

    return vmin, vmax


def add_boundary(ax, boundary_parts, linewidth=1.1):
    for xs, ys in boundary_parts:
        ax.plot(xs, ys, color="black", linewidth=linewidth)


def add_points(ax, point_xy, size=8):
    if point_xy is not None and len(point_xy) > 0:
        ax.scatter(
            point_xy[:, 0],
            point_xy[:, 1],
            s=size,
            c="black",
            edgecolors="white",
            linewidths=0.35,
            zorder=5
        )


def set_map_extent(ax, extent, buffer_ratio=0.03):
    xmin, xmax, ymin, ymax = extent

    xbuf = (xmax - xmin) * buffer_ratio
    ybuf = (ymax - ymin) * buffer_ratio

    ax.set_xlim(xmin - xbuf, xmax + xbuf)
    ax.set_ylim(ymin - ybuf, ymax + ybuf)
    ax.set_aspect("equal", adjustable="box")


def choose_scale_length_km(extent):
    xmin, xmax, ymin, ymax = extent
    width_m = xmax - xmin
    target_km = (width_m / 1000.0) / 5.0

    candidates = [
        1, 2, 5,
        10, 20, 25,
        50, 75, 100,
        150, 200
    ]

    best = min(candidates, key=lambda x: abs(x - target_km))
    return best


def add_scale_bar(ax, extent, length_km=None):
    xmin, xmax, ymin, ymax = extent

    if length_km is None:
        length_km = choose_scale_length_km(extent)

    length_m = length_km * 1000.0

    x_start = xmin + (xmax - xmin) * 0.08
    y_start = ymin + (ymax - ymin) * 0.07

    ax.plot(
        [x_start, x_start + length_m],
        [y_start, y_start],
        color="black",
        linewidth=3,
        solid_capstyle="butt"
    )

    ax.plot(
        [x_start, x_start],
        [y_start - (ymax - ymin) * 0.005, y_start + (ymax - ymin) * 0.005],
        color="black",
        linewidth=1
    )

    ax.plot(
        [x_start + length_m, x_start + length_m],
        [y_start - (ymax - ymin) * 0.005, y_start + (ymax - ymin) * 0.005],
        color="black",
        linewidth=1
    )

    ax.text(
        x_start + length_m / 2,
        y_start + (ymax - ymin) * 0.025,
        f"{length_km:g} km",
        ha="center",
        va="bottom",
        fontsize=9
    )


def clean_axis(ax):
    ax.set_xticks([])
    ax.set_yticks([])
    ax.set_xlabel("")
    ax.set_ylabel("")


def save_tiff(fig, path):
    fig.savefig(
        path,
        dpi=DPI,
        format="tiff",
        bbox_inches="tight",
        facecolor="white"
    )
    plt.close(fig)
    print("Saved TIFF:", path)


