def plot_zone_raster(
    raster_path,
    title,
    output_path,
    show_points=False
):
    arr, extent = raster_to_array(raster_path)

    arr[~np.isin(arr, [1, 2, 3])] = np.nan

    fig, ax = plt.subplots(figsize=FIGSIZE_SINGLE)

    arr_masked = np.ma.masked_invalid(arr)

    ax.imshow(
        arr_masked,
        extent=extent,
        origin="upper",
        cmap=zone_cmap,
        norm=zone_norm
    )

    add_boundary(ax, boundary_parts, linewidth=1.1)

    if show_points:
        add_points(ax, point_xy, size=7)

    set_map_extent(ax, extent)

    if SHOW_SCALE_BAR:
        add_scale_bar(ax, extent)

    clean_axis(ax)

    ax.legend(
        handles=zone_legend,
        loc="lower right",
        frameon=True,
        fontsize=8,
        title="Relative class",
        title_fontsize=9
    )

    ax.set_title(
        title,
        fontsize=13,
        fontweight="bold"
    )

    save_tiff(fig, output_path)

