# Example:
# INDIA_STATES_FC = r"D:\GIS_Data\India_Admin\India_State_Boundary.shp"
#
# You can also import the state boundary into your geodatabase and use:
# INDIA_STATES_FC = os.path.join(GDB, "India_State_Boundary")

INDIA_STATES_FC = r"D:\SR University\Scieitific Reports\India_Admin\India_State_Boundary.shp"

# Optional Telangana district boundary layer. Leave blank if not available.
# Example:
# TELANGANA_DISTRICTS_FC = r"D:\GIS_Data\India_Admin\Telangana_District_Boundary.shp"
TELANGANA_DISTRICTS_FC = r""

STATE_NAME = "Telangana"
STUDY_DISTRICT_NAMES = ["Hanumakonda", "Warangal", "Warangal Urban"]

STATE_FIELD_CANDIDATES = [
    "STATE_NAME", "ST_NM", "STNAME", "NAME_1", "NAME", "State", "state", "STATE"
]

DISTRICT_FIELD_CANDIDATES = [
    "DISTRICT", "DIST_NAME", "DISTRICT_N", "DT_NAME", "NAME_2", "NAME", "District", "district"
]

# Output resolution
DPI = 600

# Figure sizes in inches
FULL_FIGSIZE = (13.5, 5.3)
SINGLE_FIGSIZE = (5.2, 5.2)
LEGEND_FIGSIZE = (3.8, 2.5)
NORTH_FIGSIZE = (1.6, 1.9)
SCALE_FIGSIZE = (3.6, 0.9)

# Coordinate systems
SR_WGS84 = arcpy.SpatialReference(4326)
SR_UTM44N = arcpy.SpatialReference(32644)

# Visual style
COL_INDIA_FILL = "#f2f2f2"
COL_STATE_BORDER = "#bdbdbd"
COL_TELANGANA_FILL = "#f4b183"
COL_TELANGANA_EDGE = "#8c510a"
COL_DISTRICT_EDGE = "#d0d0d0"
COL_STUDY_FILL = "#d9ead3"
COL_STUDY_EDGE = "#006100"
COL_SAMPLE = "#c00000"
COL_SAMPLE_EDGE = "#ffffff"
COL_TEXT = "#222222"
COL_WATER = "#eef5ff"

# ============================================================
# 2. HELPER FUNCTIONS
# ============================================================

def exists(path):
    return bool(path) and arcpy.Exists(path)


def first_existing(paths):
    for path in paths:
        if exists(path):
            return path
    return None


def list_field_names(fc):
    return [f.name for f in arcpy.ListFields(fc)]


def detect_field(fc, candidates):
    fields = list_field_names(fc)
    lower_lookup = {f.lower(): f for f in fields}
    for cand in candidates:
        if cand.lower() in lower_lookup:
            return lower_lookup[cand.lower()]
    return None


def normalize_text(x):
    return str(x).strip().lower().replace("_", " ")


def get_geometries(fc, target_sr=None):
    geoms = []
    with arcpy.da.SearchCursor(fc, ["SHAPE@"] ) as cursor:
        for row in cursor:
            geom = row[0]
            if geom is None:
                continue
            if target_sr is not None and geom.spatialReference and geom.spatialReference.factoryCode != target_sr.factoryCode:
                try:
                    geom = geom.projectAs(target_sr)
                except Exception:
                    pass
            geoms.append(geom)
    return geoms


def get_geometries_by_attribute(fc, field_name, accepted_values, target_sr=None):
    accepted = set([normalize_text(v) for v in accepted_values])
    geoms = []
    with arcpy.da.SearchCursor(fc, ["SHAPE@", field_name]) as cursor:
        for geom, val in cursor:
            if geom is None:
                continue
            if normalize_text(val) in accepted:
                if target_sr is not None and geom.spatialReference and geom.spatialReference.factoryCode != target_sr.factoryCode:
                    try:
                        geom = geom.projectAs(target_sr)
                    except Exception:
                        pass
                geoms.append(geom)
    return geoms


def get_points(fc, target_sr=None):
    pts = []
    with arcpy.da.SearchCursor(fc, ["SHAPE@"] ) as cursor:
        for row in cursor:
            geom = row[0]
            if geom is None:
                continue
            if target_sr is not None and geom.spatialReference and geom.spatialReference.factoryCode != target_sr.factoryCode:
                try:
                    geom = geom.projectAs(target_sr)
                except Exception:
                    pass
            p = geom.centroid
            pts.append((p.X, p.Y))
    return pts


def geometry_parts_to_xy(geom):
    parts = []
    if geom is None:
        return parts
    for part in geom:
        xs = []
        ys = []
        for p in part:
            if p is None:
                if len(xs) > 2:
                    parts.append((xs, ys))
                xs = []
                ys = []
            else:
                xs.append(p.X)
                ys.append(p.Y)
        if len(xs) > 2:
            parts.append((xs, ys))
    return parts


def plot_polygons(ax, geoms, facecolor="none", edgecolor="black", linewidth=0.5, alpha=1.0, zorder=1):
    for geom in geoms:
        for xs, ys in geometry_parts_to_xy(geom):
            coords = list(zip(xs, ys))
            patch = MplPolygon(
                coords,
                closed=True,
                facecolor=facecolor,
                edgecolor=edgecolor,
                linewidth=linewidth,
                alpha=alpha,
                zorder=zorder
            )
            ax.add_patch(patch)


def plot_points(ax, pts, size=18, color="#c00000", edgecolor="#ffffff", linewidth=0.4, zorder=10):
    if not pts:
        return
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    ax.scatter(xs, ys, s=size, c=color, edgecolors=edgecolor, linewidths=linewidth, zorder=zorder)


def extent_from_geometries(geoms, pts=None, buffer_ratio=0.08):
    xs = []
    ys = []
    for geom in geoms:
        ext = geom.extent
        xs.extend([ext.XMin, ext.XMax])
        ys.extend([ext.YMin, ext.YMax])
    if pts:
        xs.extend([p[0] for p in pts])
        ys.extend([p[1] for p in pts])
    if not xs or not ys:
        raise ValueError("Cannot calculate extent because no geometry coordinates were found.")
    xmin, xmax = min(xs), max(xs)
    ymin, ymax = min(ys), max(ys)
    dx = xmax - xmin
    dy = ymax - ymin
    if dx == 0:
        dx = 1.0
    if dy == 0:
        dy = 1.0
    return (
        xmin - dx * buffer_ratio,
        xmax + dx * buffer_ratio,
        ymin - dy * buffer_ratio,
        ymax + dy * buffer_ratio
    )


def apply_extent(ax, extent):
    xmin, xmax, ymin, ymax = extent
    ax.set_xlim(xmin, xmax)
    ax.set_ylim(ymin, ymax)
    ax.set_aspect("equal", adjustable="box")


def clean_axis(ax):
    ax.set_facecolor(COL_WATER)
    ax.tick_params(axis="both", labelsize=7, colors="#444444", length=2)
    for spine in ax.spines.values():
        spine.set_linewidth(0.8)
        spine.set_color("#4d4d4d")


def add_panel_label(ax, label, title):
    ax.text(
        0.02, 0.98,
        label,
        transform=ax.transAxes,
        va="top",
        ha="left",
        fontsize=11,
        fontweight="bold",
        color="white",
        bbox=dict(facecolor="#333333", edgecolor="none", boxstyle="round,pad=0.25"),
        zorder=100
    )
    ax.text(
        0.12, 0.98,
        title,
        transform=ax.transAxes,
        va="top",
        ha="left",
        fontsize=10,
        fontweight="bold",
        color=COL_TEXT,
        bbox=dict(facecolor="white", edgecolor="#cccccc", boxstyle="round,pad=0.25", alpha=0.92),
        zorder=100
    )


def add_north_arrow(ax, x=0.90, y=0.18, size=0.10):
    ax.annotate(
        "N",
        xy=(x, y + size),
        xytext=(x, y),
        xycoords="axes fraction",
        textcoords="axes fraction",
        ha="center",
        va="center",
        fontsize=11,
        fontweight="bold",
        arrowprops=dict(facecolor="black", edgecolor="black", width=4, headwidth=14, headlength=16),
        zorder=120
    )


def nice_scale_length(width_m):
    target = width_m / 5.0 / 1000.0
    candidates = [1, 2, 5, 10, 20, 25, 50, 100, 200]
    best = min(candidates, key=lambda v: abs(v - target))
    return best


def add_scale_bar_utm(ax, location=(0.08, 0.08)):
    xmin, xmax = ax.get_xlim()
    ymin, ymax = ax.get_ylim()
    width_m = xmax - xmin
    scale_km = nice_scale_length(width_m)
    scale_m = scale_km * 1000.0
    x0 = xmin + (xmax - xmin) * location[0]
    y0 = ymin + (ymax - ymin) * location[1]
    ax.plot([x0, x0 + scale_m], [y0, y0], color="black", linewidth=3, zorder=140)
    ax.plot([x0, x0], [y0 - width_m * 0.005, y0 + width_m * 0.005], color="black", linewidth=1, zorder=140)
    ax.plot([x0 + scale_m, x0 + scale_m], [y0 - width_m * 0.005, y0 + width_m * 0.005], color="black", linewidth=1, zorder=140)
    ax.text(
        x0 + scale_m / 2.0,
        y0 + width_m * 0.012,
        f"{scale_km} km",
        ha="center",
        va="bottom",
        fontsize=8,
        color="black",
        bbox=dict(facecolor="white", edgecolor="none", alpha=0.85, pad=1.5),
        zorder=140
    )


def add_coordinate_labels(ax, projected=False):
    if projected:
        ax.set_xlabel("Easting (m, UTM Zone 44N)", fontsize=8)
        ax.set_ylabel("Northing (m, UTM Zone 44N)", fontsize=8)
    else:
        ax.set_xlabel("Longitude (degrees)", fontsize=8)
        ax.set_ylabel("Latitude (degrees)", fontsize=8)


def save_fig(fig, path):
    fig.savefig(path, dpi=DPI, bbox_inches="tight", pil_kwargs={"compression": "tiff_lzw"})
    plt.close(fig)
    print("Saved:", path)

# ============================================================
# 3. VALIDATE INPUTS
# ============================================================

if not exists(STUDY_BOUNDARY_FC):
    raise FileNotFoundError("Study boundary not found: " + STUDY_BOUNDARY_FC)

SAMPLE_POINTS_FC = first_existing(SAMPLE_POINT_CANDIDATES)
if SAMPLE_POINTS_FC is None:
    raise FileNotFoundError("No sample point layer found. Checked: " + str(SAMPLE_POINT_CANDIDATES))

if not exists(INDIA_STATES_FC):
    raise FileNotFoundError(
        "India state boundary layer not found. Update INDIA_STATES_FC at the top of this script.\n"
        "Expected example: D:\\SR University\\Scieitific Reports\\India_Admin\\India_State_Boundary.shp"
    )

STATE_FIELD = detect_field(INDIA_STATES_FC, STATE_FIELD_CANDIDATES)
if STATE_FIELD is None:
    raise ValueError(
        "Could not detect state-name field in INDIA_STATES_FC. Available fields are: "
        + str(list_field_names(INDIA_STATES_FC))
    )

DISTRICT_FIELD = None
if exists(TELANGANA_DISTRICTS_FC):
    DISTRICT_FIELD = detect_field(TELANGANA_DISTRICTS_FC, DISTRICT_FIELD_CANDIDATES)

print("Inputs validated.")
print("India states:", INDIA_STATES_FC)
print("State field:", STATE_FIELD)
print("Study boundary:", STUDY_BOUNDARY_FC)
print("Sample points:", SAMPLE_POINTS_FC)
if exists(TELANGANA_DISTRICTS_FC):
    print("Telangana districts:", TELANGANA_DISTRICTS_FC)
    print("District field:", DISTRICT_FIELD)
else:
    print("Telangana district layer not supplied. Panel B will use Telangana state boundary and study boundary.")

# ============================================================
# 4. READ GEOMETRIES
# ============================================================

# Locator panels in WGS84
india_state_geoms_wgs = get_geometries(INDIA_STATES_FC, SR_WGS84)
telangana_geoms_wgs = get_geometries_by_attribute(INDIA_STATES_FC, STATE_FIELD, [STATE_NAME], SR_WGS84)
if len(telangana_geoms_wgs) == 0:
    raise ValueError("No Telangana polygon found in India state boundary using field " + STATE_FIELD)

study_boundary_wgs = get_geometries(STUDY_BOUNDARY_FC, SR_WGS84)
sample_points_wgs = get_points(SAMPLE_POINTS_FC, SR_WGS84)

# Detailed study panel in UTM 44N
study_boundary_utm = get_geometries(STUDY_BOUNDARY_FC, SR_UTM44N)
sample_points_utm = get_points(SAMPLE_POINTS_FC, SR_UTM44N)

# Optional Telangana district layer in WGS84
if exists(TELANGANA_DISTRICTS_FC):
    telangana_districts_wgs = get_geometries(TELANGANA_DISTRICTS_FC, SR_WGS84)
    if DISTRICT_FIELD:
        study_districts_wgs = get_geometries_by_attribute(
            TELANGANA_DISTRICTS_FC,
            DISTRICT_FIELD,
            STUDY_DISTRICT_NAMES,
            SR_WGS84
        )
    else:
        study_districts_wgs = []
else:
    telangana_districts_wgs = []
    study_districts_wgs = []

print("Number of India polygons:", len(india_state_geoms_wgs))
print("Number of Telangana polygons:", len(telangana_geoms_wgs))
print("Number of study boundary polygons:", len(study_boundary_wgs))
print("Number of sample points:", len(sample_points_utm))

# Extents
india_extent = extent_from_geometries(india_state_geoms_wgs, buffer_ratio=0.04)
telangana_extent = extent_from_geometries(telangana_geoms_wgs, buffer_ratio=0.18)
study_extent_wgs = extent_from_geometries(study_boundary_wgs, sample_points_wgs, buffer_ratio=0.22)
study_extent_utm = extent_from_geometries(study_boundary_utm, sample_points_utm, buffer_ratio=0.10)

# ============================================================
# 5. PANEL PLOTTING FUNCTIONS
# ============================================================

def plot_india_panel(ax, panel_label="a", show_title=True):
    plot_polygons(ax, india_state_geoms_wgs, facecolor=COL_INDIA_FILL, edgecolor=COL_STATE_BORDER, linewidth=0.35, zorder=1)
    plot_polygons(ax, telangana_geoms_wgs, facecolor=COL_TELANGANA_FILL, edgecolor=COL_TELANGANA_EDGE, linewidth=1.2, zorder=5)
    apply_extent(ax, india_extent)
    clean_axis(ax)
    add_coordinate_labels(ax, projected=False)
    if show_title:
        add_panel_label(ax, panel_label, "India: Telangana highlighted")
    ax.text(
        0.55, 0.36,
        "Telangana",
        transform=ax.transAxes,
        fontsize=8,
        fontweight="bold",
        color=COL_TELANGANA_EDGE,
        bbox=dict(facecolor="white", edgecolor="none", alpha=0.80, pad=1.5),
        zorder=80
    )
    add_north_arrow(ax, x=0.88, y=0.14, size=0.11)


def plot_telangana_panel(ax, panel_label="b", show_title=True):
    plot_polygons(ax, telangana_geoms_wgs, facecolor="#fff2cc", edgecolor=COL_TELANGANA_EDGE, linewidth=1.2, zorder=1)
    if telangana_districts_wgs:
        plot_polygons(ax, telangana_districts_wgs, facecolor="none", edgecolor=COL_DISTRICT_EDGE, linewidth=0.45, zorder=2)
    if study_districts_wgs:
        plot_polygons(ax, study_districts_wgs, facecolor="#e2f0d9", edgecolor=COL_STUDY_EDGE, linewidth=0.9, alpha=0.75, zorder=3)
    plot_polygons(ax, study_boundary_wgs, facecolor=COL_STUDY_FILL, edgecolor=COL_STUDY_EDGE, linewidth=1.4, alpha=0.85, zorder=6)
    apply_extent(ax, telangana_extent)
    clean_axis(ax)
    add_coordinate_labels(ax, projected=False)
    if show_title:
        add_panel_label(ax, panel_label, "Telangana: study area location")
    ax.text(
        0.55, 0.34,
        "Study area",
        transform=ax.transAxes,
        fontsize=8,
        fontweight="bold",
        color=COL_STUDY_EDGE,
        bbox=dict(facecolor="white", edgecolor="none", alpha=0.85, pad=1.5),
        zorder=80
    )
    add_north_arrow(ax, x=0.88, y=0.14, size=0.11)


def plot_study_panel(ax, panel_label="c", show_title=True, include_points=True):
    plot_polygons(ax, study_boundary_utm, facecolor=COL_STUDY_FILL, edgecolor=COL_STUDY_EDGE, linewidth=1.5, alpha=0.75, zorder=3)
    if include_points:
        plot_points(ax, sample_points_utm, size=20, color=COL_SAMPLE, edgecolor=COL_SAMPLE_EDGE, linewidth=0.45, zorder=10)
    apply_extent(ax, study_extent_utm)
    clean_axis(ax)
    add_coordinate_labels(ax, projected=True)
    if show_title:
        add_panel_label(ax, panel_label, "Hanumakonda study area and sampling locations")
    add_north_arrow(ax, x=0.90, y=0.15, size=0.11)
    add_scale_bar_utm(ax, location=(0.08, 0.08))

# ============================================================
# 6. EXPORT FULL THREE-PANEL FIGURE
# ============================================================

full_map = os.path.join(OUT_DIR, "Fig_1_FULL_India_Telangana_Study_area_sampling_locations.tif")
fig, axes = plt.subplots(1, 3, figsize=FULL_FIGSIZE)
plot_india_panel(axes[0], "a")
plot_telangana_panel(axes[1], "b")
plot_study_panel(axes[2], "c", include_points=True)

legend_handles = [
    Patch(facecolor=COL_TELANGANA_FILL, edgecolor=COL_TELANGANA_EDGE, label="Telangana State"),
    Patch(facecolor=COL_STUDY_FILL, edgecolor=COL_STUDY_EDGE, label="Study area boundary"),
    Line2D([0], [0], marker="o", color="none", markerfacecolor=COL_SAMPLE, markeredgecolor=COL_SAMPLE_EDGE, markersize=6, label="Soil sampling location")
]
fig.legend(
    handles=legend_handles,
    loc="lower center",
    ncol=3,
    frameon=True,
    fontsize=9,
    bbox_to_anchor=(0.5, -0.015)
)
fig.suptitle("Figure 1. Study area and soil sampling locations", fontsize=13, fontweight="bold", y=1.02)
fig.tight_layout(rect=[0, 0.04, 1, 0.98])
save_fig(fig, full_map)

# ============================================================
# 7. EXPORT SEPARATE MAP PANELS
# ============================================================

india_panel = os.path.join(OUT_DIR, "Fig_1A_India_highlighting_Telangana.tif")
fig, ax = plt.subplots(1, 1, figsize=SINGLE_FIGSIZE)
plot_india_panel(ax, "a")
fig.tight_layout()
save_fig(fig, india_panel)

telangana_panel = os.path.join(OUT_DIR, "Fig_1B_Telangana_highlighting_study_area.tif")
fig, ax = plt.subplots(1, 1, figsize=SINGLE_FIGSIZE)
plot_telangana_panel(ax, "b")
fig.tight_layout()
save_fig(fig, telangana_panel)

study_panel = os.path.join(OUT_DIR, "Fig_1C_Study_area_sampling_locations.tif")
fig, ax = plt.subplots(1, 1, figsize=SINGLE_FIGSIZE)
plot_study_panel(ax, "c", include_points=True)
fig.tight_layout()
save_fig(fig, study_panel)

# ============================================================
# 8. EXPORT SEPARATE BASE MAPS
# ============================================================

