# ============================================================
# Compare IDW, Ordinary Kriging and Natural Neighbor
# Select best interpolation method using LOOCV statistics
# Export classified publication-quality TIFF for Observed Overall SFI
# ArcGIS Pro Python code
# ============================================================

import arcpy
import os
import math
import csv
import numpy as np

from arcpy.sa import Idw, Kriging, KrigingModelOrdinary, NaturalNeighbor, ExtractValuesToPoints
from arcpy.sa import ExtractByMask

# ------------------------------------------------------------
# 1. USER INPUTS
# ------------------------------------------------------------

# Point feature class containing 64 soil sampling points
points_fc = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\01_data\Hanumakonda_soil_points.shp"

# Field containing observed Overall SFI value
z_field = "Overall_SFI"

# Boundary polygon for clipping final raster
boundary_fc = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\01_data\Hanumakonda_boundary.shp"

# Output folder
out_folder = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Best_interpolation_Observed_Overall_SFI"
os.makedirs(out_folder, exist_ok=True)

# Raster cell size in metres
cell_size = 30

# Coordinate system should be projected, preferably WGS 1984 UTM Zone 44N
arcpy.env.outputCoordinateSystem = arcpy.SpatialReference(32644)
arcpy.env.cellSize = cell_size
arcpy.env.snapRaster = None
arcpy.env.overwriteOutput = True

# Check Spatial Analyst
arcpy.CheckOutExtension("Spatial")

# Workspace for temporary outputs
scratch_gdb = arcpy.env.scratchGDB

# ------------------------------------------------------------
# 2. OUTPUT PATHS
# ------------------------------------------------------------

comparison_csv = os.path.join(out_folder, "Observed_Overall_SFI_interpolation_LOOCV_comparison.csv")

best_raster_raw = os.path.join(out_folder, "Observed_Overall_SFI_best_interpolation_raw.tif")
best_raster_clip = os.path.join(out_folder, "Observed_Overall_SFI_best_interpolation_clipped.tif")
best_tiff_export = os.path.join(out_folder, "Fig_2_Observed_Overall_SFI_best_classified_publication.tif")

# ------------------------------------------------------------
# 3. GET POINT IDS AND OBSERVED VALUES
# ------------------------------------------------------------

oid_field = arcpy.Describe(points_fc).OIDFieldName

records = []
with arcpy.da.SearchCursor(points_fc, [oid_field, z_field]) as cursor:
    for oid, obs in cursor:
        if obs is not None:
            records.append((oid, float(obs)))

if len(records) < 10:
    raise Exception("Too few valid observations. Check points_fc and z_field.")

observed_values = np.array([r[1] for r in records], dtype=float)

print("Number of valid observations:", len(records))
print("Observed value range:", observed_values.min(), observed_values.max())

# ------------------------------------------------------------
# 4. INTERPOLATION FUNCTION
# ------------------------------------------------------------

def create_interpolation(method_name, training_layer, output_raster):
    """
    Create interpolation raster using one of three methods:
    IDW, OK, NN.
    """
    if method_name == "IDW":
        # IDW: power 2 is standard and stable for local soil-test interpolation
        raster = Idw(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        # Ordinary Kriging with spherical semivariogram.
        # This is a stable first-choice model for soil fertility surfaces.
        # Lag/range parameters can be refined later if needed.
        krig_model = KrigingModelOrdinary("SPHERICAL")
        raster = Kriging(
            in_point_features=training_layer,
            z_field=z_field,
            kriging_model=krig_model,
            cell_size=cell_size
        )

    elif method_name == "NN":
        # Natural Neighbor interpolation.
        # Good for smooth local surfaces inside the sampled point support.
        raster = NaturalNeighbor(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size
        )

    else:
        raise ValueError("Unknown interpolation method.")

    raster.save(output_raster)
    return output_raster

# ------------------------------------------------------------
# 5. LEAVE-ONE-OUT CROSS-VALIDATION
# ------------------------------------------------------------

methods = ["IDW", "OK", "NN"]
all_predictions = {m: [] for m in methods}

for method in methods:
    print("\nRunning LOOCV for:", method)

    for oid, obs in records:
        # Training points = all except current point
        train_layer = f"train_{method}_{oid}"
        test_layer = f"test_{method}_{oid}"

        arcpy.management.MakeFeatureLayer(
            points_fc,
            train_layer,
            f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} <> {oid}"
        )

        arcpy.management.MakeFeatureLayer(
            points_fc,
            test_layer,
            f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} = {oid}"
        )

        temp_raster = os.path.join(scratch_gdb, f"tmp_{method}_{oid}")
        temp_extract = os.path.join(scratch_gdb, f"ext_{method}_{oid}")

        try:
            create_interpolation(method, train_layer, temp_raster)

            ExtractValuesToPoints(
                in_point_features=test_layer,
                in_raster=temp_raster,
                out_point_features=temp_extract,
                interpolate_values="INTERPOLATE",
                add_attributes="VALUE_ONLY"
            )

            pred = None
            with arcpy.da.SearchCursor(temp_extract, ["RASTERVALU"]) as cur:
                for row in cur:
                    pred = row[0]

            if pred is not None and pred != -9999:
                all_predictions[method].append((obs, float(pred)))

        except Exception as e:
            print(f"Warning: {method}, OID {oid} failed:", e)

        finally:
            for item in [train_layer, test_layer, temp_raster, temp_extract]:
                try:
                    arcpy.management.Delete(item)
                except:
                    pass

    print(method, "valid LOOCV predictions:", len(all_predictions[method]))

# ------------------------------------------------------------
# 6. CALCULATE STATISTICS
# ------------------------------------------------------------

def calc_stats(obs, pred):
    obs = np.array(obs, dtype=float)
    pred = np.array(pred, dtype=float)

    residual = pred - obs

    n = len(obs)
    me = np.mean(residual)
    mae = np.mean(np.abs(residual))
    rmse = math.sqrt(np.mean(residual ** 2))

    ss_res = np.sum((obs - pred) ** 2)
    ss_tot = np.sum((obs - np.mean(obs)) ** 2)

    r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else np.nan
    rpd = np.std(obs, ddof=1) / rmse if rmse != 0 else np.nan

    return {
        "n": n,
        "ME": me,
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "RPD": rpd
    }

stats = []

for method in methods:
    pairs = all_predictions[method]
    obs = [p[0] for p in pairs]
    pred = [p[1] for p in pairs]

    s = calc_stats(obs, pred)
    s["Method"] = method
    stats.append(s)

# Sort method ranking
stats_sorted = sorted(
    stats,
    key=lambda x: (x["RMSE"], x["MAE"], -x["R2"], -x["RPD"])
)

best_method = stats_sorted[0]["Method"]

print("\nInterpolation comparison:")
for s in stats_sorted:
    print(
        s["Method"],
        "n =", s["n"],
        "ME =", round(s["ME"], 4),
        "MAE =", round(s["MAE"], 4),
        "RMSE =", round(s["RMSE"], 4),
        "R2 =", round(s["R2"], 4),
        "RPD =", round(s["RPD"], 4)
    )

print("\nBest method selected:", best_method)

# Save comparison table
with open(comparison_csv, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["Method", "n", "ME", "MAE", "RMSE", "R2", "RPD"])
    for s in stats_sorted:
        writer.writerow([
            s["Method"],
            s["n"],
            round(s["ME"], 6),
            round(s["MAE"], 6),
            round(s["RMSE"], 6),
            round(s["R2"], 6),
            round(s["RPD"], 6)
        ])

print("Comparison CSV saved:")
print(comparison_csv)

# ------------------------------------------------------------
# 7. CREATE FINAL RASTER USING BEST METHOD AND ALL POINTS
# ------------------------------------------------------------

final_layer = "all_points_for_best_interpolation"
arcpy.management.MakeFeatureLayer(points_fc, final_layer)

create_interpolation(best_method, final_layer, best_raster_raw)

# Clip to sampled study boundary
clipped = ExtractByMask(best_raster_raw, boundary_fc)
clipped.save(best_raster_clip)

print("Best clipped raster saved:")
print(best_raster_clip)

# ------------------------------------------------------------
# 8. ADD FINAL RASTER TO CURRENT MAP AND CLASSIFY
# ------------------------------------------------------------

aprx = arcpy.mp.ArcGISProject("CURRENT")
m = aprx.activeMap

if m is None:
    raise Exception("Open an ArcGIS Pro map before running the symbology/export section.")

# Remove old layer if already present
for lyr in m.listLayers():
    if lyr.name == "Fig_2_Observed_Overall_SFI_best_classified":
        m.removeLayer(lyr)

lyr = m.addDataFromPath(best_raster_clip)
lyr.name = "Fig_2_Observed_Overall_SFI_best_classified"

# ------------------------------------------------------------
# 9. CLASSIFIED SYMBOLOGY
# ------------------------------------------------------------
# These are local classes for observed Overall SFI.
# They improve map contrast compared with stretched symbology.

class_breaks = [
    {
        "upper": 0.72,
        "label": "0.67-0.72  Lower local SFI",
        "color": {"RGB": [215, 48, 39, 100]}
    },
    {
        "upper": 0.77,
        "label": "0.72-0.77  Low-moderate SFI",
        "color": {"RGB": [252, 141, 89, 100]}
    },
    {
        "upper": 0.82,
        "label": "0.77-0.82  Moderate SFI",
        "color": {"RGB": [254, 224, 139, 100]}
    },
    {
        "upper": 0.87,
        "label": "0.82-0.87  High SFI",
        "color": {"RGB": [145, 207, 96, 100]}
    },
    {
        "upper": 0.93,
        "label": "0.87-0.93  Highest local SFI",
        "color": {"RGB": [26, 152, 80, 100]}
    }
]

sym = lyr.symbology
sym.updateColorizer("RasterClassifyColorizer")
sym.colorizer.classificationField = "Value"
sym.colorizer.breakCount = len(class_breaks)
sym.colorizer.classificationMethod = "ManualInterval"

for i, brk in enumerate(sym.colorizer.classBreaks):
    brk.upperBound = class_breaks[i]["upper"]
    brk.label = class_breaks[i]["label"]
    brk.color = class_breaks[i]["color"]

lyr.symbology = sym
lyr.transparency = 0

# ------------------------------------------------------------
# 10. EXPORT ACTIVE MAP OR LAYOUT AS PUBLICATION TIFF
# ------------------------------------------------------------

active_view = aprx.activeView

if active_view is None:
    raise Exception("Open the map view or layout view before exporting.")

active_view.exportToTIFF(
    best_tiff_export,
    resolution=600,
    world_file=True,
    color_mode="24-BIT_TRUE_COLOR",
    tiff_compression="LZW"
)

print("Publication classified TIFF exported:")
print(best_tiff_export)

aprx.save()

# Release extension
arcpy.CheckInExtension("Spatial")

