import arcpy
import os
import math
import csv
import numpy as np
from arcpy.sa import Idw, Kriging, KrigingModelOrdinary, NaturalNeighbor, ExtractValuesToPoints, ExtractByMask

# ------------------------------------------------------------
# 1. USER SETTINGS
