# ------------------------------------------------------------
# 2. FIND LAYERS FROM CURRENT MAP
# ------------------------------------------------------------

def find_layer_by_name(map_obj, layer_name):
    for lyr in map_obj.listLayers():
        if lyr.name.lower() == layer_name.lower():
            return lyr
    return None

points_layer = find_layer_by_name(m, points_layer_name)
boundary_layer = find_layer_by_name(m, boundary_layer_name)

if points_layer is None:
    available = [lyr.name for lyr in m.listLayers()]
    raise Exception(
        "Point layer not found in current map.\n"
        f"Required layer name: {points_layer_name}\n"
        f"Available layers: {available}"
    )

if boundary_layer is None:
    available = [lyr.name for lyr in m.listLayers()]
    raise Exception(
        "Boundary layer not found in current map.\n"
        f"Required layer name: {boundary_layer_name}\n"
        f"Available layers: {available}"
    )

points_fc = points_layer
boundary_fc = boundary_layer

# ------------------------------------------------------------
# 3. FIND OVERALL SFI FIELD
# ------------------------------------------------------------

field_names = [f.name for f in arcpy.ListFields(points_fc)]

z_field = None
for candidate in z_field_candidates:
    if candidate in field_names:
        z_field = candidate
        break

if z_field is None:
    raise Exception(
        "Observed Overall SFI field not found.\n"
        f"Tried these names: {z_field_candidates}\n"
        f"Available fields: {field_names}"
    )

print("Using point layer:", points_layer.name)
print("Using boundary layer:", boundary_layer.name)
print("Using Overall SFI field:", z_field)

# ------------------------------------------------------------
# 4. OUTPUT PATHS
# ------------------------------------------------------------

scratch_gdb = arcpy.env.scratchGDB

comparison_csv = os.path.join(
    out_folder,
    "Observed_Overall_SFI_IDW_OK_NN_LOOCV_comparison.csv"
)

best_raster_raw = os.path.join(
    out_folder,
    "Observed_Overall_SFI_best_interpolation_raw.tif"
)

best_raster_clip = os.path.join(
    out_folder,
    "Observed_Overall_SFI_best_interpolation_clipped.tif"
)

best_tiff_export = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_best_classified_publication.tif"
)

# ------------------------------------------------------------
# 5. GET POINT IDS AND OBSERVED VALUES
# ------------------------------------------------------------

oid_field = arcpy.Describe(points_fc).OIDFieldName

records = []
with arcpy.da.SearchCursor(points_fc, [oid_field, z_field]) as cursor:
    for oid, obs in cursor:
        if obs is not None:
            records.append((oid, float(obs)))

if len(records) < 10:
    raise Exception("Too few valid observed Overall SFI values. Check the field values.")

observed_values = np.array([r[1] for r in records], dtype=float)

print("Number of valid observations:", len(records))
print("Observed Overall SFI range:", round(observed_values.min(), 4), "-", round(observed_values.max(), 4))

# ------------------------------------------------------------
# 6. INTERPOLATION FUNCTION
# ------------------------------------------------------------

def create_interpolation(method_name, training_layer, output_raster):
    if method_name == "IDW":
        raster = Idw(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        krig_model = KrigingModelOrdinary("SPHERICAL")
        raster = Kriging(
            in_point_features=training_layer,
            z_field=z_field,
            kriging_model=krig_model,
            cell_size=cell_size
        )

    elif method_name == "NN":
        raster = NaturalNeighbor(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size
        )

    else:
        raise ValueError("Unknown interpolation method.")

    raster.save(output_raster)
    return output_raster

# ------------------------------------------------------------
# 7. LEAVE-ONE-OUT CROSS-VALIDATION
# ------------------------------------------------------------

methods = ["IDW", "OK", "NN"]
all_predictions = {method: [] for method in methods}

for method in methods:
    print("\nRunning LOOCV for:", method)

    for oid, obs in records:
        oid_sql = f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} = {oid}"
        train_sql = f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} <> {oid}"

        train_layer = f"train_{method}_{oid}"
        test_layer = f"test_{method}_{oid}"

        arcpy.management.MakeFeatureLayer(points_fc, train_layer, train_sql)
        arcpy.management.MakeFeatureLayer(points_fc, test_layer, oid_sql)

        temp_raster = os.path.join(scratch_gdb, f"r_{method}_{oid}")
        temp_extract = os.path.join(scratch_gdb, f"e_{method}_{oid}")

        try:
            create_interpolation(method, train_layer, temp_raster)

            ExtractValuesToPoints(
                in_point_features=test_layer,
                in_raster=temp_raster,
                out_point_features=temp_extract,
                interpolate_values="INTERPOLATE",
                add_attributes="VALUE_ONLY"
            )

            pred = None
            with arcpy.da.SearchCursor(temp_extract, ["RASTERVALU"]) as cur:
                for row in cur:
                    pred = row[0]

            if pred is not None and pred != -9999:
                all_predictions[method].append((obs, float(pred)))

        except Exception as e:
            print(f"Warning: {method}, OID {oid} failed:", e)

        finally:
            for item in [train_layer, test_layer, temp_raster, temp_extract]:
                try:
                    arcpy.management.Delete(item)
                except:
                    pass

    print(method, "valid LOOCV predictions:", len(all_predictions[method]))

# ------------------------------------------------------------
# 8. CALCULATE VALIDATION STATISTICS
# ------------------------------------------------------------

def calc_stats(obs, pred):
    obs = np.array(obs, dtype=float)
    pred = np.array(pred, dtype=float)

    residual = pred - obs

    n = len(obs)
    me = np.mean(residual)
    mae = np.mean(np.abs(residual))
    rmse = math.sqrt(np.mean(residual ** 2))

    ss_res = np.sum((obs - pred) ** 2)
    ss_tot = np.sum((obs - np.mean(obs)) ** 2)

    r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else np.nan
    rpd = np.std(obs, ddof=1) / rmse if rmse != 0 else np.nan

    return {
        "n": n,
        "ME": me,
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "RPD": rpd
    }

stats = []

for method in methods:
    pairs = all_predictions[method]

    if len(pairs) < 10:
        print("Skipping", method, "because too few predictions were produced.")
        continue

    obs = [p[0] for p in pairs]
    pred = [p[1] for p in pairs]

    s = calc_stats(obs, pred)
    s["Method"] = method
    stats.append(s)

if len(stats) == 0:
    raise Exception("No interpolation method produced valid cross-validation results.")

# Ranking rule: lowest RMSE, lowest MAE, highest R2, highest RPD
stats_sorted = sorted(
    stats,
    key=lambda x: (x["RMSE"], x["MAE"], -x["R2"], -x["RPD"])
)

best_method = stats_sorted[0]["Method"]

print("\nInterpolation comparison results:")
for s in stats_sorted:
    print(
        s["Method"],
        "| n =", s["n"],
        "| ME =", round(s["ME"], 5),
        "| MAE =", round(s["MAE"], 5),
        "| RMSE =", round(s["RMSE"], 5),
        "| R2 =", round(s["R2"], 5),
        "| RPD =", round(s["RPD"], 5)
    )

print("\nBest selected interpolation method:", best_method)

# Save comparison table
with open(comparison_csv, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["Method", "n", "ME", "MAE", "RMSE", "R2", "RPD"])
    for s in stats_sorted:
        writer.writerow([
            s["Method"],
            s["n"],
            round(s["ME"], 6),
            round(s["MAE"], 6),
            round(s["RMSE"], 6),
            round(s["R2"], 6),
            round(s["RPD"], 6)
        ])

print("Saved comparison CSV:")
print(comparison_csv)

# ------------------------------------------------------------
# 9. CREATE FINAL BEST INTERPOLATION RASTER USING ALL POINTS
# ------------------------------------------------------------

all_points_layer = "all_points_best_interpolation"
arcpy.management.MakeFeatureLayer(points_fc, all_points_layer)

create_interpolation(best_method, all_points_layer, best_raster_raw)

clipped = ExtractByMask(best_raster_raw, boundary_fc)
clipped.save(best_raster_clip)

print("Saved clipped best raster:")
print(best_raster_clip)

# ------------------------------------------------------------
# 10. ADD FINAL RASTER AND APPLY CLASSIFIED SYMBOLOGY
# ------------------------------------------------------------

for lyr in m.listLayers():
    if lyr.name == "Fig_2_Observed_Overall_SFI_best_classified":
        m.removeLayer(lyr)

final_layer = m.addDataFromPath(best_raster_clip)
final_layer.name = "Fig_2_Observed_Overall_SFI_best_classified"

# Manual classes for strong publication contrast
class_breaks = [
    {
        "upper": 0.72,
        "label": "0.67-0.72  Lower local SFI",
        "color": {"RGB": [215, 48, 39, 100]}
    },
    {
        "upper": 0.77,
        "label": "0.72-0.77  Low-moderate SFI",
        "color": {"RGB": [252, 141, 89, 100]}
    },
    {
        "upper": 0.82,
        "label": "0.77-0.82  Moderate SFI",
        "color": {"RGB": [254, 224, 139, 100]}
    },
    {
        "upper": 0.87,
        "label": "0.82-0.87  High SFI",
        "color": {"RGB": [145, 207, 96, 100]}
    },
    {
        "upper": 0.93,
        "label": "0.87-0.93  Highest local SFI",
        "color": {"RGB": [26, 152, 80, 100]}
    }
]

sym = final_layer.symbology
sym.updateColorizer("RasterClassifyColorizer")
sym.colorizer.classificationField = "Value"
sym.colorizer.breakCount = len(class_breaks)
sym.colorizer.classificationMethod = "ManualInterval"

for i, brk in enumerate(sym.colorizer.classBreaks):
    brk.upperBound = class_breaks[i]["upper"]
    brk.label = class_breaks[i]["label"]
    brk.color = class_breaks[i]["color"]

final_layer.symbology = sym
final_layer.transparency = 0

# ------------------------------------------------------------
# 11. EXPORT ACTIVE VIEW AS HIGH-QUALITY TIFF
# ------------------------------------------------------------

active_view = aprx.activeView

if active_view is None:
    raise Exception("Open the map view or layout view before exporting.")

active_view.exportToTIFF(
    best_tiff_export,
    resolution=600,
    world_file=True,
    color_mode="24-BIT_TRUE_COLOR",
    tiff_compression="LZW"
)

print("Exported publication TIFF:")
print(best_tiff_export)

aprx.save()
arcpy.CheckInExtension("Spatial")

