arcpy.management.MakeFeatureLayer(points_layer, all_points_layer)

create_interpolation(best_method, all_points_layer, raw_idw_raster)

if arcpy.Exists(clipped_idw_raster):
    arcpy.management.Delete(clipped_idw_raster)

clipped = ExtractByMask(raw_idw_raster, boundary_layer)
clipped.save(clipped_idw_raster)

arcpy.management.CalculateStatistics(clipped_idw_raster)

print("Clipped interpolation raster saved:")
print(clipped_idw_raster)

