# ============================================================
# FIG. 2 OBSERVED OVERALL SFI
# Correct publication map:
# IDW interpolation + classified integer raster + colour map
# Layout export with map frame, north arrow, scale bar and legend
# ============================================================

import arcpy
import os
import math
import csv
import numpy as np

from arcpy.sa import (
    Idw,
    Kriging,
    KrigingModelOrdinary,
    NaturalNeighbor,
    ExtractValuesToPoints,
    ExtractByMask,
    Reclassify,
    RemapRange,
    Raster
)

# ------------------------------------------------------------
# 1. USER SETTINGS
# ------------------------------------------------------------

points_layer_name = "sfi_mapping_points_utm44n"
boundary_layer_name = "hanumakonda_study_boundary_500m"
z_field = "Obs_Overall"

out_folder = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_correct_classified_map"
os.makedirs(out_folder, exist_ok=True)

cell_size = 30

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = arcpy.SpatialReference(32644)
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

# ------------------------------------------------------------
# 2. OUTPUT PATHS
# ------------------------------------------------------------

comparison_csv = os.path.join(
    out_folder,
    "Fig_2_IDW_OK_NN_LOOCV_comparison.csv"
)

best_method_txt = os.path.join(
    out_folder,
    "Fig_2_best_interpolation_method.txt"
)

raw_idw_raster = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_IDW_raw.tif"
)

clipped_idw_raster = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_IDW_clipped.tif"
)

classified_raster = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_IDW_classified_integer.tif"
)

colormap_file = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_colormap.clr"
)

final_tiff = os.path.join(
    out_folder,
    "Fig_2_Observed_Overall_SFI_IDW_classified_map_with_legend.tif"
)

# ------------------------------------------------------------
# 3. OPEN CURRENT PROJECT AND FIND EXISTING POINT/BOUNDARY LAYERS
# ------------------------------------------------------------

aprx = arcpy.mp.ArcGISProject("CURRENT")

m0 = aprx.activeMap
if m0 is None:
    maps = aprx.listMaps()
    if len(maps) == 0:
        raise Exception("No map found in this ArcGIS Pro project.")
    m0 = maps[0]

def get_layer_by_name(map_obj, layer_name):
    for lyr in map_obj.listLayers():
        if lyr.name.lower() == layer_name.lower():
            return lyr
    return None

points_layer = get_layer_by_name(m0, points_layer_name)
boundary_layer = get_layer_by_name(m0, boundary_layer_name)

if points_layer is None:
    available = [lyr.name for lyr in m0.listLayers()]
    raise Exception(
        "Point layer not found.\n"
        f"Required: {points_layer_name}\n"
        f"Available layers: {available}"
    )

if boundary_layer is None:
    available = [lyr.name for lyr in m0.listLayers()]
    raise Exception(
        "Boundary layer not found.\n"
        f"Required: {boundary_layer_name}\n"
        f"Available layers: {available}"
    )

field_names = [f.name for f in arcpy.ListFields(points_layer)]

if z_field not in field_names:
    raise Exception(
        f"Field {z_field} not found in point layer.\n"
        f"Available fields: {field_names}"
    )

print("Using point layer:", points_layer.name)
print("Using boundary layer:", boundary_layer.name)
print("Using SFI field:", z_field)

# ------------------------------------------------------------
# 4. READ OBSERVED VALUES
# ------------------------------------------------------------

oid_field = arcpy.Describe(points_layer).OIDFieldName

records = []
with arcpy.da.SearchCursor(points_layer, [oid_field, z_field]) as cursor:
    for oid, value in cursor:
        if value is not None:
            records.append((oid, float(value)))

if len(records) < 10:
    raise Exception("Too few valid observed Overall SFI values.")

observed_values = np.array([r[1] for r in records], dtype=float)

print("Number of valid observations:", len(records))
print("Observed Overall SFI range:",
      round(observed_values.min(), 4),
      "-",
      round(observed_values.max(), 4))

# ------------------------------------------------------------
# 5. INTERPOLATION FUNCTION
# ------------------------------------------------------------

def create_interpolation(method_name, training_layer, output_raster):

    if arcpy.Exists(output_raster):
        arcpy.management.Delete(output_raster)

    if method_name == "IDW":
        raster = Idw(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        krig_model = KrigingModelOrdinary("SPHERICAL")
        raster = Kriging(
            in_point_features=training_layer,
            z_field=z_field,
            kriging_model=krig_model,
            cell_size=cell_size
        )

    elif method_name == "NN":
        raster = NaturalNeighbor(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size
        )

    else:
        raise ValueError("Unknown interpolation method.")

    raster.save(output_raster)
    return output_raster

# ------------------------------------------------------------
# 6. COMPARE IDW, ORDINARY KRIGING AND NATURAL NEIGHBOR
# ------------------------------------------------------------

methods = ["IDW", "OK", "NN"]
all_predictions = {method: {} for method in methods}
scratch_gdb = arcpy.env.scratchGDB

for method in methods:
    print("\nRunning LOOCV for:", method)

    for oid, obs in records:

        train_sql = f"{arcpy.AddFieldDelimiters(points_layer, oid_field)} <> {oid}"
        test_sql = f"{arcpy.AddFieldDelimiters(points_layer, oid_field)} = {oid}"

        train_layer_name = f"train_{method}_{oid}"
        test_layer_name = f"test_{method}_{oid}"

        temp_raster = os.path.join(scratch_gdb, f"r_{method}_{oid}")
        temp_extract = os.path.join(scratch_gdb, f"e_{method}_{oid}")

        try:
            arcpy.management.MakeFeatureLayer(points_layer, train_layer_name, train_sql)
            arcpy.management.MakeFeatureLayer(points_layer, test_layer_name, test_sql)

            create_interpolation(method, train_layer_name, temp_raster)

            if arcpy.Exists(temp_extract):
                arcpy.management.Delete(temp_extract)

            ExtractValuesToPoints(
                in_point_features=test_layer_name,
                in_raster=temp_raster,
                out_point_features=temp_extract,
                interpolate_values="INTERPOLATE",
                add_attributes="VALUE_ONLY"
            )

            pred = None
            with arcpy.da.SearchCursor(temp_extract, ["RASTERVALU"]) as cur:
                for row in cur:
                    pred = row[0]

            if pred is not None and pred != -9999:
                all_predictions[method][oid] = (obs, float(pred))

        except Exception as e:
            print(f"Warning: {method}, OID {oid} failed:", e)

        finally:
            for item in [train_layer_name, test_layer_name, temp_raster, temp_extract]:
                try:
                    if arcpy.Exists(item):
                        arcpy.management.Delete(item)
                except:
                    pass

    print(method, "valid predictions:", len(all_predictions[method]))

# Use common validation points for fair comparison
common_oids = set(all_predictions["IDW"].keys())
for method in methods:
    common_oids = common_oids.intersection(set(all_predictions[method].keys()))

common_oids = sorted(list(common_oids))

if len(common_oids) < 10:
    raise Exception("Too few common validation points for IDW, OK and NN comparison.")

print("\nCommon validation points:", len(common_oids))

def calc_stats(obs, pred):

    obs = np.array(obs, dtype=float)
    pred = np.array(pred, dtype=float)

    residual = pred - obs

    n = len(obs)
    me = np.mean(residual)
    mae = np.mean(np.abs(residual))
    rmse = math.sqrt(np.mean(residual ** 2))

    ss_res = np.sum((obs - pred) ** 2)
    ss_tot = np.sum((obs - np.mean(obs)) ** 2)

    r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else np.nan
    rpd = np.std(obs, ddof=1) / rmse if rmse != 0 else np.nan

    return {
        "n": n,
        "ME": me,
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "RPD": rpd
    }

stats = []

for method in methods:
    obs_list = []
    pred_list = []

    for oid in common_oids:
        obs, pred = all_predictions[method][oid]
        obs_list.append(obs)
        pred_list.append(pred)

    s = calc_stats(obs_list, pred_list)
    s["Method"] = method
    stats.append(s)

stats_sorted = sorted(
    stats,
    key=lambda x: (x["RMSE"], x["MAE"], -x["R2"], -x["RPD"])
)

best_method = stats_sorted[0]["Method"]

print("\nInterpolation comparison results:")
for s in stats_sorted:
    print(
        s["Method"],
        "| n =", s["n"],
        "| ME =", round(s["ME"], 6),
        "| MAE =", round(s["MAE"], 6),
        "| RMSE =", round(s["RMSE"], 6),
        "| R2 =", round(s["R2"], 6),
        "| RPD =", round(s["RPD"], 6)
    )

print("\nBest selected interpolation method:", best_method)

with open(comparison_csv, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["Method", "n", "ME", "MAE", "RMSE", "R2", "RPD"])
    for s in stats_sorted:
        writer.writerow([
            s["Method"],
            s["n"],
            round(s["ME"], 8),
            round(s["MAE"], 8),
            round(s["RMSE"], 8),
            round(s["R2"], 8),
            round(s["RPD"], 8)
        ])

with open(best_method_txt, "w") as f:
    f.write("Best interpolation method for Fig. 2 Observed Overall SFI\n")
    f.write(f"Selected method: {best_method}\n\n")
    for s in stats_sorted:
        f.write(
            f"{s['Method']}: n={s['n']}, ME={s['ME']:.8f}, "
            f"MAE={s['MAE']:.8f}, RMSE={s['RMSE']:.8f}, "
            f"R2={s['R2']:.8f}, RPD={s['RPD']:.8f}\n"
        )

