# ------------------------------------------------------------
# 13. EXPORT NORTH ARROW ONLY
# ------------------------------------------------------------

fig, ax = plt.subplots(figsize=(1.2, 1.6))
ax.axis("off")

ax.annotate(
    "",
    xy=(0.5, 0.88),
    xytext=(0.5, 0.25),
    xycoords="axes fraction",
    textcoords="axes fraction",
    arrowprops=dict(
        facecolor="black",
        edgecolor="black",
        width=6,
        headwidth=22,
        headlength=25
    )
)

ax.text(
    0.5,
    0.96,
    "N",
    transform=ax.transAxes,
    ha="center",
    va="center",
    fontsize=18,
    fontweight="bold"
)

save_tiff(fig, north_arrow_tif, dpi)
plt.close(fig)

print("North arrow only TIFF saved:")
print(north_arrow_tif)

# ------------------------------------------------------------
# 14. EXPORT SCALE BAR ONLY
# ------------------------------------------------------------

fig, ax = plt.subplots(figsize=(3.4, 0.8))
ax.axis("off")

ax.plot(
    [0.15, 0.85],
    [0.40, 0.40],
    color="black",
    linewidth=4,
    solid_capstyle="butt",
    transform=ax.transAxes
)

ax.plot(
    [0.15, 0.15],
    [0.32, 0.48],
    color="black",
    linewidth=2,
    transform=ax.transAxes
)

ax.plot(
    [0.85, 0.85],
    [0.32, 0.48],
    color="black",
    linewidth=2,
    transform=ax.transAxes
)

ax.text(
    0.50,
    0.62,
    "10 km",
    transform=ax.transAxes,
    ha="center",
    va="bottom",
    fontsize=12,
    fontweight="bold"
)

save_tiff(fig, scale_bar_tif, dpi)
plt.close(fig)

print("Scale bar only TIFF saved:")
print(scale_bar_tif)

# ------------------------------------------------------------
# 15. FINISH
# ------------------------------------------------------------

aprx.save()
arcpy.CheckInExtension("Spatial")

print("\nDONE. Files created:")
print("1. Complete map:", complete_map_tif)
print("2. Map only:", map_only_tif)
print("3. Legend only:", legend_only_tif)
print("4. North arrow only:", north_arrow_tif)
print("5. Scale bar only:", scale_bar_tif)
print("6. Classified raster:", classified_raster)

