# ============================================================
# FIG. 2 OBSERVED OVERALL SFI ANALYSIS ONLY
# No export. No download.
# Creates final classified map layers in ArcGIS Pro Contents panel.
# ============================================================

import arcpy
import os
import math
import csv
import numpy as np

from arcpy.sa import (
    Idw,
    Kriging,
    KrigingModelOrdinary,
    NaturalNeighbor,
    ExtractValuesToPoints,
    ExtractByMask,
    Reclassify,
    RemapRange
)

# ------------------------------------------------------------
# 1. USER SETTINGS
# ------------------------------------------------------------

points_layer_name = "sfi_mapping_points_utm44n"
boundary_layer_name = "hanumakonda_study_boundary_500m"
z_field = "Obs_Overall"

out_folder = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_analysis_only"
os.makedirs(out_folder, exist_ok=True)

cell_size = 30

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = arcpy.SpatialReference(32644)
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

# ------------------------------------------------------------
# 2. WORKSPACE
# ------------------------------------------------------------

work_gdb = os.path.join(out_folder, "Fig2_analysis_only.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(out_folder, "Fig2_analysis_only.gdb")

points_fc = os.path.join(work_gdb, "fig2_points")
boundary_fc = os.path.join(work_gdb, "fig2_boundary")

comparison_csv = os.path.join(out_folder, "Fig2_IDW_OK_NN_LOOCV_statistics.csv")
best_method_txt = os.path.join(out_folder, "Fig2_best_interpolation_method.txt")

best_raw_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_best_raw")
best_clipped_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_best_clipped")
classified_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_classified")

# ------------------------------------------------------------
# 3. FIND POINT AND BOUNDARY LAYERS
# ------------------------------------------------------------

aprx = arcpy.mp.ArcGISProject("CURRENT")

def find_layer(aprx_obj, target_name):
    for mp in aprx_obj.listMaps():
        for lyr in mp.listLayers():
            if lyr.name.lower() == target_name.lower():
                return mp, lyr
    return None, None

map_obj, points_layer = find_layer(aprx, points_layer_name)
_, boundary_layer = find_layer(aprx, boundary_layer_name)

if points_layer is None:
    all_layers = []
    for mp in aprx.listMaps():
        all_layers.extend([lyr.name for lyr in mp.listLayers()])
    raise Exception(
        f"Point layer not found: {points_layer_name}\n"
        f"Available layers: {all_layers}"
    )

if boundary_layer is None:
    all_layers = []
    for mp in aprx.listMaps():
        all_layers.extend([lyr.name for lyr in mp.listLayers()])
    raise Exception(
        f"Boundary layer not found: {boundary_layer_name}\n"
        f"Available layers: {all_layers}"
    )

field_names = [f.name for f in arcpy.ListFields(points_layer)]

if z_field not in field_names:
    raise Exception(
        f"Field not found: {z_field}\n"
        f"Available fields: {field_names}"
    )

print("Using map:", map_obj.name)
print("Using point layer:", points_layer.name)
print("Using boundary layer:", boundary_layer.name)
print("Using observed SFI field:", z_field)

# ------------------------------------------------------------
# 4. COPY INPUT LAYERS TO SAFE FEATURE CLASSES
# ------------------------------------------------------------

for item in [points_fc, boundary_fc]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

arcpy.management.CopyFeatures(points_layer, points_fc)
arcpy.management.CopyFeatures(boundary_layer, boundary_fc)

boundary_extent = arcpy.Describe(boundary_fc).extent
arcpy.env.extent = boundary_extent

print("Copied points:", points_fc)
print("Copied boundary:", boundary_fc)

# ------------------------------------------------------------
# 5. READ OBSERVED VALUES
# ------------------------------------------------------------

oid_field = arcpy.Describe(points_fc).OIDFieldName

records = []

with arcpy.da.SearchCursor(points_fc, [oid_field, z_field]) as cursor:
    for oid, value in cursor:
        if value is not None:
            records.append((oid, float(value)))

if len(records) < 10:
    raise Exception("Too few valid observed Overall SFI values.")

values = np.array([r[1] for r in records], dtype=float)

print("Number of valid observations:", len(records))
print("Observed SFI range:", round(values.min(), 4), "-", round(values.max(), 4))

# ------------------------------------------------------------
# 6. INTERPOLATION FUNCTION
# ------------------------------------------------------------

def create_interpolation(method_name, training_layer, output_raster):

    if arcpy.Exists(output_raster):
        arcpy.management.Delete(output_raster)

    if method_name == "IDW":
        raster = Idw(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        krig_model = KrigingModelOrdinary("SPHERICAL")
        raster = Kriging(
            in_point_features=training_layer,
            z_field=z_field,
            kriging_model=krig_model,
            cell_size=cell_size
        )

    elif method_name == "NN":
        raster = NaturalNeighbor(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size
        )

    else:
        raise ValueError("Unknown interpolation method.")

    raster.save(output_raster)
    return output_raster

# ------------------------------------------------------------
# 7. LEAVE-ONE-OUT CROSS-VALIDATION
# ------------------------------------------------------------

methods = ["IDW", "OK", "NN"]
all_predictions = {m: {} for m in methods}
scratch_gdb = arcpy.env.scratchGDB

for method in methods:
    print("\nRunning LOOCV:", method)

    for oid, obs in records:

        train_sql = f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} <> {oid}"
        test_sql = f"{arcpy.AddFieldDelimiters(points_fc, oid_field)} = {oid}"

        train_layer = f"fig2_train_{method}_{oid}"
        test_layer = f"fig2_test_{method}_{oid}"

        temp_raster = os.path.join(scratch_gdb, f"fig2_r_{method}_{oid}")
        temp_extract = os.path.join(scratch_gdb, f"fig2_e_{method}_{oid}")

        try:
            arcpy.management.MakeFeatureLayer(points_fc, train_layer, train_sql)
            arcpy.management.MakeFeatureLayer(points_fc, test_layer, test_sql)

            create_interpolation(method, train_layer, temp_raster)

            if arcpy.Exists(temp_extract):
                arcpy.management.Delete(temp_extract)

            ExtractValuesToPoints(
                in_point_features=test_layer,
                in_raster=temp_raster,
                out_point_features=temp_extract,
                interpolate_values="INTERPOLATE",
                add_attributes="VALUE_ONLY"
            )

            pred = None
            with arcpy.da.SearchCursor(temp_extract, ["RASTERVALU"]) as cur:
                for row in cur:
                    pred = row[0]

            if pred is not None and pred != -9999:
                all_predictions[method][oid] = (obs, float(pred))

        except Exception as e:
            print(f"Warning: {method}, OID {oid} failed:", e)

        finally:
            for item in [train_layer, test_layer, temp_raster, temp_extract]:
                try:
                    if arcpy.Exists(item):
                        arcpy.management.Delete(item)
                except:
                    pass

    print(method, "valid predictions:", len(all_predictions[method]))

# ------------------------------------------------------------
# 8. FAIR COMPARISON USING COMMON POINTS
# ------------------------------------------------------------

common_oids = set(all_predictions["IDW"].keys())

for method in methods:
    common_oids = common_oids.intersection(set(all_predictions[method].keys()))

common_oids = sorted(list(common_oids))

if len(common_oids) < 10:
    raise Exception("Too few common validation points. Check point distribution.")

print("\nCommon validation points:", len(common_oids))

def calc_stats(obs, pred):

    obs = np.array(obs, dtype=float)
    pred = np.array(pred, dtype=float)

    residual = pred - obs

    n = len(obs)
    me = np.mean(residual)
    mae = np.mean(np.abs(residual))
    rmse = math.sqrt(np.mean(residual ** 2))

    ss_res = np.sum((obs - pred) ** 2)
    ss_tot = np.sum((obs - np.mean(obs)) ** 2)

    r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else np.nan
    rpd = np.std(obs, ddof=1) / rmse if rmse != 0 else np.nan

    return {
        "n": n,
        "ME": me,
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "RPD": rpd
    }

stats = []

for method in methods:
    obs_list = []
    pred_list = []

    for oid in common_oids:
        obs, pred = all_predictions[method][oid]
        obs_list.append(obs)
        pred_list.append(pred)

    s = calc_stats(obs_list, pred_list)
    s["Method"] = method
    stats.append(s)

stats_sorted = sorted(
    stats,
    key=lambda x: (x["RMSE"], x["MAE"], -x["R2"], -x["RPD"])
)

best_method = stats_sorted[0]["Method"]

print("\nInterpolation comparison results:")
for s in stats_sorted:
    print(
        s["Method"],
        "| n =", s["n"],
        "| ME =", round(s["ME"], 6),
        "| MAE =", round(s["MAE"], 6),
        "| RMSE =", round(s["RMSE"], 6),
        "| R2 =", round(s["R2"], 6),
        "| RPD =", round(s["RPD"], 6)
    )

print("\nBest selected method:", best_method)

# Save statistics table for record
with open(comparison_csv, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["Method", "n", "ME", "MAE", "RMSE", "R2", "RPD"])
    for s in stats_sorted:
        writer.writerow([
            s["Method"],
            s["n"],
            round(s["ME"], 8),
            round(s["MAE"], 8),
            round(s["RMSE"], 8),
            round(s["R2"], 8),
            round(s["RPD"], 8)
        ])

with open(best_method_txt, "w") as f:
    f.write("Best interpolation method for observed Overall SFI\n")
    f.write(f"Selected method: {best_method}\n\n")
    for s in stats_sorted:
        f.write(
            f"{s['Method']}: n={s['n']}, ME={s['ME']:.8f}, "
            f"MAE={s['MAE']:.8f}, RMSE={s['RMSE']:.8f}, "
            f"R2={s['R2']:.8f}, RPD={s['RPD']:.8f}\n"
        )

# ------------------------------------------------------------
# 9. CREATE FINAL BEST INTERPOLATION RASTER
# ------------------------------------------------------------

all_points_layer = "fig2_all_points_for_best_interpolation"

if arcpy.Exists(all_points_layer):
    arcpy.management.Delete(all_points_layer)

arcpy.management.MakeFeatureLayer(points_fc, all_points_layer)

create_interpolation(best_method, all_points_layer, best_raw_raster)

if arcpy.Exists(best_clipped_raster):
    arcpy.management.Delete(best_clipped_raster)

clipped = ExtractByMask(
    in_raster=best_raw_raster,
    in_mask_data=boundary_fc
)

clipped.save(best_clipped_raster)
arcpy.management.CalculateStatistics(best_clipped_raster)

print("\nBest clipped raster created:")
print(best_clipped_raster)

# ------------------------------------------------------------
# 10. CREATE CLASSIFIED INTEGER RASTER
# This is the important part: class raster, not stretch raster.
# ------------------------------------------------------------

if arcpy.Exists(classified_raster):
    arcpy.management.Delete(classified_raster)

remap = RemapRange([
    [0.00, 0.72, 1],
    [0.72, 0.77, 2],
    [0.77, 0.82, 3],
    [0.82, 0.87, 4],
    [0.87, 1.00, 5]
])

classified = Reclassify(
    in_raster=best_clipped_raster,
    reclass_field="Value",
    remap=remap,
    missing_values="NODATA"
)

classified.save(classified_raster)
arcpy.management.BuildRasterAttributeTable(classified_raster, "Overwrite")
arcpy.management.CalculateStatistics(classified_raster)

# Add class name field
existing_fields = [f.name for f in arcpy.ListFields(classified_raster)]

if "ClassName" not in existing_fields:
    arcpy.management.AddField(classified_raster, "ClassName", "TEXT", field_length=80)

class_names = {
    1: "0.67-0.72 Lower local SFI",
    2: "0.72-0.77 Low-moderate SFI",
    3: "0.77-0.82 Moderate SFI",
    4: "0.82-0.87 High SFI",
    5: "0.87-0.93 Highest local SFI"
}

with arcpy.da.UpdateCursor(classified_raster, ["Value", "ClassName"]) as cursor:
    for value, name in cursor:
        if value in class_names:
            cursor.updateRow([value, class_names[value]])

print("Classified raster created:")
print(classified_raster)

# ------------------------------------------------------------
# 11. ADD FINAL LAYERS TO CONTENTS PANEL
# ------------------------------------------------------------

final_map_name = "FIG_2_OBSERVED_OVERALL_SFI_FINAL"

existing_maps = aprx.listMaps(final_map_name)

if len(existing_maps) > 0:
    final_map = existing_maps[0]

    # Remove previous Fig 2 layers only
    for lyr in final_map.listLayers():
        try:
            final_map.removeLayer(lyr)
        except:
            pass
else:
    final_map = aprx.createMap(final_map_name)

# Add layers
class_layer = final_map.addDataFromPath(classified_raster)
class_layer.name = "Observed Overall SFI classified"

boundary_final = final_map.addDataFromPath(boundary_fc)
boundary_final.name = "Study boundary"

points_final = final_map.addDataFromPath(points_fc)
points_final.name = "Soil sampling points"

# Remove default basemap layers if present
for lyr in final_map.listLayers():
    try:
        if lyr.isBasemapLayer:
            final_map.removeLayer(lyr)
    except:
        pass

# ------------------------------------------------------------
# 12. APPLY CLASS COLOURS TO CLASSIFIED RASTER
# ------------------------------------------------------------

sym = class_layer.symbology
sym.updateColorizer("RasterUniqueValueColorizer")

# Apply symbology
class_layer.symbology = sym

# Reopen symbology after update
sym = class_layer.symbology

# Some ArcGIS Pro versions expose groups/items differently.
# This block is defensive.
class_colors = {
    1: {"RGB": [215, 48, 39, 100]},
    2: {"RGB": [252, 141, 89, 100]},
    3: {"RGB": [254, 224, 139, 100]},
    4: {"RGB": [145, 207, 96, 100]},
    5: {"RGB": [26, 152, 80, 100]}
}

class_labels = {
    1: "0.67-0.72 Lower local SFI",
    2: "0.72-0.77 Low-moderate SFI",
    3: "0.77-0.82 Moderate SFI",
    4: "0.82-0.87 High SFI",
    5: "0.87-0.93 Highest local SFI"
}

try:
    for group in sym.colorizer.groups:
        for item in group.items:
            try:
                val = int(item.values[0][0])
                if val in class_colors:
                    item.label = class_labels[val]
                    item.color = class_colors[val]
            except:
                pass

    class_layer.symbology = sym

except Exception as e:
    print("Unique value colour assignment warning:", e)
    print("Layer was added. If colours do not apply automatically, use Symbology > Unique Values > Value.")

# ------------------------------------------------------------
# 13. STYLE BOUNDARY AND POINTS
# ------------------------------------------------------------

# Boundary: no fill, black outline
try:
    sym_b = boundary_final.symbology
    sym_b.updateRenderer("SimpleRenderer")
    sym_b.renderer.symbol.color = {"RGB": [255, 255, 255, 0]}
    sym_b.renderer.symbol.outlineColor = {"RGB": [0, 0, 0, 100]}
    sym_b.renderer.symbol.outlineWidth = 1.2
    boundary_final.symbology = sym_b
except Exception as e:
    print("Boundary styling warning:", e)

# Points: small black points
try:
    sym_p = points_final.symbology
    sym_p.updateRenderer("SimpleRenderer")
    sym_p.renderer.symbol.color = {"RGB": [0, 0, 0, 100]}
    sym_p.renderer.symbol.size = 3
    points_final.symbology = sym_p
except Exception as e:
    print("Point styling warning:", e)

# ------------------------------------------------------------
# 14. SET MAP EXTENT AND SAVE
# ------------------------------------------------------------

try:
    aprx.save()
except:
    pass

print("\nDONE.")
print("Open this map in Contents panel:")
print(final_map_name)

print("\nBest interpolation method:")
print(best_method)

print("\nCreated layers:")
print("1. Observed Overall SFI classified")
print("2. Study boundary")
print("3. Soil sampling points")

print("\nImportant outputs saved in workspace:")
print("Best clipped raster:", best_clipped_raster)
print("Classified raster:", classified_raster)
print("Statistics CSV:", comparison_csv)
print("Best method text:", best_method_txt)

print("\nFor final figure:")
print("Use the map named FIG_2_OBSERVED_OVERALL_SFI_FINAL.")
print("Add north arrow, scale bar and legend manually from Insert tab if needed.")
print("The raster is classified, so it will not appear as grey stretched colour.")

# ============================================================
# OBSERVED OVERALL SFI INTERPOLATION ANALYSIS
# ArcGIS Pro Python code
#
# Input:
# soil_points_hanumakonda_wgs84
# hanumakonda_study_boundary_500m
#
# Tasks:
# 1. Compare IDW, Ordinary Kriging and Natural Neighbor
# 2. Select best method using lowest RMSE -> lowest MAE -> highest R2 -> highest RPD
# 3. Create final raster using best method
# 4. Clip to boundary
# 5. Create classified integer raster, not stretched raster
# 6. Add clean coloured layers to ArcGIS Pro Contents panel
# ============================================================

import arcpy
import os
import math
import csv
import numpy as np

from arcpy.sa import (
    Idw,
    Kriging,
    KrigingModelOrdinary,
    NaturalNeighbor,
    ExtractValuesToPoints,
    ExtractByMask,
    Reclassify,
    RemapRange
)

# ------------------------------------------------------------
# 1. USER INPUTS
# ------------------------------------------------------------

soil_points_source = r"D:\SR University\Scieitific Reports\Sci\Sci.gdb\soil_points_hanumakonda_wgs84"
boundary_source = r"D:\SR University\Scieitific Reports\Sci\Sci.gdb\hanumakonda_study_boundary_500m"

# Change this only if your observed SFI field has another name.
observed_sfi_field = "Obs_Overall"

# Backup candidate names. Code will search these if Obs_Overall is not found.
observed_sfi_candidates = [
    "Obs_Overall",
    "Overall_SFI",
    "OverallSFI",
    "Observed_SFI",
    "Obs_SFI",
    "SFI",
    "SFI_Total",
    "SFI_Total_Score"
]

out_folder = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_best_interpolation_analysis"
os.makedirs(out_folder, exist_ok=True)

cell_size = 30

# Projection for interpolation
utm44n = arcpy.SpatialReference(32644)

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = utm44n
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

# ------------------------------------------------------------
# 2. WORKSPACE AND OUTPUTS
# ------------------------------------------------------------

work_gdb = os.path.join(out_folder, "Fig2_best_interpolation_analysis.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(out_folder, "Fig2_best_interpolation_analysis.gdb")

points_utm = os.path.join(work_gdb, "soil_points_utm44n_for_fig2")
boundary_utm = os.path.join(work_gdb, "hanumakonda_boundary_utm44n_for_fig2")

best_raw_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_best_raw")
best_clipped_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_best_clipped")
classified_raster = os.path.join(work_gdb, "Fig2_Observed_Overall_SFI_classified")

comparison_csv = os.path.join(out_folder, "Fig2_IDW_OK_NN_LOOCV_statistics.csv")
best_method_txt = os.path.join(out_folder, "Fig2_best_interpolation_method.txt")
colormap_file = os.path.join(out_folder, "Fig2_SFI_class_colormap.clr")

# ------------------------------------------------------------
# 3. CHECK INPUTS
# ------------------------------------------------------------

if not arcpy.Exists(soil_points_source):
    raise Exception("Soil point feature class not found:\n" + soil_points_source)

if not arcpy.Exists(boundary_source):
    raise Exception("Boundary feature class not found:\n" + boundary_source)

print("Input soil points:", soil_points_source)
print("Input boundary:", boundary_source)

# ------------------------------------------------------------
# 4. PROJECT POINTS AND BOUNDARY TO UTM 44N
# ------------------------------------------------------------

for item in [points_utm, boundary_utm]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

points_desc = arcpy.Describe(soil_points_source)
boundary_desc = arcpy.Describe(boundary_source)

points_sr = points_desc.spatialReference
boundary_sr = boundary_desc.spatialReference

if points_sr.factoryCode == 32644:
    arcpy.management.CopyFeatures(soil_points_source, points_utm)
else:
    arcpy.management.Project(
        in_dataset=soil_points_source,
        out_dataset=points_utm,
        out_coor_system=utm44n
    )

if boundary_sr.factoryCode == 32644:
    arcpy.management.CopyFeatures(boundary_source, boundary_utm)
else:
    arcpy.management.Project(
        in_dataset=boundary_source,
        out_dataset=boundary_utm,
        out_coor_system=utm44n
    )

print("Projected/copied points:", points_utm)
print("Projected/copied boundary:", boundary_utm)

# ------------------------------------------------------------
# 5. DETECT OBSERVED SFI FIELD
# ------------------------------------------------------------

field_names = [f.name for f in arcpy.ListFields(points_utm)]

z_field = None

if observed_sfi_field in field_names:
    z_field = observed_sfi_field
else:
    for candidate in observed_sfi_candidates:
        if candidate in field_names:
            z_field = candidate
            break

if z_field is None:
    raise Exception(
        "Observed SFI field not found in your soil point source.\n\n"
        "Available fields are:\n"
        + str(field_names)
        + "\n\nAdd an observed SFI field to this point feature class, or use the mapping point layer "
        "that already contains Obs_Overall."
    )

print("Using observed SFI field:", z_field)

# ------------------------------------------------------------
# 6. READ OBSERVED VALUES
# ------------------------------------------------------------

oid_field = arcpy.Describe(points_utm).OIDFieldName

records = []

with arcpy.da.SearchCursor(points_utm, [oid_field, z_field]) as cursor:
    for oid, value in cursor:
        if value is not None:
            try:
                records.append((oid, float(value)))
            except:
                pass

if len(records) < 10:
    raise Exception("Too few valid observed SFI values in field: " + z_field)

values = np.array([r[1] for r in records], dtype=float)

print("Number of valid observations:", len(records))
print("Observed SFI range:", round(values.min(), 4), "-", round(values.max(), 4))

# ------------------------------------------------------------
# 7. SET SAFE ENVIRONMENT
# ------------------------------------------------------------

boundary_extent = arcpy.Describe(boundary_utm).extent
arcpy.env.extent = boundary_extent
arcpy.env.snapRaster = None

# Do not set arcpy.env.mask here. ExtractByMask is safer.

# ------------------------------------------------------------
# 8. INTERPOLATION FUNCTION
# ------------------------------------------------------------

def create_interpolation(method_name, training_layer, output_raster):

    if arcpy.Exists(output_raster):
        arcpy.management.Delete(output_raster)

    if method_name == "IDW":
        raster = Idw(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        kriging_model = KrigingModelOrdinary("SPHERICAL")
        raster = Kriging(
            in_point_features=training_layer,
            z_field=z_field,
            kriging_model=kriging_model,
            cell_size=cell_size
        )

    elif method_name == "NN":
        raster = NaturalNeighbor(
            in_point_features=training_layer,
            z_field=z_field,
            cell_size=cell_size
        )

    else:
        raise ValueError("Unknown interpolation method: " + method_name)

    raster.save(output_raster)
    return output_raster

# ------------------------------------------------------------
# 9. LEAVE-ONE-OUT CROSS-VALIDATION
# ------------------------------------------------------------

methods = ["IDW", "OK", "NN"]
all_predictions = {method: {} for method in methods}

scratch_gdb = arcpy.env.scratchGDB

for method in methods:
    print("\nRunning LOOCV for:", method)

    for oid, obs in records:

        train_sql = f"{arcpy.AddFieldDelimiters(points_utm, oid_field)} <> {oid}"
        test_sql = f"{arcpy.AddFieldDelimiters(points_utm, oid_field)} = {oid}"

        train_layer = f"fig2_train_{method}_{oid}"
        test_layer = f"fig2_test_{method}_{oid}"

        temp_raster = os.path.join(scratch_gdb, f"fig2_r_{method}_{oid}")
        temp_extract = os.path.join(scratch_gdb, f"fig2_e_{method}_{oid}")

        try:
            arcpy.management.MakeFeatureLayer(points_utm, train_layer, train_sql)
            arcpy.management.MakeFeatureLayer(points_utm, test_layer, test_sql)

            create_interpolation(method, train_layer, temp_raster)

            if arcpy.Exists(temp_extract):
                arcpy.management.Delete(temp_extract)

            ExtractValuesToPoints(
                in_point_features=test_layer,
                in_raster=temp_raster,
                out_point_features=temp_extract,
                interpolate_values="INTERPOLATE",
                add_attributes="VALUE_ONLY"
            )

            pred = None

            with arcpy.da.SearchCursor(temp_extract, ["RASTERVALU"]) as cur:
                for row in cur:
                    pred = row[0]

            if pred is not None and pred != -9999:
                all_predictions[method][oid] = (obs, float(pred))

        except Exception as e:
            print(f"Warning: {method}, OID {oid} failed:", e)

        finally:
            for item in [train_layer, test_layer, temp_raster, temp_extract]:
                try:
                    if arcpy.Exists(item):
                        arcpy.management.Delete(item)
                except:
                    pass

    print(method, "valid predictions:", len(all_predictions[method]))

# ------------------------------------------------------------
# 10. FAIR COMPARISON USING COMMON VALIDATION POINTS
# ------------------------------------------------------------

common_oids = set(all_predictions["IDW"].keys())

for method in methods:
    common_oids = common_oids.intersection(set(all_predictions[method].keys()))

common_oids = sorted(list(common_oids))

if len(common_oids) < 10:
    raise Exception(
        "Too few common validation points across IDW, OK and NN. "
        "Natural Neighbor may be failing at edge points."
    )

print("\nCommon validation points used:", len(common_oids))

def calc_stats(obs, pred):

    obs = np.array(obs, dtype=float)
    pred = np.array(pred, dtype=float)

    residual = pred - obs

    n = len(obs)
    me = np.mean(residual)
    mae = np.mean(np.abs(residual))
    rmse = math.sqrt(np.mean(residual ** 2))

    ss_res = np.sum((obs - pred) ** 2)
    ss_tot = np.sum((obs - np.mean(obs)) ** 2)

    r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else np.nan
    rpd = np.std(obs, ddof=1) / rmse if rmse != 0 else np.nan

    return {
        "n": n,
        "ME": me,
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "RPD": rpd
    }

stats = []

for method in methods:

    obs_list = []
    pred_list = []

    for oid in common_oids:
        obs, pred = all_predictions[method][oid]
        obs_list.append(obs)
        pred_list.append(pred)

    s = calc_stats(obs_list, pred_list)
    s["Method"] = method
    stats.append(s)

# Selection rule:
# lowest RMSE -> lowest MAE -> highest R2 -> highest RPD
stats_sorted = sorted(
    stats,
    key=lambda x: (x["RMSE"], x["MAE"], -x["R2"], -x["RPD"])
)

best_method = stats_sorted[0]["Method"]

print("\nInterpolation comparison results:")
for s in stats_sorted:
    print(
        s["Method"],
        "| n =", s["n"],
        "| ME =", round(s["ME"], 6),
        "| MAE =", round(s["MAE"], 6),
        "| RMSE =", round(s["RMSE"], 6),
        "| R2 =", round(s["R2"], 6),
        "| RPD =", round(s["RPD"], 6)
    )

print("\nBest selected interpolation method:", best_method)

# Save comparison table
with open(comparison_csv, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["Method", "n", "ME", "MAE", "RMSE", "R2", "RPD", "Selection_rule"])
    for s in stats_sorted:
        writer.writerow([
            s["Method"],
            s["n"],
            round(s["ME"], 8),
            round(s["MAE"], 8),
            round(s["RMSE"], 8),
            round(s["R2"], 8),
            round(s["RPD"], 8),
            "lowest RMSE, lowest MAE, highest R2, highest RPD"
        ])

with open(best_method_txt, "w") as f:
    f.write("Observed Overall SFI interpolation comparison\n")
    f.write("Selection rule: lowest RMSE -> lowest MAE -> highest R2 -> highest RPD\n\n")
    f.write(f"Selected method: {best_method}\n\n")

    for s in stats_sorted:
        f.write(
            f"{s['Method']}: n={s['n']}, ME={s['ME']:.8f}, "
            f"MAE={s['MAE']:.8f}, RMSE={s['RMSE']:.8f}, "
            f"R2={s['R2']:.8f}, RPD={s['RPD']:.8f}\n"
        )

print("Saved statistics CSV:", comparison_csv)
print("Saved best-method text:", best_method_txt)

# ------------------------------------------------------------
# 11. CREATE FINAL BEST INTERPOLATED RASTER
# ------------------------------------------------------------

all_points_layer = "fig2_all_points_best_interpolation"

if arcpy.Exists(all_points_layer):
    arcpy.management.Delete(all_points_layer)

arcpy.management.MakeFeatureLayer(points_utm, all_points_layer)

create_interpolation(best_method, all_points_layer, best_raw_raster)

if arcpy.Exists(best_clipped_raster):
    arcpy.management.Delete(best_clipped_raster)

clipped = ExtractByMask(
    in_raster=best_raw_raster,
    in_mask_data=boundary_utm
)

clipped.save(best_clipped_raster)
arcpy.management.CalculateStatistics(best_clipped_raster)

print("\nBest clipped raster created:")
print(best_clipped_raster)

# ------------------------------------------------------------
# 12. CREATE CLASSIFIED INTEGER RASTER
# ------------------------------------------------------------

if arcpy.Exists(classified_raster):
    arcpy.management.Delete(classified_raster)

# Fixed local classes for observed Overall SFI.
# These classes are for visual contrast and local fertility zoning.
remap = RemapRange([
    [0.00, 0.72, 1],
    [0.72, 0.77, 2],
    [0.77, 0.82, 3],
    [0.82, 0.87, 4],
    [0.87, 1.00, 5]
])

classified = Reclassify(
    in_raster=best_clipped_raster,
    reclass_field="Value",
    remap=remap,
    missing_values="NODATA"
)

classified.save(classified_raster)

arcpy.management.BuildRasterAttributeTable(classified_raster, "Overwrite")
arcpy.management.CalculateStatistics(classified_raster)

# Add class name field for legend interpretation
existing_fields = [f.name for f in arcpy.ListFields(classified_raster)]

if "ClassName" not in existing_fields:
    arcpy.management.AddField(classified_raster, "ClassName", "TEXT", field_length=90)

class_names = {
    1: "0.67-0.72 Lower local SFI",
    2: "0.72-0.77 Low-moderate SFI",
    3: "0.77-0.82 Moderate SFI",
    4: "0.82-0.87 High SFI",
    5: "0.87-0.93 Highest local SFI"
}

with arcpy.da.UpdateCursor(classified_raster, ["Value", "ClassName"]) as cursor:
    for value, class_name in cursor:
        if value in class_names:
            cursor.updateRow([value, class_names[value]])

print("Classified integer raster created:")
print(classified_raster)

# ------------------------------------------------------------
# 13. ADD COLORMAP TO CLASSIFIED RASTER
# ------------------------------------------------------------

with open(colormap_file, "w") as f:
    f.write("1 215 48 39\n")     # red
    f.write("2 252 141 89\n")    # orange
    f.write("3 254 224 139\n")   # yellow
    f.write("4 145 207 96\n")    # light green
    f.write("5 26 152 80\n")     # dark green

try:
    arcpy.management.AddColormap(
        in_raster=classified_raster,
        in_template_raster="",
        input_CLR_file=colormap_file
    )
    print("Colormap added:", colormap_file)
except Exception as e:
    print("Colormap warning:", e)

# ------------------------------------------------------------
# 14. ADD CLEAN LAYERS TO CONTENTS PANEL
# ------------------------------------------------------------

aprx = arcpy.mp.ArcGISProject("CURRENT")

final_map_name = "FIG_2_OBSERVED_OVERALL_SFI_FINAL"

existing_maps = aprx.listMaps(final_map_name)

if len(existing_maps) > 0:
    final_map = existing_maps[0]

    # Remove old layers from this map
    for lyr in final_map.listLayers():
        try:
            final_map.removeLayer(lyr)
        except:
            pass
else:
    final_map = aprx.createMap(final_map_name)

# Add final layers
class_layer = final_map.addDataFromPath(classified_raster)
class_layer.name = "Observed Overall SFI classified"

boundary_layer_final = final_map.addDataFromPath(boundary_utm)
boundary_layer_final.name = "Study boundary"

points_layer_final = final_map.addDataFromPath(points_utm)
points_layer_final.name = "Soil sampling points"

# Remove basemap layers if present
for lyr in final_map.listLayers():
    try:
        if lyr.isBasemapLayer:
            final_map.removeLayer(lyr)
    except:
        pass

# ------------------------------------------------------------
# 15. APPLY RASTER UNIQUE VALUE COLOURS IN CONTENTS PANEL
# ------------------------------------------------------------

class_colors = {
    1: {"RGB": [215, 48, 39, 100]},
    2: {"RGB": [252, 141, 89, 100]},
    3: {"RGB": [254, 224, 139, 100]},
    4: {"RGB": [145, 207, 96, 100]},
    5: {"RGB": [26, 152, 80, 100]}
}

class_labels = {
    1: "0.67-0.72 Lower local SFI",
    2: "0.72-0.77 Low-moderate SFI",
    3: "0.77-0.82 Moderate SFI",
    4: "0.82-0.87 High SFI",
    5: "0.87-0.93 Highest local SFI"
}

try:
    sym = class_layer.symbology
    sym.updateColorizer("RasterUniqueValueColorizer")
    class_layer.symbology = sym

    sym = class_layer.symbology

    for group in sym.colorizer.groups:
        for item in group.items:
            try:
                val = int(item.values[0][0])
                if val in class_colors:
                    item.label = class_labels[val]
                    item.color = class_colors[val]
            except:
                pass

    class_layer.symbology = sym
    print("Unique-value class colours applied.")

except Exception as e:
    print("Symbology warning:", e)
    print("The raster still has a colormap. If needed, manually set Symbology > Unique Values > Value.")

# ------------------------------------------------------------
# 16. STYLE BOUNDARY AND POINTS
# ------------------------------------------------------------

# Boundary: transparent fill, black outline
try:
    sym_b = boundary_layer_final.symbology
    sym_b.updateRenderer("SimpleRenderer")
    sym_b.renderer.symbol.color = {"RGB": [255, 255, 255, 0]}
    sym_b.renderer.symbol.outlineColor = {"RGB": [0, 0, 0, 100]}
    sym_b.renderer.symbol.outlineWidth = 1.3
    boundary_layer_final.symbology = sym_b
except Exception as e:
    print("Boundary styling warning:", e)

# Points: small black dots
try:
    sym_p = points_layer_final.symbology
    sym_p.updateRenderer("SimpleRenderer")
    sym_p.renderer.symbol.color = {"RGB": [0, 0, 0, 100]}
    sym_p.renderer.symbol.size = 3
    points_layer_final.symbology = sym_p
except Exception as e:
    print("Point styling warning:", e)

# ------------------------------------------------------------
# 17. SAVE PROJECT AND FINISH
# ------------------------------------------------------------

aprx.save()
arcpy.CheckInExtension("Spatial")

print("\nDONE.")
print("Open this map in the Contents panel:")
print(final_map_name)

print("\nBest interpolation method:")
print(best_method)

print("\nLayers added:")
print("1. Observed Overall SFI classified")
print("2. Study boundary")
print("3. Soil sampling points")

print("\nOutput rasters:")
print("Best clipped raster:", best_clipped_raster)
print("Classified integer raster:", classified_raster)

