import matplotlib.pyplot as plt

from matplotlib.colors import ListedColormap, BoundaryNorm
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter, MaxNLocator

from arcpy.sa import Idw, ExtractByMask, Reclassify, RemapRange

# ------------------------------------------------------------
# 1. INPUTS
# ------------------------------------------------------------

csv_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_macro_micro_SFI_dataset.csv"

boundary_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_best_interpolation_analysis\Fig2_best_interpolation_analysis.gdb\hanumakonda_boundary_utm44n_for_fig2"

x_field = "Longitude"
y_field = "Latitude"
sfi_field = "Overall_SFI"

cell_size = 30
dpi = 600

# Safe no-space folder
safe_root = r"D:\GIS_TMP\Fig2_IDW_Separate_Files"
outputs_folder = os.path.join(safe_root, "outputs")
os.makedirs(outputs_folder, exist_ok=True)

# ------------------------------------------------------------
# 2. OUTPUT FILES
# ------------------------------------------------------------

map_only_tif = os.path.join(outputs_folder, "Fig_2_MAP_ONLY_Observed_Overall_SFI_IDW.tif")
legend_only_tif = os.path.join(outputs_folder, "Fig_2_LEGEND_ONLY_Observed_Overall_SFI_IDW.tif")
north_arrow_tif = os.path.join(outputs_folder, "Fig_2_NORTH_ARROW_ONLY.tif")
scale_bar_tif = os.path.join(outputs_folder, "Fig_2_SCALE_BAR_ONLY.tif")

classified_raster_out = os.path.join(outputs_folder, "Fig_2_Observed_Overall_SFI_IDW_classified.tif")

# ------------------------------------------------------------
# 3. ARCGIS ENVIRONMENT
# ------------------------------------------------------------

wgs84 = arcpy.SpatialReference(4326)
utm44n = arcpy.SpatialReference(32644)

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = utm44n
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

work_gdb = os.path.join(safe_root, "work.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(safe_root, "work.gdb")

arcpy.env.workspace = work_gdb
arcpy.env.scratchWorkspace = work_gdb

# ------------------------------------------------------------
# 4. COPY CSV TO SAFE PATH
# ------------------------------------------------------------

local_csv = os.path.join(safe_root, "Hanumakonda_macro_micro_SFI_dataset.csv")

if os.path.exists(local_csv):
    os.remove(local_csv)

shutil.copy2(csv_source, local_csv)

print("CSV copied to safe path:")
print(local_csv)

# ------------------------------------------------------------
# 5. CREATE POINTS AND PROJECT TO UTM 44N
# ------------------------------------------------------------

points_wgs84 = os.path.join(work_gdb, "fig2_points_wgs84")
points_utm = os.path.join(work_gdb, "fig2_points_utm44n")
boundary_utm = os.path.join(work_gdb, "fig2_boundary_utm44n")

for item in [points_wgs84, points_utm, boundary_utm]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

# Check fields
csv_fields = [f.name for f in arcpy.ListFields(local_csv)]

for fld in [x_field, y_field, sfi_field]:
    if fld not in csv_fields:
        raise Exception(f"Field not found: {fld}\nAvailable fields: {csv_fields}")

arcpy.management.XYTableToPoint(
    in_table=local_csv,
    out_feature_class=points_wgs84,
    x_field=x_field,
    y_field=y_field,
    coordinate_system=wgs84
)

arcpy.management.Project(
    in_dataset=points_wgs84,
    out_dataset=points_utm,
    out_coor_system=utm44n
)

# Boundary projection/copy
boundary_sr = arcpy.Describe(boundary_source).spatialReference

if boundary_sr.factoryCode == 32644:
    arcpy.management.CopyFeatures(boundary_source, boundary_utm)
else:
    arcpy.management.Project(
        in_dataset=boundary_source,
        out_dataset=boundary_utm,
        out_coor_system=utm44n
    )

print("Points and boundary prepared.")

# ------------------------------------------------------------
# 6. CREATE IDW RASTER AND CLIP TO BOUNDARY
# ------------------------------------------------------------

idw_raw = os.path.join(work_gdb, "Fig2_IDW_raw")
idw_clip = os.path.join(work_gdb, "Fig2_IDW_clipped")
idw_classified = os.path.join(work_gdb, "Fig2_IDW_classified")

for item in [idw_raw, idw_clip, idw_classified, classified_raster_out]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

arcpy.env.extent = arcpy.Describe(boundary_utm).extent

idw = Idw(
    in_point_features=points_utm,
    z_field=sfi_field,
    cell_size=cell_size,
    power=2
)

idw.save(idw_raw)

clipped = ExtractByMask(
    in_raster=idw_raw,
    in_mask_data=boundary_utm
)

clipped.save(idw_clip)
arcpy.management.CalculateStatistics(idw_clip)

print("IDW clipped raster created.")

# ------------------------------------------------------------
# 7. CREATE CLASSIFIED INTEGER RASTER
# ------------------------------------------------------------

remap = RemapRange([
    [0.00, 0.72, 1],
    [0.72, 0.77, 2],
    [0.77, 0.82, 3],
    [0.82, 0.87, 4],
    [0.87, 1.00, 5]
])

classified = Reclassify(
    in_raster=idw_clip,
    reclass_field="Value",
    remap=remap,
    missing_values="NODATA"
)

classified.save(idw_classified)
arcpy.management.BuildRasterAttributeTable(idw_classified, "Overwrite")
arcpy.management.CalculateStatistics(idw_classified)

# Save a classified TIFF copy also
arcpy.management.CopyRaster(
    in_raster=idw_classified,
    out_rasterdataset=classified_raster_out,
    pixel_type="8_BIT_UNSIGNED"
)

print("Classified raster created:")
print(classified_raster_out)

# ------------------------------------------------------------
# 8. READ RASTER TO NUMPY FOR CLEAN MAP EXPORT
# ------------------------------------------------------------

nodata_value = -999999.0
ras = arcpy.Raster(idw_clip)

arr = arcpy.RasterToNumPyArray(
    ras,
    nodata_to_value=nodata_value
).astype("float64")

arr[arr <= nodata_value + 1] = np.nan

xmin = ras.extent.XMin
xmax = ras.extent.XMax
ymin = ras.extent.YMin
ymax = ras.extent.YMax
extent = [xmin, xmax, ymin, ymax]

class_arr = np.full(arr.shape, np.nan)

class_arr[(arr >= 0.00) & (arr < 0.72)] = 1
class_arr[(arr >= 0.72) & (arr < 0.77)] = 2
class_arr[(arr >= 0.77) & (arr < 0.82)] = 3
class_arr[(arr >= 0.82) & (arr < 0.87)] = 4
class_arr[(arr >= 0.87) & (arr <= 1.00)] = 5

masked_class_arr = np.ma.masked_invalid(class_arr)

# ------------------------------------------------------------
# 9. COLOURS AND LABELS
# ------------------------------------------------------------

class_colors = [
    (215/255, 48/255, 39/255),
    (252/255, 141/255, 89/255),
    (254/255, 224/255, 139/255),
    (145/255, 207/255, 96/255),
    (26/255, 152/255, 80/255)
]

class_labels = [
    "0.67-0.72  Lower local SFI",
    "0.72-0.77  Low-moderate SFI",
    "0.77-0.82  Moderate SFI",
    "0.82-0.87  High SFI",
    "0.87-0.93  Highest local SFI"
]

cmap = ListedColormap(class_colors)
cmap.set_bad("white")

norm = BoundaryNorm([0.5, 1.5, 2.5, 3.5, 4.5, 5.5], cmap.N)

legend_handles = [
    Patch(
        facecolor=class_colors[i],
        edgecolor="black",
        linewidth=0.5,
        label=class_labels[i]
    )
    for i in range(5)
]

# ------------------------------------------------------------
# 10. HELPER FUNCTIONS
# ------------------------------------------------------------

def save_tiff(fig, path):
    try:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white",
            pil_kwargs={"compression": "tiff_lzw"}
        )
    except TypeError:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white"
        )

def comma_formatter(x, pos):
    return f"{x:,.0f}"

def plot_boundary(ax):
    with arcpy.da.SearchCursor(boundary_utm, ["SHAPE@"]) as cursor:
        for row in cursor:
            geom = row[0]
            for part in geom:
                xs = []
                ys = []

                for pnt in part:
                    if pnt:
                        xs.append(pnt.X)
                        ys.append(pnt.Y)
                    else:
                        if len(xs) > 0:
                            ax.plot(xs, ys, color="black", linewidth=1.2, zorder=4)
                            xs = []
                            ys = []

                if len(xs) > 0:
                    ax.plot(xs, ys, color="black", linewidth=1.2, zorder=4)

def plot_points(ax):
    xs = []
    ys = []

    with arcpy.da.SearchCursor(points_utm, ["SHAPE@XY"]) as cursor:
        for row in cursor:
            x, y = row[0]
            xs.append(x)
            ys.append(y)

    ax.scatter(
        xs,
        ys,
        s=9,
        c="black",
        edgecolors="white",
        linewidths=0.25,
        zorder=5
    )

def style_axes(ax):
    ax.set_xlim(xmin, xmax)
    ax.set_ylim(ymin, ymax)
    ax.set_aspect("equal", adjustable="box")

    ax.set_xlabel("Easting (m, WGS 1984 UTM Zone 44N)", fontsize=10)
    ax.set_ylabel("Northing (m, WGS 1984 UTM Zone 44N)", fontsize=10)

    ax.xaxis.set_major_formatter(FuncFormatter(comma_formatter))
    ax.yaxis.set_major_formatter(FuncFormatter(comma_formatter))

    ax.xaxis.set_major_locator(MaxNLocator(5))
    ax.yaxis.set_major_locator(MaxNLocator(5))

    ax.tick_params(axis="x", labelsize=8, rotation=25)
    ax.tick_params(axis="y", labelsize=8)

    ax.grid(True, linestyle="--", linewidth=0.35, alpha=0.35)

    for spine in ax.spines.values():
        spine.set_linewidth(1.0)
        spine.set_color("black")

# ------------------------------------------------------------
# 11. EXPORT MAP ONLY FILE
# ------------------------------------------------------------

fig, ax = plt.subplots(figsize=(7.5, 6.5))

ax.imshow(
    masked_class_arr,
    cmap=cmap,
    norm=norm,
    extent=extent,
    origin="upper",
    interpolation="nearest",
    zorder=1
)

plot_boundary(ax)
plot_points(ax)
style_axes(ax)

ax.set_title(
    "Observed Overall Soil Fertility Index IDW",
    fontsize=13,
    fontweight="bold",
    pad=10
)

save_tiff(fig, map_only_tif)
plt.close(fig)

print("Map only saved:")
print(map_only_tif)

# ------------------------------------------------------------
