class_arr[(arr >= 0.72) & (arr < 0.77)] = 2
class_arr[(arr >= 0.77) & (arr < 0.82)] = 3
class_arr[(arr >= 0.82) & (arr < 0.87)] = 4
class_arr[(arr >= 0.87) & (arr <= 1.00)] = 5

