# ------------------------------------------------------------
# 18. FINISH
# ------------------------------------------------------------

arcpy.CheckInExtension("Spatial")

print("\nDONE. Fig. 4 separate files created:")
print("Map:", map_only_tif)
print("Legend:", legend_only_tif)
print("North arrow:", north_arrow_tif)
print("Scale bar:", scale_bar_tif)
print("Classified raster:", classified_raster_out)

# ============================================================
# FIG. 5 OBSERVED MNI ORDINARY KRIGING MAP
# Separate publication files:
# 1. Map only with longitude-latitude degree coordinates
# 2. Legend only
# 3. North arrow only
# 4. Scale bar only
# 5. Classified raster
#
# Input: Hanumakonda macro-micro SFI dataset
# Field used: MNI
# Interpolation: Ordinary Kriging
#
# Reason:
# OK was selected as best for MNI:
# RMSE = 0.0792, MAE = 0.0686, R2 = -0.0970, RPD = 0.9637
# ============================================================

import os

# ------------------------------------------------------------
# 0. FORCE SAFE NO-SPACE TEMP PATHS
# ------------------------------------------------------------

safe_root = r"D:\GIS_TMP\Fig5_Observed_MNI_OK"
safe_temp = r"D:\GIS_TMP\ArcTemp"

os.makedirs(safe_root, exist_ok=True)
os.makedirs(safe_temp, exist_ok=True)

os.environ["TEMP"] = safe_temp
os.environ["TMP"] = safe_temp
os.chdir(safe_root)

import arcpy
import shutil
import numpy as np

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from matplotlib.colors import ListedColormap, BoundaryNorm
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter, MaxNLocator

from arcpy.sa import (
    Kriging,
    KrigingModelOrdinary,
    ExtractByMask,
    Reclassify,
    RemapRange
)

# ------------------------------------------------------------
# 1. INPUTS
# ------------------------------------------------------------

csv_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_macro_micro_SFI_dataset.csv"

boundary_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_best_interpolation_analysis\Fig2_best_interpolation_analysis.gdb\hanumakonda_boundary_utm44n_for_fig2"

x_field = "Longitude"
y_field = "Latitude"
mni_field = "MNI"

cell_size = 30
dpi = 600

outputs_folder = os.path.join(safe_root, "outputs")
os.makedirs(outputs_folder, exist_ok=True)

# ------------------------------------------------------------
# 2. OUTPUT FILES
# ------------------------------------------------------------

map_only_tif = os.path.join(
    outputs_folder,
    "Fig_5_MAP_ONLY_Observed_MNI_OK_degree_coordinates.tif"
)

legend_only_tif = os.path.join(
    outputs_folder,
    "Fig_5_LEGEND_ONLY_Observed_MNI_OK.tif"
)

north_arrow_tif = os.path.join(
    outputs_folder,
    "Fig_5_NORTH_ARROW_ONLY.tif"
)

scale_bar_tif = os.path.join(
    outputs_folder,
    "Fig_5_SCALE_BAR_ONLY.tif"
)

classified_raster_out = os.path.join(
    outputs_folder,
    "Fig_5_Observed_MNI_OK_classified.tif"
)

raw_raster_out = os.path.join(
    outputs_folder,
    "Fig_5_Observed_MNI_OK_raw.tif"
)

# ------------------------------------------------------------
# 3. ARCGIS ENVIRONMENT
# ------------------------------------------------------------

wgs84 = arcpy.SpatialReference(4326)
utm44n = arcpy.SpatialReference(32644)

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = utm44n
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

work_gdb = os.path.join(safe_root, "work.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(safe_root, "work.gdb")

arcpy.env.workspace = work_gdb
arcpy.env.scratchWorkspace = work_gdb

# ------------------------------------------------------------
# 4. COPY CSV TO SAFE PATH
# ------------------------------------------------------------

local_csv = os.path.join(
    safe_root,
    "Hanumakonda_macro_micro_SFI_dataset.csv"
)

if os.path.exists(local_csv):
    os.remove(local_csv)

shutil.copy2(csv_source, local_csv)

print("CSV copied to safe path:")
print(local_csv)

# ------------------------------------------------------------
# 5. CREATE POINTS AND PROJECT TO UTM 44N
# ------------------------------------------------------------

points_wgs84 = os.path.join(work_gdb, "fig5_mni_points_wgs84")
points_utm = os.path.join(work_gdb, "fig5_mni_points_utm44n")
boundary_utm = os.path.join(work_gdb, "fig5_boundary_utm44n")

for item in [points_wgs84, points_utm, boundary_utm]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

csv_fields = [f.name for f in arcpy.ListFields(local_csv)]

for fld in [x_field, y_field, mni_field]:
    if fld not in csv_fields:
        raise Exception(
            f"Field not found: {fld}\nAvailable fields: {csv_fields}"
        )

arcpy.management.XYTableToPoint(
    in_table=local_csv,
    out_feature_class=points_wgs84,
    x_field=x_field,
    y_field=y_field,
    coordinate_system=wgs84
)

arcpy.management.Project(
    in_dataset=points_wgs84,
    out_dataset=points_utm,
    out_coor_system=utm44n
)

boundary_sr = arcpy.Describe(boundary_source).spatialReference

if boundary_sr.factoryCode == 32644:
    arcpy.management.CopyFeatures(
        boundary_source,
        boundary_utm
    )
else:
    arcpy.management.Project(
        in_dataset=boundary_source,
        out_dataset=boundary_utm,
        out_coor_system=utm44n
    )

print("MNI points and boundary prepared in UTM 44N.")

# ------------------------------------------------------------
# 6. CREATE ORDINARY KRIGING RASTER AND CLIP TO BOUNDARY
# ------------------------------------------------------------

ok_raw = os.path.join(work_gdb, "Fig5_Observed_MNI_OK_raw")
ok_clip = os.path.join(work_gdb, "Fig5_Observed_MNI_OK_clipped")
ok_classified = os.path.join(work_gdb, "Fig5_Observed_MNI_OK_classified")

for item in [ok_raw, ok_clip, ok_classified]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

for item in [classified_raster_out, raw_raster_out]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

arcpy.env.extent = arcpy.Describe(boundary_utm).extent

kriging_model = KrigingModelOrdinary("SPHERICAL")

ok_result = Kriging(
    in_point_features=points_utm,
    z_field=mni_field,
    kriging_model=kriging_model,
    cell_size=cell_size
)

ok_result.save(ok_raw)

