# ============================================================
# FIG. 6 PREDICTED MNI ORDINARY KRIGING MAP
# Separate publication files:
# 1. Map only with longitude-latitude degree coordinates
# 2. Legend only
# 3. North arrow only
# 4. Scale bar only
# 5. Raw predicted MNI OK raster
# 6. Classified predicted MNI OK raster
#
# Input: Regularized ML prediction CSV
# Target: MNI
# Model: ElasticNet
# Field used: Predicted
# Interpolation: Ordinary Kriging
#
# Reason:
# OK was selected as best interpolation method for observed MNI.
# MNI model was predicted using ElasticNet.
# ============================================================

import os

# ------------------------------------------------------------
# 0. FORCE SAFE NO-SPACE TEMP PATHS
# ------------------------------------------------------------

safe_root = r"D:\GIS_TMP\Fig6_Predicted_MNI_OK"
safe_temp = r"D:\GIS_TMP\ArcTemp"

os.makedirs(safe_root, exist_ok=True)
os.makedirs(safe_temp, exist_ok=True)

os.environ["TEMP"] = safe_temp
os.environ["TMP"] = safe_temp
os.chdir(safe_root)

import arcpy
import csv
import shutil
import numpy as np

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from matplotlib.colors import ListedColormap, BoundaryNorm
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter, MaxNLocator

from arcpy.sa import (
    Kriging,
    KrigingModelOrdinary,
    ExtractByMask,
    Reclassify,
    RemapRange
)

# ------------------------------------------------------------
# 1. INPUTS
# ------------------------------------------------------------

prediction_csv_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_SFI_regularized_ML_predictions.csv"

boundary_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_best_interpolation_analysis\Fig2_best_interpolation_analysis.gdb\hanumakonda_boundary_utm44n_for_fig2"

x_field = "Longitude"
y_field = "Latitude"

target_field_name = "MNI"

# The code accepts both ElasticNet and Elastic Net spelling
accepted_model_names = ["elasticnet", "elastic net"]

predicted_source_field = "Predicted"
predicted_field = "Predicted_MNI"

cell_size = 30
dpi = 600

outputs_folder = os.path.join(safe_root, "outputs")
os.makedirs(outputs_folder, exist_ok=True)

# ------------------------------------------------------------
# 2. OUTPUT FILES
# ------------------------------------------------------------

map_only_tif = os.path.join(
    outputs_folder,
    "Fig_6_MAP_ONLY_Predicted_MNI_ElasticNet_OK_degree_coordinates.tif"
)

legend_only_tif = os.path.join(
    outputs_folder,
    "Fig_6_LEGEND_ONLY_Predicted_MNI_ElasticNet_OK.tif"
)

north_arrow_tif = os.path.join(
    outputs_folder,
    "Fig_6_NORTH_ARROW_ONLY.tif"
)

scale_bar_tif = os.path.join(
    outputs_folder,
    "Fig_6_SCALE_BAR_ONLY.tif"
)

raw_raster_out = os.path.join(
    outputs_folder,
    "Fig_6_Predicted_MNI_ElasticNet_OK_raw.tif"
)

classified_raster_out = os.path.join(
    outputs_folder,
    "Fig_6_Predicted_MNI_ElasticNet_OK_classified.tif"
)

filtered_prediction_csv = os.path.join(
    safe_root,
    "Fig6_MNI_ElasticNet_predictions_only.csv"
)

# ------------------------------------------------------------
# 3. ARCGIS ENVIRONMENT
# ------------------------------------------------------------

wgs84 = arcpy.SpatialReference(4326)
utm44n = arcpy.SpatialReference(32644)

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = utm44n
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

work_gdb = os.path.join(safe_root, "work.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(safe_root, "work.gdb")

arcpy.env.workspace = work_gdb
arcpy.env.scratchWorkspace = work_gdb

# ------------------------------------------------------------
# 4. COPY PREDICTION CSV TO SAFE PATH
# ------------------------------------------------------------

local_prediction_csv = os.path.join(
    safe_root,
    "Hanumakonda_SFI_regularized_ML_predictions.csv"
)

if os.path.exists(local_prediction_csv):
    os.remove(local_prediction_csv)

shutil.copy2(prediction_csv_source, local_prediction_csv)

print("Prediction CSV copied to safe path:")
print(local_prediction_csv)

# ------------------------------------------------------------
# 5. FILTER ONLY MNI + ELASTICNET PREDICTIONS
# ------------------------------------------------------------

required_columns = [
    "Latitude",
    "Longitude",
    "Target",
    "Model",
    predicted_source_field
]

filtered_rows = []

with open(local_prediction_csv, "r", newline="", encoding="utf-8-sig") as infile:
    reader = csv.DictReader(infile)
    input_columns = reader.fieldnames

    print("\nInput prediction CSV fields:")
    print(input_columns)

    for col in required_columns:
        if col not in input_columns:
            raise Exception(
                f"Required column not found: {col}\n"
                f"Available columns: {input_columns}"
            )

    unique_targets = set()
    unique_models = set()

    for row in reader:
        target_value = str(row["Target"]).strip()
        model_value = str(row["Model"]).strip()

        unique_targets.add(target_value)
        unique_models.add(model_value)

        target_match = target_value == target_field_name
        model_match = model_value.lower() in accepted_model_names

        if target_match and model_match:
            try:
                lon = float(row["Longitude"])
                lat = float(row["Latitude"])
                pred = float(row[predicted_source_field])

                filtered_rows.append({
                    "ID": len(filtered_rows) + 1,
                    "Longitude": lon,
                    "Latitude": lat,
                    predicted_field: pred
                })

            except:
                pass

if len(filtered_rows) < 10:
    print("\nAvailable Target values:")
    print(sorted(list(unique_targets)))

    print("\nAvailable Model values:")
    print(sorted(list(unique_models)))

    raise Exception(
        "Too few ElasticNet-predicted MNI records found. "
        "Check Target and Model names in the prediction CSV."
    )

with open(filtered_prediction_csv, "w", newline="", encoding="utf-8") as outfile:
    fieldnames = [
        "ID",
        "Longitude",
        "Latitude",
        predicted_field
    ]

    writer = csv.DictWriter(outfile, fieldnames=fieldnames)
    writer.writeheader()

    for row in filtered_rows:
        writer.writerow(row)

print("\nFiltered predicted MNI CSV created:")
print(filtered_prediction_csv)
print("Number of predicted MNI ElasticNet points:", len(filtered_rows))

pred_values = np.array(
    [row[predicted_field] for row in filtered_rows],
    dtype=float
)

print("Predicted MNI range:",
      round(float(np.min(pred_values)), 4),
      "-",
      round(float(np.max(pred_values)), 4))

print("Predicted MNI mean:",
      round(float(np.mean(pred_values)), 4))

# ------------------------------------------------------------
# 6. CREATE POINTS AND PROJECT TO UTM 44N
# ------------------------------------------------------------

points_wgs84 = os.path.join(work_gdb, "fig6_pred_mni_points_wgs84")
points_utm = os.path.join(work_gdb, "fig6_pred_mni_points_utm44n")
boundary_utm = os.path.join(work_gdb, "fig6_boundary_utm44n")

for item in [points_wgs84, points_utm, boundary_utm]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

arcpy.management.XYTableToPoint(
    in_table=filtered_prediction_csv,
    out_feature_class=points_wgs84,
    x_field=x_field,
    y_field=y_field,
    coordinate_system=wgs84
)

arcpy.management.Project(
    in_dataset=points_wgs84,
    out_dataset=points_utm,
    out_coor_system=utm44n
)

boundary_sr = arcpy.Describe(boundary_source).spatialReference

if boundary_sr.factoryCode == 32644:
    arcpy.management.CopyFeatures(
        boundary_source,
        boundary_utm
    )
else:
    arcpy.management.Project(
        in_dataset=boundary_source,
        out_dataset=boundary_utm,
        out_coor_system=utm44n
    )

print("\nPredicted MNI points and boundary prepared in UTM 44N.")

# ------------------------------------------------------------
# 7. CREATE ORDINARY KRIGING RASTER AND CLIP TO BOUNDARY
# ------------------------------------------------------------

ok_raw = os.path.join(work_gdb, "Fig6_Predicted_MNI_OK_raw")
ok_clip = os.path.join(work_gdb, "Fig6_Predicted_MNI_OK_clipped")
ok_classified = os.path.join(work_gdb, "Fig6_Predicted_MNI_OK_classified")

for item in [ok_raw, ok_clip, ok_classified]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

for item in [raw_raster_out, classified_raster_out]:
    if arcpy.Exists(item):
        arcpy.management.Delete(item)

arcpy.env.extent = arcpy.Describe(boundary_utm).extent

kriging_model = KrigingModelOrdinary("SPHERICAL")

ok_result = Kriging(
    in_point_features=points_utm,
    z_field=predicted_field,
    kriging_model=kriging_model,
    cell_size=cell_size
)

ok_result.save(ok_raw)

clipped_result = ExtractByMask(
    in_raster=ok_raw,
    in_mask_data=boundary_utm
)

clipped_result.save(ok_clip)

arcpy.management.CalculateStatistics(ok_clip)

arcpy.management.CopyRaster(
    in_raster=ok_clip,
    out_rasterdataset=raw_raster_out,
    pixel_type="32_BIT_FLOAT"
)

print("Predicted MNI Ordinary Kriging clipped raster created:")
print(raw_raster_out)

# ------------------------------------------------------------
# 8. CLASSIFY PREDICTED MNI RASTER
# Same breaks as observed MNI for direct comparison
# ------------------------------------------------------------

remap = RemapRange([
    [0.00, 0.72, 1],
    [0.72, 0.77, 2],
    [0.77, 0.82, 3],
    [0.82, 0.87, 4],
    [0.87, 1.00, 5]
])

classified_result = Reclassify(
    in_raster=ok_clip,
    reclass_field="Value",
    remap=remap,
    missing_values="NODATA"
)

classified_result.save(ok_classified)

arcpy.management.BuildRasterAttributeTable(
    ok_classified,
    "Overwrite"
)

arcpy.management.CalculateStatistics(ok_classified)

arcpy.management.CopyRaster(
    in_raster=ok_classified,
    out_rasterdataset=classified_raster_out,
    pixel_type="8_BIT_UNSIGNED"
)

print("Classified predicted MNI OK raster created:")
print(classified_raster_out)

# ------------------------------------------------------------
# 9. READ RASTER TO NUMPY
# ------------------------------------------------------------

nodata_value = -999999.0
ras = arcpy.Raster(ok_clip)

arr = arcpy.RasterToNumPyArray(
    ras,
    nodata_to_value=nodata_value
).astype("float64")

arr[arr <= nodata_value + 1] = np.nan

xmin = ras.extent.XMin
xmax = ras.extent.XMax
ymin = ras.extent.YMin
ymax = ras.extent.YMax

extent = [xmin, xmax, ymin, ymax]

class_arr = np.full(arr.shape, np.nan)

class_arr[(arr >= 0.00) & (arr < 0.72)] = 1
class_arr[(arr >= 0.72) & (arr < 0.77)] = 2
class_arr[(arr >= 0.77) & (arr < 0.82)] = 3
class_arr[(arr >= 0.82) & (arr < 0.87)] = 4
class_arr[(arr >= 0.87) & (arr <= 1.00)] = 5

masked_class_arr = np.ma.masked_invalid(class_arr)

# ------------------------------------------------------------
# 10. COLOURS AND LABELS
# ------------------------------------------------------------

class_colors = [
    (215 / 255, 48 / 255, 39 / 255),
    (252 / 255, 141 / 255, 89 / 255),
    (254 / 255, 224 / 255, 139 / 255),
    (145 / 255, 207 / 255, 96 / 255),
    (26 / 255, 152 / 255, 80 / 255)
]

class_labels = [
    "0.67-0.72  Lower local MNI",
    "0.72-0.77  Low-moderate MNI",
    "0.77-0.82  Moderate MNI",
    "0.82-0.87  High MNI",
    "0.87-0.93  Highest local MNI"
]

cmap = ListedColormap(class_colors)
cmap.set_bad("white")

norm = BoundaryNorm(
    [0.5, 1.5, 2.5, 3.5, 4.5, 5.5],
    cmap.N
)

legend_handles = []

for i in range(5):
    handle = Patch(
        facecolor=class_colors[i],
        edgecolor="black",
        linewidth=0.5,
        label=class_labels[i]
    )
    legend_handles.append(handle)

# ------------------------------------------------------------
# 11. HELPER FUNCTIONS
# ------------------------------------------------------------

def save_tiff(fig, path):
    try:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white",
            pil_kwargs={"compression": "tiff_lzw"}
        )
    except TypeError:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white"
        )


def plot_boundary(ax):
    with arcpy.da.SearchCursor(boundary_utm, ["SHAPE@"]) as cursor:
        for row in cursor:
            geom = row[0]

            for part in geom:
                xs = []
                ys = []

                for pnt in part:
                    if pnt:
                        xs.append(pnt.X)
                        ys.append(pnt.Y)
                    else:
                        if len(xs) > 0:
                            ax.plot(
                                xs,
                                ys,
                                color="black",
                                linewidth=1.2,
                                zorder=4
                            )
                            xs = []
                            ys = []

                if len(xs) > 0:
                    ax.plot(
                        xs,
                        ys,
                        color="black",
                        linewidth=1.2,
                        zorder=4
                    )


def plot_points(ax):
    xs = []
    ys = []

    with arcpy.da.SearchCursor(points_utm, ["SHAPE@XY"]) as cursor:
        for row in cursor:
            x, y = row[0]
            xs.append(x)
            ys.append(y)

    ax.scatter(
        xs,
        ys,
        s=9,
        c="black",
        edgecolors="white",
        linewidths=0.25,
        zorder=5
    )

# ------------------------------------------------------------
# 12. DEGREE COORDINATE FORMATTER
