import os

# ------------------------------------------------------------
# 0. FORCE SAFE NO-SPACE TEMP PATHS
# ------------------------------------------------------------

safe_root = r"D:\GIS_TMP\Fig8_Predicted_MiNI_IDW"
safe_temp = r"D:\GIS_TMP\ArcTemp"

os.makedirs(safe_root, exist_ok=True)
