import arcpy
import csv
import shutil
import numpy as np

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from matplotlib.colors import ListedColormap, BoundaryNorm
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter, MaxNLocator

from arcpy.sa import Idw, ExtractByMask, Reclassify, RemapRange

# ------------------------------------------------------------
# 1. INPUTS
# ------------------------------------------------------------

prediction_csv_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_SFI_regularized_ML_predictions.csv"

boundary_source = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\08_figures\Fig2_best_interpolation_analysis\Fig2_best_interpolation_analysis.gdb\hanumakonda_boundary_utm44n_for_fig2"

x_field = "Longitude"
y_field = "Latitude"

target_field_name = "MiNI"

# Accept both spelling forms if present in CSV
accepted_model_names = ["elasticnet", "elastic net"]

predicted_source_field = "Predicted"
predicted_field = "Predicted_MiNI"

cell_size = 30
dpi = 600

outputs_folder = os.path.join(safe_root, "outputs")
os.makedirs(outputs_folder, exist_ok=True)

# ------------------------------------------------------------
# 2. OUTPUT FILES
# ------------------------------------------------------------

map_only_tif = os.path.join(
    outputs_folder,
    "Fig_8_MAP_ONLY_Predicted_MiNI_ElasticNet_IDW_degree_coordinates.tif"
)

legend_only_tif = os.path.join(
    outputs_folder,
    "Fig_8_LEGEND_ONLY_Predicted_MiNI_ElasticNet_IDW.tif"
)

north_arrow_tif = os.path.join(
    outputs_folder,
    "Fig_8_NORTH_ARROW_ONLY.tif"
)

scale_bar_tif = os.path.join(
    outputs_folder,
    "Fig_8_SCALE_BAR_ONLY.tif"
)

raw_raster_out = os.path.join(
    outputs_folder,
    "Fig_8_Predicted_MiNI_ElasticNet_IDW_raw.tif"
)

classified_raster_out = os.path.join(
    outputs_folder,
    "Fig_8_Predicted_MiNI_ElasticNet_IDW_classified.tif"
)

filtered_prediction_csv = os.path.join(
    safe_root,
    "Fig8_MiNI_ElasticNet_predictions_only.csv"
)

# ------------------------------------------------------------
# 3. ARCGIS ENVIRONMENT
# ------------------------------------------------------------

wgs84 = arcpy.SpatialReference(4326)
utm44n = arcpy.SpatialReference(32644)

arcpy.env.overwriteOutput = True
arcpy.env.outputCoordinateSystem = utm44n
arcpy.env.cellSize = cell_size

arcpy.CheckOutExtension("Spatial")

work_gdb = os.path.join(safe_root, "work.gdb")

if not arcpy.Exists(work_gdb):
    arcpy.management.CreateFileGDB(safe_root, "work.gdb")

arcpy.env.workspace = work_gdb
arcpy.env.scratchWorkspace = work_gdb

# ------------------------------------------------------------
# 4. COPY PREDICTION CSV TO SAFE PATH
# ------------------------------------------------------------

local_prediction_csv = os.path.join(
    safe_root,
    "Hanumakonda_SFI_regularized_ML_predictions.csv"
)

if os.path.exists(local_prediction_csv):
    os.remove(local_prediction_csv)

shutil.copy2(prediction_csv_source, local_prediction_csv)

print("Prediction CSV copied to safe path:")
print(local_prediction_csv)

# ------------------------------------------------------------
# 5. FILTER ONLY MiNI + ELASTICNET PREDICTIONS
# ------------------------------------------------------------

required_columns = [
    "Latitude",
    "Longitude",
    "Target",
    "Model",
    predicted_source_field
]

filtered_rows = []

with open(local_prediction_csv, "r", newline="", encoding="utf-8-sig") as infile:
    reader = csv.DictReader(infile)
    input_columns = reader.fieldnames

    print("\nInput prediction CSV fields:")
    print(input_columns)

    for col in required_columns:
        if col not in input_columns:
            raise Exception(
                f"Required column not found: {col}\n"
                f"Available columns: {input_columns}"
            )

    unique_targets = set()
    unique_models = set()

    for row in reader:
        target_value = str(row["Target"]).strip()
        model_value = str(row["Model"]).strip()

        unique_targets.add(target_value)
        unique_models.add(model_value)

        target_match = target_value == target_field_name
        model_match = model_value.lower() in accepted_model_names

        if target_match and model_match:
            try:
                lon = float(row["Longitude"])
                lat = float(row["Latitude"])
                pred = float(row[predicted_source_field])

                filtered_rows.append({
                    "ID": len(filtered_rows) + 1,
                    "Longitude": lon,
                    "Latitude": lat,
                    predicted_field: pred
                })

            except:
                pass

if len(filtered_rows) < 10:
    print("\nAvailable Target values:")
    print(sorted(list(unique_targets)))

