def save_tiff(fig, path):
    try:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white",
            pil_kwargs={"compression": "tiff_lzw"}
        )
    except TypeError:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white"
        )


def plot_boundary(ax):
    with arcpy.da.SearchCursor(boundary_utm, ["SHAPE@"]) as cursor:
        for row in cursor:
            geom = row[0]

            for part in geom:
                xs = []
                ys = []

                for pnt in part:
                    if pnt:
                        xs.append(pnt.X)
                        ys.append(pnt.Y)
                    else:
                        if len(xs) > 0:
                            ax.plot(
                                xs,
                                ys,
                                color="black",
                                linewidth=1.2,
                                zorder=4
                            )
                            xs = []
                            ys = []

                if len(xs) > 0:
                    ax.plot(
                        xs,
                        ys,
                        color="black",
                        linewidth=1.2,
                        zorder=4
                    )


def plot_points(ax):
    xs = []
    ys = []

    with arcpy.da.SearchCursor(points_utm, ["SHAPE@XY"]) as cursor:
        for row in cursor:
            x, y = row[0]
            xs.append(x)
            ys.append(y)

    ax.scatter(
        xs,
        ys,
        s=9,
        c="black",
        edgecolors="white",
        linewidths=0.25,
        zorder=5
    )

# ------------------------------------------------------------
# 12. DEGREE COORDINATE FORMATTER
# Raster remains UTM. Only display labels are degrees.
# ------------------------------------------------------------

mid_x = (xmin + xmax) / 2
mid_y = (ymin + ymax) / 2


def utm_to_lonlat(x_utm, y_utm):
    point_utm = arcpy.PointGeometry(
        arcpy.Point(float(x_utm), float(y_utm)),
        utm44n
    )

    point_wgs84 = point_utm.projectAs(wgs84)
    p = point_wgs84.firstPoint

    return p.X, p.Y


def degree_label(value, is_longitude=True):
    if is_longitude:
        direction = "E" if value >= 0 else "W"
    else:
        direction = "N" if value >= 0 else "S"

    return f"{abs(value):.2f} deg {direction}"


def longitude_formatter(x, pos):
    lon, lat = utm_to_lonlat(x, mid_y)
    return degree_label(lon, is_longitude=True)


def latitude_formatter(y, pos):
    lon, lat = utm_to_lonlat(mid_x, y)
    return degree_label(lat, is_longitude=False)


def style_axes(ax):
    ax.set_xlim(xmin, xmax)
    ax.set_ylim(ymin, ymax)
    ax.set_aspect("equal", adjustable="box")

    ax.set_xlabel("Longitude", fontsize=10)
    ax.set_ylabel("Latitude", fontsize=10)

    ax.xaxis.set_major_formatter(FuncFormatter(longitude_formatter))
    ax.yaxis.set_major_formatter(FuncFormatter(latitude_formatter))

    ax.xaxis.set_major_locator(MaxNLocator(5))
    ax.yaxis.set_major_locator(MaxNLocator(5))

    ax.tick_params(
        axis="x",
        labelsize=8,
        rotation=25
    )

    ax.tick_params(
        axis="y",
        labelsize=8
    )

    ax.grid(
        True,
        linestyle="--",
        linewidth=0.35,
        alpha=0.35
    )

    for spine in ax.spines.values():
        spine.set_linewidth(1.0)
        spine.set_color("black")

