# ------------------------------------------------------------

required_columns = [
    "Latitude",
    "Longitude",
    "Target",
    "Model",
    predicted_source_field
]

filtered_rows = []

with open(local_prediction_csv, "r", newline="", encoding="utf-8-sig") as infile:
    reader = csv.DictReader(infile)
    input_columns = reader.fieldnames

    print("\nInput prediction CSV fields:")
    print(input_columns)

    for col in required_columns:
        if col not in input_columns:
            raise Exception(
                f"Required column not found: {col}\n"
                f"Available columns: {input_columns}"
            )

    unique_targets = set()
    unique_models = set()

    for row in reader:
        target_value = str(row["Target"]).strip()
        model_value = str(row["Model"]).strip()

        unique_targets.add(target_value)
        unique_models.add(model_value)

        target_clean = target_value.lower().replace(" ", "").replace("-", "_")
        model_clean = model_value.lower().strip()

        target_match = (
            target_value == target_field_name
            or target_clean in accepted_target_names
        )

        model_match = model_clean in accepted_model_names

        if target_match and model_match:
            try:
                lon = float(row["Longitude"])
                lat = float(row["Latitude"])
                pred = float(row[predicted_source_field])

                filtered_rows.append({
                    "ID": len(filtered_rows) + 1,
                    "Longitude": lon,
                    "Latitude": lat,
                    predicted_field: pred
                })

            except:
                pass

if len(filtered_rows) < 10:
    print("\nAvailable Target values:")
    print(sorted(list(unique_targets)))

    print("\nAvailable Model values:")
    print(sorted(list(unique_models)))

    raise Exception(
        "Too few Lasso-predicted SFI_5core records found. "
        "Check Target and Model names in the prediction CSV."
    )

with open(filtered_prediction_csv, "w", newline="", encoding="utf-8") as outfile:
    fieldnames = [
        "ID",
        "Longitude",
        "Latitude",
        predicted_field
    ]

    writer = csv.DictWriter(outfile, fieldnames=fieldnames)
    writer.writeheader()

    for row in filtered_rows:
        writer.writerow(row)

