overall = arcpy.Raster(overall_raster)
mni = arcpy.Raster(mni_raster)
mini = arcpy.Raster(mini_raster)

# High priority if any major predicted layer is locally low
high_condition = (
    (overall < 0.77) |
    (mni < 0.77) |
    (mini < 0.75)
)

# Moderate priority if not high but any layer is in mid range
moderate_condition = (
    (overall < 0.87) |
    (mni < 0.87) |
    (mini < 0.95)
)

priority = Con(
    high_condition,
    1,
    Con(
        moderate_condition,
        2,
        3
    )
)

