# ------------------------------------------------------------
# 4. CREATE INTEGRATED PRIORITY RASTER
# Rule:
# High priority = 1
# Moderate priority = 2
# Low priority = 3
# ------------------------------------------------------------

if arcpy.Exists(priority_raster_gdb):
    arcpy.management.Delete(priority_raster_gdb)

if arcpy.Exists(priority_raster_out):
    arcpy.management.Delete(priority_raster_out)

overall = arcpy.Raster(overall_raster)
mni = arcpy.Raster(mni_raster)
mini = arcpy.Raster(mini_raster)

# Robust nested Con version.
# Avoids possible raster OR-expression errors.

priority = Con(
    overall < 0.77,
    1,
    Con(
        mni < 0.77,
        1,
        Con(
            mini < 0.75,
            1,
            Con(
                overall < 0.87,
                2,
                Con(
                    mni < 0.87,
                    2,
                    Con(
                        mini < 0.95,
                        2,
                        3
                    )
                )
            )
        )
    )
)

priority_clip = ExtractByMask(
    in_raster=priority,
    in_mask_data=boundary_utm
)

priority_clip.save(priority_raster_gdb)

arcpy.management.CalculateStatistics(priority_raster_gdb)

arcpy.management.CopyRaster(
    in_raster=priority_raster_gdb,
    out_rasterdataset=priority_raster_out,
    pixel_type="8_BIT_UNSIGNED"
)

