nodata_value = -999999
ras = arcpy.Raster(priority_raster_gdb)

arr = arcpy.RasterToNumPyArray(
    ras,
    nodata_to_value=nodata_value
).astype("float64")

arr[arr <= nodata_value + 1] = np.nan

cell_size = float(ras.meanCellWidth)
cell_area_ha = (cell_size * cell_size) / 10000.0

valid = arr[~np.isnan(arr)]

total_cells = len(valid)
total_area_ha = total_cells * cell_area_ha

zone_names = {
    1: "High priority",
    2: "Moderate priority",
    3: "Low priority"
}

with open(area_csv_out, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)

    writer.writerow([
        "Priority_class",
        "Zone",
        "Cell_count",
        "Area_ha",
        "Area_percent"
    ])

    for cls in [1, 2, 3]:
        count = int(np.sum(valid == cls))
        area_ha = count * cell_area_ha
        percent = (area_ha / total_area_ha) * 100 if total_area_ha > 0 else 0

        writer.writerow([
            cls,
            zone_names[cls],
            count,
            round(area_ha, 4),
            round(percent, 2)
        ])

        print(
            zone_names[cls],
            "| cells:", count,
            "| area ha:", round(area_ha, 4),
            "| percent:", round(percent, 2)
        )

print("Area statistics saved:")
