# All maps use same boundary extent.
sample_ras = results[0]["raster"]

xmin = sample_ras.extent.XMin
xmax = sample_ras.extent.XMax
ymin = sample_ras.extent.YMin
ymax = sample_ras.extent.YMax

mid_x = (xmin + xmax) / 2
mid_y = (ymin + ymax) / 2


def utm_to_lonlat(x_utm, y_utm):
    point_utm = arcpy.PointGeometry(
        arcpy.Point(float(x_utm), float(y_utm)),
        utm44n
    )

    point_wgs84 = point_utm.projectAs(wgs84)
    p = point_wgs84.firstPoint

    return p.X, p.Y


def degree_label(value, is_longitude=True):
    if is_longitude:
        direction = "E" if value >= 0 else "W"
    else:
        direction = "N" if value >= 0 else "S"

    return f"{abs(value):.2f} deg {direction}"


def longitude_formatter(x, pos):
    lon, lat = utm_to_lonlat(x, mid_y)
    return degree_label(lon, is_longitude=True)


def latitude_formatter(y, pos):
    lon, lat = utm_to_lonlat(mid_x, y)
    return degree_label(lat, is_longitude=False)


def style_axes(ax):
    ax.set_aspect("equal", adjustable="box")
    ax.set_xlabel("Longitude", fontsize=7)
    ax.set_ylabel("Latitude", fontsize=7)

    ax.xaxis.set_major_formatter(FuncFormatter(longitude_formatter))
    ax.yaxis.set_major_formatter(FuncFormatter(latitude_formatter))

    ax.xaxis.set_major_locator(MaxNLocator(4))
    ax.yaxis.set_major_locator(MaxNLocator(4))

    ax.tick_params(axis="x", labelsize=6, rotation=25)
    ax.tick_params(axis="y", labelsize=6)

    ax.grid(
        True,
        linestyle="--",
        linewidth=0.25,
        alpha=0.35
    )

    for spine in ax.spines.values():
        spine.set_linewidth(0.8)
        spine.set_color("black")

