# ------------------------------------------------------------
# 7. HELPER FUNCTIONS
# ------------------------------------------------------------

def clean_text(value):
    return str(value).strip().lower().replace(" ", "").replace("-", "_")


def delete_if_exists(path):
    try:
        if path is not None and arcpy.Exists(path):
            arcpy.management.Delete(path)
    except:
        pass


def filter_prediction_csv(panel_def):
    target_names_clean = [clean_text(v) for v in panel_def["target_names"]]
    model_names_clean = [clean_text(v) for v in panel_def["model_names"]]

    value_field = panel_def["value_field"]

    out_csv = os.path.join(
        safe_root,
        f"Fig9{panel_def['panel']}_{panel_def['short_name']}_predictions.csv"
    )

    rows = []
    unique_targets = set()
    unique_models = set()

    with open(local_prediction_csv, "r", newline="", encoding="utf-8-sig") as infile:
        reader = csv.DictReader(infile)
        fields = reader.fieldnames

        required = [
            "Longitude",
            "Latitude",
            "Target",
            "Model",
            "Predicted"
        ]

        for col in required:
            if col not in fields:
                raise Exception(
                    f"Required column not found: {col}\nAvailable fields: {fields}"
                )

        for row in reader:
            target_raw = str(row["Target"]).strip()
            model_raw = str(row["Model"]).strip()

            unique_targets.add(target_raw)
            unique_models.add(model_raw)

            target_match = clean_text(target_raw) in target_names_clean
            model_match = clean_text(model_raw) in model_names_clean

            if target_match and model_match:
                try:
                    lon = float(row["Longitude"])
                    lat = float(row["Latitude"])
                    pred = float(row["Predicted"])

                    rows.append({
                        "ID": len(rows) + 1,
                        "Longitude": lon,
                        "Latitude": lat,
                        value_field: pred
                    })
                except:
                    pass

    if len(rows) < 10:
        print("\nAvailable Target values:")
        print(sorted(list(unique_targets)))

        print("\nAvailable Model values:")
        print(sorted(list(unique_models)))

        raise Exception(
            f"Too few records found for panel {panel_def['panel']}."
        )

    with open(out_csv, "w", newline="", encoding="utf-8") as outfile:
        writer = csv.DictWriter(
            outfile,
            fieldnames=["ID", "Longitude", "Latitude", value_field]
        )
        writer.writeheader()

        for row in rows:
            writer.writerow(row)

    values = np.array([r[value_field] for r in rows], dtype=float)

    p33 = float(np.percentile(values, 33.333333))
    p66 = float(np.percentile(values, 66.666667))

    print("\nFiltered CSV created:", out_csv)
    print("Panel:", panel_def["panel"], panel_def["short_name"])
    print("Records:", len(rows))
    print("Predicted range:", round(values.min(), 4), "-", round(values.max(), 4))
    print("Tertile thresholds:", round(p33, 4), round(p66, 4))

    return out_csv, p33, p66


def make_points_from_csv(input_csv, value_field, point_prefix):
    points_wgs84 = os.path.join(work_gdb, point_prefix + "_wgs84")
    points_utm = os.path.join(work_gdb, point_prefix + "_utm44n")

    delete_if_exists(points_wgs84)
    delete_if_exists(points_utm)

    arcpy.management.XYTableToPoint(
        in_table=input_csv,
        out_feature_class=points_wgs84,
        x_field=x_field,
        y_field=y_field,
        coordinate_system=wgs84
    )

    arcpy.management.Project(
        in_dataset=points_wgs84,
        out_dataset=points_utm,
        out_coor_system=utm44n
    )

    return points_utm


def create_prediction_raster(points_fc, value_field, method_name, raster_prefix):
    raw_raster = os.path.join(work_gdb, raster_prefix + "_raw")
    clip_raster = os.path.join(work_gdb, raster_prefix + "_clip")

    delete_if_exists(raw_raster)
    delete_if_exists(clip_raster)

    if method_name == "IDW":
        result = Idw(
            in_point_features=points_fc,
            z_field=value_field,
            cell_size=cell_size,
            power=2
        )

    elif method_name == "OK":
        kriging_model = KrigingModelOrdinary("SPHERICAL")

        result = Kriging(
            in_point_features=points_fc,
            z_field=value_field,
            kriging_model=kriging_model,
            cell_size=cell_size
        )

    else:
        raise Exception("Unknown interpolation method: " + method_name)

    result.save(raw_raster)

    clipped = ExtractByMask(
        in_raster=raw_raster,
        in_mask_data=boundary_utm
    )

    clipped.save(clip_raster)

    arcpy.management.CalculateStatistics(clip_raster)

    return clip_raster


def create_relative_zone_raster(pred_raster, p33, p66, raster_prefix):
    zone_raster_gdb = os.path.join(work_gdb, raster_prefix + "_relative_zones")
    zone_raster_tif = os.path.join(
        outputs_folder,
        raster_prefix + "_relative_zones.tif"
    )

    delete_if_exists(zone_raster_gdb)
    delete_if_exists(zone_raster_tif)

    r = arcpy.Raster(pred_raster)

    # 1 = Low relative fertility
    # 2 = Moderate relative fertility
    # 3 = High relative fertility
    zones = Con(
        r <= p33,
        1,
        Con(
            r <= p66,
            2,
            3
        )
    )

    zones_clip = ExtractByMask(
        in_raster=zones,
        in_mask_data=boundary_utm
    )

    zones_clip.save(zone_raster_gdb)

    arcpy.management.CalculateStatistics(zone_raster_gdb)

    arcpy.management.CopyRaster(
        in_raster=zone_raster_gdb,
        out_rasterdataset=zone_raster_tif,
        pixel_type="8_BIT_UNSIGNED"
    )

    return zone_raster_gdb, zone_raster_tif


def raster_to_array(raster_path):
    nodata_value = -999999
    ras = arcpy.Raster(raster_path)

    arr = arcpy.RasterToNumPyArray(
        ras,
        nodata_to_value=nodata_value
    ).astype("float64")

    arr[arr <= nodata_value + 1] = np.nan

    extent = [
        ras.extent.XMin,
        ras.extent.XMax,
        ras.extent.YMin,
        ras.extent.YMax
    ]

    return arr, extent, ras


def save_tiff(fig, path):
    try:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white",
            pil_kwargs={"compression": "tiff_lzw"}
        )
    except TypeError:
        fig.savefig(
            path,
            dpi=dpi,
            bbox_inches="tight",
            facecolor="white"
        )


def plot_boundary(ax):
    with arcpy.da.SearchCursor(boundary_utm, ["SHAPE@"]) as cursor:
        for row in cursor:
            geom = row[0]

            for part in geom:
                xs = []
                ys = []

                for pnt in part:
                    if pnt:
                        xs.append(pnt.X)
                        ys.append(pnt.Y)
                    else:
                        if len(xs) > 0:
                            ax.plot(
                                xs,
                                ys,
                                color="black",
                                linewidth=1.0,
                                zorder=4
                            )
                            xs = []
                            ys = []

                if len(xs) > 0:
                    ax.plot(
                        xs,
                        ys,
                        color="black",
                        linewidth=1.0,
                        zorder=4
                    )


def plot_points(ax, points_fc):
    xs = []
    ys = []

    with arcpy.da.SearchCursor(points_fc, ["SHAPE@XY"]) as cursor:
        for row in cursor:
            x, y = row[0]
            xs.append(x)
            ys.append(y)

    ax.scatter(
        xs,
        ys,
        s=4,
        c="black",
        edgecolors="white",
        linewidths=0.15,
        zorder=5
    )

# ------------------------------------------------------------
# 8. CREATE ALL PREDICTED AND RELATIVE-ZONE RASTERS
# ------------------------------------------------------------

results = []

for panel_def in panels:
    filtered_csv, p33, p66 = filter_prediction_csv(panel_def)

    points_utm = make_points_from_csv(
        input_csv=filtered_csv,
        value_field=panel_def["value_field"],
        point_prefix=panel_def["point_prefix"]
    )

    pred_raster = create_prediction_raster(
        points_fc=points_utm,
        value_field=panel_def["value_field"],
        method_name=panel_def["method"],
        raster_prefix=panel_def["raster_prefix"]
    )

    zone_raster_gdb, zone_raster_tif = create_relative_zone_raster(
        pred_raster=pred_raster,
        p33=p33,
        p66=p66,
        raster_prefix=panel_def["raster_prefix"]
    )

    arr, extent, ras = raster_to_array(zone_raster_gdb)

    results.append({
        "panel": panel_def["panel"],
        "short_name": panel_def["short_name"],
        "title": panel_def["title"],
        "method": panel_def["method"],
        "p33": p33,
        "p66": p66,
        "points": points_utm,
        "pred_raster": pred_raster,
        "zone_raster_gdb": zone_raster_gdb,
        "zone_raster_tif": zone_raster_tif,
        "arr": arr,
        "extent": extent,
        "raster": ras
    })

print("\nAll relative-zone rasters created.")

# ------------------------------------------------------------
