zone_names = {
    1: "Low relative fertility / high management priority",
    2: "Moderate relative fertility / moderate management priority",
    3: "High relative fertility / lower management priority"
}

with open(area_csv_out, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)

    writer.writerow([
        "Index",
        "Panel",
        "Relative_class",
        "Zone_interpretation",
        "Cell_count",
        "Area_ha",
        "Area_percent",
        "Lower_threshold",
        "Upper_threshold"
    ])

    for res in results:
        arr = res["arr"]
        ras = res["raster"]

        valid = arr[~np.isnan(arr)]

        cell_size_actual = float(ras.meanCellWidth)
        cell_area_ha = (cell_size_actual * cell_size_actual) / 10000.0

        total_cells = len(valid)
        total_area_ha = total_cells * cell_area_ha

        for cls in [1, 2, 3]:
            count = int(np.sum(valid == cls))
            area_ha = count * cell_area_ha
            percent = (area_ha / total_area_ha) * 100 if total_area_ha > 0 else 0

            if cls == 1:
                lower_thr = ""
                upper_thr = round(res["p33"], 6)
            elif cls == 2:
                lower_thr = round(res["p33"], 6)
                upper_thr = round(res["p66"], 6)
            else:
                lower_thr = round(res["p66"], 6)
                upper_thr = ""

            writer.writerow([
                res["short_name"],
                res["panel"],
                cls,
                zone_names[cls],
                count,
                round(area_ha, 4),
                round(percent, 2),
                lower_thr,
                upper_thr
            ])

print("Table 6 area statistics saved:")
