rasters = {
    "A": os.path.join(gdb, "Obs_Overall_IDW"),
    "B": os.path.join(gdb, "Pre_Overall_IDW"),
    "C": os.path.join(gdb, "Res_Overall_IDW")
}


# Output

output_fig = os.path.join(
    fig_out,
    "Fig_7_Overall_SFI_Observed_Predicted_Residual_600dpi.tif"
)


# ------------------------------------------------------------
# FUNCTION TO READ RASTER
# ------------------------------------------------------------

def read_raster(path):

    with rasterio.open(path) as src:

        data = src.read(1)

        extent = [
            src.bounds.left,
            src.bounds.right,
            src.bounds.bottom,
            src.bounds.top
        ]

    data = np.ma.masked_invalid(data)

    return data, extent



# ------------------------------------------------------------
# CREATE FIGURE
# ------------------------------------------------------------

fig, axes = plt.subplots(
    2,
    2,
    figsize=(12,10),
    dpi=600
)

axes = axes.flatten()


titles = {
    "A":
    "Observed Overall Soil Fertility Index\n(IDW interpolation)",

    "B":
    "Predicted Overall Soil Fertility Index\n(Lasso-IDW)",

    "C":
    "Residual Overall Soil Fertility Index\n(Local prediction mismatch)"
}


cmaps = {
    "A":"RdYlGn",
    "B":"RdYlGn",
    "C":"RdBu_r"
}


for ax, key in zip(axes, ["A","B","C"]):

    raster, extent = read_raster(
        rasters[key]
    )

    im = ax.imshow(
        raster,
        extent=extent,
        cmap=cmaps[key],
        interpolation="nearest"
    )


    ax.set_title(
        f"({key}) {titles[key]}",
        fontsize=12,
        fontweight="bold"
    )


    ax.set_xlabel(
        "Longitude",
        fontsize=10
    )

    ax.set_ylabel(
        "Latitude",
        fontsize=10
    )


    ax.tick_params(
        labelsize=9
    )


    # panel border

    for spine in ax.spines.values():
        spine.set_linewidth(1.2)


    # colour bar

    cbar = fig.colorbar(
        im,
        ax=ax,
        shrink=0.75
    )

    cbar.ax.tick_params(
        labelsize=8
    )



# Remove empty fourth panel

axes[3].axis("off")


fig.suptitle(
    "Spatial comparison of observed, predicted and residual Overall Soil Fertility Index surfaces",
    fontsize=16,
    fontweight="bold",
    y=0.98
)


plt.tight_layout(
    rect=[0,0,1,0.95]
)


plt.savefig(
    output_fig,
    dpi=600,
    format="tiff",
    bbox_inches="tight"
)


plt.close()


print("SUCCESS")
print("Saved Figure:")
print(output_fig)

