# Supplementary Table
# Correlation of soil variables and fertility indices with yield
# ============================================================

import pandas as pd
from scipy.stats import pearsonr, spearmanr


# ------------------------------------------------------------
# INPUT FILE
# ------------------------------------------------------------

input_file = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_SFI_yield_validation_dataset.csv"


df = pd.read_csv(input_file)


print("Dataset size:", df.shape)


# ------------------------------------------------------------
# YIELD VARIABLE
# ------------------------------------------------------------

yield_col = "Yield_q_acre"


# ------------------------------------------------------------
# VARIABLES TO TEST
# ------------------------------------------------------------

variables = [

    # measured soil indicators
    "pH",
    "EC",
    "OC",
    "N",
    "P2O5",
    "K2O",
    "Zn",
    "Fe",
    "Cu",
    "Mn",

    # fertility indices
    "CCI",
    "MNI",
    "MiNI",
    "Overall_SFI",
    "SFI_5core"

]


# ------------------------------------------------------------
# CORRELATION ANALYSIS
# ------------------------------------------------------------

results = []


for var in variables:

    temp = df[[yield_col, var]].dropna()


    pearson_r, pearson_p = pearsonr(
        temp[var],
        temp[yield_col]
    )


    spearman_rho, spearman_p = spearmanr(
        temp[var],
        temp[yield_col]
    )


    results.append({

        "Variable": var,

        "n": len(temp),

        "Pearson_r": round(
            pearson_r,
            3
        ),

        "Pearson_p": round(
            pearson_p,
            4
        ),

        "Spearman_rho": round(
            spearman_rho,
            3
        ),

        "Spearman_p": round(
            spearman_p,
            4
        )

    })


# ------------------------------------------------------------
# CREATE TABLE
# ------------------------------------------------------------

corr_table = pd.DataFrame(results)


print("\nCorrelation table")
print(corr_table)



# ------------------------------------------------------------
# SAVE OUTPUT
# ------------------------------------------------------------

output_file = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\09_tables\Supplementary_Table_Yield_Correlation_All_Soil_Variables.csv"


corr_table.to_csv(
    output_file,
    index=False
)


print("\nSaved:")
print(output_file)

