# ============================================================
# Supplementary Table S4
# Model performance comparison
# Ridge, Lasso, ElasticNet
# ============================================================

import pandas as pd
import numpy as np

from sklearn.model_selection import GridSearchCV, train_test_split, KFold
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler

from sklearn.linear_model import Ridge, Lasso, ElasticNet

from sklearn.metrics import (
    r2_score,
    mean_squared_error,
    mean_absolute_error
)


# ------------------------------------------------------------
# INPUT DATA
# ------------------------------------------------------------

file = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\06_ml_tables\Hanumakonda_SFI_yield_validation_dataset.csv"


df = pd.read_csv(file)


# ------------------------------------------------------------
# PREDICTORS
# ------------------------------------------------------------

predictors = [
    "pH",
    "EC",
    "OC",
    "N",
    "P2O5",
    "K2O",
    "Zn",
    "Fe",
    "Cu",
    "Mn"
]


targets = [
    "Overall_SFI",
    "CCI",
    "MNI",
    "MiNI",
    "SFI_5core"
]


X = df[predictors]


# ------------------------------------------------------------
# TRAIN TEST SPLIT
# ------------------------------------------------------------

X_train, X_test = train_test_split(
    X,
    test_size=0.20,
    random_state=42
)


# ------------------------------------------------------------
# MODELS
# ------------------------------------------------------------

models = {


"Ridge":
(
Ridge(),
{
"model__alpha":[0.001,0.01,0.1,1,10,100]
}
),


"Lasso":
(
Lasso(max_iter=10000),
{
"model__alpha":[0.001,0.01,0.1,1,10]
}
),


"ElasticNet":
(
ElasticNet(max_iter=10000),
{
"model__alpha":[0.001,0.01,0.1,1],
"model__l1_ratio":[0.1,0.5,0.7,0.9]
}
)

}


# ------------------------------------------------------------
# CROSS VALIDATION
# ------------------------------------------------------------

cv = KFold(
    n_splits=5,
    shuffle=True,
    random_state=42
)



results=[]


# ------------------------------------------------------------
# RUN MODELS
# ------------------------------------------------------------

for target in targets:


    y = df[target]


    y_train, y_test = train_test_split(
        y,
        test_size=0.20,
        random_state=42
    )


    for name,(model,param) in models.items():


        pipe = Pipeline(
            [
                (
                "scale",
                StandardScaler()
                ),

                (
                "model",
                model
                )
            ]
        )


        grid = GridSearchCV(
            pipe,
            param,
            cv=cv,
            scoring="r2"
        )


        grid.fit(
            X_train,
            y_train
        )


        best_model = grid.best_estimator_


        # CV score

        cv_score = grid.best_score_


        # TEST prediction

        pred = best_model.predict(
            X_test
        )


        r2 = r2_score(
            y_test,
            pred
        )


        rmse = np.sqrt(
            mean_squared_error(
                y_test,
                pred
            )
        )


        mae = mean_absolute_error(
            y_test,
            pred
        )


        rpd = (
            np.std(y_test, ddof=1)
            /
            rmse
        )


        results.append(
            {

            "Target":
            target,


            "Model":
            name,


            "Best_parameters":
            grid.best_params_,


            "CV_R2":
            round(cv_score,3),


            "Test_R2":
            round(r2,3),


            "RMSE":
            round(rmse,3),


            "MAE":
            round(mae,3),


            "RPD":
            round(rpd,3),


            "n":
            len(y_test)

            }
        )



# ------------------------------------------------------------
# TABLE
# ------------------------------------------------------------

table_S4 = pd.DataFrame(results)


print(table_S4)



# ------------------------------------------------------------
# SAVE
# ------------------------------------------------------------

output = r"D:\SR University\Scieitific Reports\Hanumakonda_DSM_ML\09_tables\Table_S4_Model_Performance_All_Targets.csv"


table_S4.to_csv(
    output,
    index=False
)


print("\nSaved:")
print(output)

