# ============================================================

def read_arc_raster(raster_path):

    raster = arcpy.Raster(
        raster_path
    )

    array = arcpy.RasterToNumPyArray(
        raster,
        nodata_to_value=np.nan
    ).astype("float64")

    array[
        ~np.isfinite(array)
    ] = np.nan

    extent_object = raster.extent

    extent = [
        float(extent_object.XMin),
        float(extent_object.XMax),
        float(extent_object.YMin),
        float(extent_object.YMax)
    ]

    spatial_reference = arcpy.Describe(
        raster_path
    ).spatialReference

    return (
        array,
        extent,
        spatial_reference
    )


# ============================================================
# 6. READ OBSERVED + PREDICTED RASTERS
#
# A and B must use the SAME colour range so that the
# observed and predicted maps are visually comparable.
# ============================================================

obs_data, obs_extent, obs_sr = read_arc_raster(
    OBS_RASTER
)

pred_data, _, _ = read_arc_raster(
    PRED_RASTER
)


if np.all(
    np.isnan(obs_data)
):

    raise ValueError(
        "Observed Overall SFI raster contains no valid values."
    )


# ============================================================
# 7. COMMON COLOUR RANGE FOR FIG. 7A AND 7B
# ============================================================

obs_valid = obs_data[
    np.isfinite(obs_data)
]

pred_valid = pred_data[
    np.isfinite(pred_data)
]


combined_values = np.concatenate(
    [
        obs_valid,
        pred_valid
    ]
)


if combined_values.size == 0:

    raise ValueError(
        "Observed and predicted Overall SFI rasters "
        "contain no valid values."
    )


VMIN = float(
    np.min(combined_values)
)

VMAX = float(
    np.max(combined_values)
)


print("")
print("Common Fig. 7A-7B colour range:")
print(
    round(VMIN, 6),
    "to",
    round(VMAX, 6)
)


# ============================================================
# 8. RASTER EXTENT
# ============================================================

xmin = obs_extent[0]
xmax = obs_extent[1]
ymin = obs_extent[2]
ymax = obs_extent[3]

xmid = (
    xmin + xmax
) / 2.0

ymid = (
    ymin + ymax
) / 2.0


# ============================================================
# 9. CONVERT DISPLAYED AXES TO LONGITUDE/LATITUDE
#
# Raster itself remains unchanged.
# Only tick labels are converted to WGS84 coordinates.
# ============================================================

WGS84 = arcpy.SpatialReference(
    4326
)


def project_xy_to_wgs84(
    x,
    y
):

    point_geometry = arcpy.PointGeometry(
        arcpy.Point(
            float(x),
            float(y)
        ),
        obs_sr
    )

    projected_geometry = point_geometry.projectAs(
        WGS84
    )

    point = projected_geometry.firstPoint

    return (
        float(point.X),
        float(point.Y)
    )


def format_longitude(
    x,
    pos=None
):

    try:

        lon, lat = project_xy_to_wgs84(
            x,
            ymid
        )

        return f"{lon:.2f}°E"

    except Exception:

        return f"{x:.0f}"


def format_latitude(
    y,
    pos=None
):

    try:

        lon, lat = project_xy_to_wgs84(
            xmid,
            y
        )

        return f"{lat:.2f}°N"

    except Exception:

        return f"{y:.0f}"


