# ============================================================
# 5. FUNCTION TO READ ArcGIS RASTER
# ============================================================

def read_arc_raster(
    raster_path
):

    raster = arcpy.Raster(
        raster_path
    )


    array = arcpy.RasterToNumPyArray(
        raster,
        nodata_to_value=np.nan
    ).astype(
        "float64"
    )


    array[
        ~np.isfinite(array)
    ] = np.nan


    extent_object = raster.extent


    extent = [

        float(
            extent_object.XMin
        ),

        float(
            extent_object.XMax
        ),

        float(
            extent_object.YMin
        ),

        float(
            extent_object.YMax
        )
    ]


    spatial_reference = arcpy.Describe(
        raster_path
    ).spatialReference


    return (
        array,
        extent,
        spatial_reference
    )


