# ============================================================
# 5. FIND EXISTING RASTER
# ============================================================

def resolve_raster(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path) or arcpy.Exists(path):

            print("")
            print(label + " raster found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " raster was not found.\n\nChecked paths:\n"
        + "\n".join(candidates)
    )


OBS_RASTER = resolve_raster(
    OBSERVED_MNI_CANDIDATES,
    "Observed MNI Ordinary Kriging"
)


PRED_RASTER = resolve_raster(
    PREDICTED_MNI_CANDIDATES,
    "Predicted MNI ElasticNet Ordinary Kriging"
)


# ============================================================
# 6. READ ArcGIS RASTER
# ============================================================

def read_arc_raster(
    raster_path
):

    raster = arcpy.Raster(
        raster_path
    )


    array = arcpy.RasterToNumPyArray(
        raster,
        nodata_to_value=np.nan
    ).astype(
        "float64"
    )


    array[
        ~np.isfinite(array)
    ] = np.nan


    ext = raster.extent


    extent = [
        float(ext.XMin),
        float(ext.XMax),
        float(ext.YMin),
        float(ext.YMax)
    ]


    spatial_reference = arcpy.Describe(
        raster_path
    ).spatialReference


    return (
        array,
        extent,
        spatial_reference
    )


# ============================================================
# 7. READ OBSERVED AND PREDICTED MNI
# ============================================================

obs_data, obs_extent, obs_sr = read_arc_raster(
    OBS_RASTER
)


pred_data, pred_extent, pred_sr = read_arc_raster(
    PRED_RASTER
)


# ============================================================
# 8. CHECK VALID DATA
# ============================================================

if np.all(
    np.isnan(obs_data)
):

    raise ValueError(
        "Observed MNI raster contains no valid values."
    )


if np.all(
    np.isnan(pred_data)
):

    raise ValueError(
        "Predicted MNI raster contains no valid values."
    )


# ============================================================
# 9. SAME COLOUR RANGE AS FIG. 8A
#
# Observed and predicted MNI must use one common range
# for valid direct comparison.
# ============================================================

obs_valid = obs_data[
    np.isfinite(
        obs_data
    )
]


pred_valid = pred_data[
    np.isfinite(
        pred_data
    )
]


combined_values = np.concatenate(
    [
        obs_valid,
        pred_valid
    ]
)


if combined_values.size == 0:

    raise ValueError(
        "No valid MNI values found."
    )


VMIN = float(
    np.min(
        combined_values
    )
)


VMAX = float(
    np.max(
        combined_values
    )
)


if VMAX <= VMIN:

    raise ValueError(
        "Invalid MNI colour range."
    )


print("")
print(
    "Common Fig. 8A-8B MNI colour range:"
)

print(
    round(
        VMIN,
        6
    ),
    "to",
    round(
        VMAX,
        6
    )
)


# ============================================================
# 10. PREDICTED RASTER EXTENT
# ============================================================

xmin = pred_extent[0]

xmax = pred_extent[1]

ymin = pred_extent[2]

ymax = pred_extent[3]


xmid = (
    xmin + xmax
) / 2.0


ymid = (
    ymin + ymax
) / 2.0


# ============================================================
# 11. WGS84 FOR DISPLAYED COORDINATES
#
# Raster values/projection remain unchanged.
# Only displayed coordinate numbers are converted.
# ============================================================

WGS84 = arcpy.SpatialReference(
    4326
)


# ============================================================
# 12. PROJECT X/Y TO LONGITUDE/LATITUDE
# ============================================================

def project_xy_to_wgs84(
    x,
    y
):

    point_geometry = arcpy.PointGeometry(

        arcpy.Point(
            float(x),
            float(y)
        ),

        pred_sr
    )


    projected_geometry = point_geometry.projectAs(
        WGS84
    )


    point = projected_geometry.firstPoint


    return (
        float(
            point.X
        ),
        float(
            point.Y
        )
    )


# ============================================================
# 13. LONGITUDE FORMATTER
# ============================================================

def format_longitude(
    x,
    pos=None
):

    try:

        lon, lat = project_xy_to_wgs84(
            x,
            ymid
        )


        return (
            f"{lon:.2f}°E"
        )


    except Exception:

        return (
            f"{x:.0f}"
        )


# ============================================================
# 14. LATITUDE FORMATTER
# ============================================================

def format_latitude(
    y,
    pos=None
):

    try:

        lon, lat = project_xy_to_wgs84(
            xmid,
            y
        )


        return (
            f"{lat:.2f}°N"
        )


    except Exception:

        return (
            f"{y:.0f}"
        )


