def resolve_raster(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path) or arcpy.Exists(path):

            print("")
            print(label + " raster found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " raster was not found.\n\nChecked paths:\n"
        + "\n".join(candidates)
    )


