# ============================================================
# 6. FIND EXISTING RASTER
# ============================================================

def resolve_raster(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path) or arcpy.Exists(path):

            print("")
            print(label + " found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " was not found.\n\nChecked:\n"
        + "\n".join(candidates)
    )


ZONE_RASTER = resolve_raster(
    ZONE_RASTER_CANDIDATES,
    "Fig. 9B MNI relative-zone raster"
)


# ============================================================
# 7. FIND PREDICTION CSV
# ============================================================

def resolve_file(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path):

            print("")
            print(label + " found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " was not found.\n\nChecked:\n"
        + "\n".join(candidates)
    )


PREDICTION_CSV = resolve_file(
    PREDICTION_CSV_CANDIDATES,
    "Fig. 9B MNI prediction CSV"
)


# ============================================================
# 8. CHECK BOUNDARY
# ============================================================

if not arcpy.Exists(
    BOUNDARY_SOURCE
):

    raise FileNotFoundError(
        "Study boundary not found:\n"
        + BOUNDARY_SOURCE
    )


# ============================================================
# 9. READ EXISTING RELATIVE-ZONE RASTER
# ============================================================

ras = arcpy.Raster(
    ZONE_RASTER
)


zone_array = arcpy.RasterToNumPyArray(
    ras,
    nodata_to_value=-999999
).astype(
    "float64"
)


# Keep only classes 1, 2 and 3.

zone_array[
    ~np.isin(
        zone_array,
        [1, 2, 3]
    )
] = np.nan


# ============================================================
# 10. RASTER EXTENT AND SPATIAL REFERENCE
# ============================================================

extent = [

    float(
        ras.extent.XMin
    ),

    float(
        ras.extent.XMax
    ),

    float(
        ras.extent.YMin
    ),

    float(
        ras.extent.YMax
    )
]


zone_sr = arcpy.Describe(
    ZONE_RASTER
).spatialReference


xmin = extent[0]
xmax = extent[1]
ymin = extent[2]
ymax = extent[3]


xmid = (
    xmin + xmax
) / 2.0


ymid = (
    ymin + ymax
) / 2.0


# ============================================================
# 11. READ MNI PREDICTION LOCATIONS
# ============================================================

def read_mni_points(
    csv_path
):

    lon_values = []
    lat_values = []


    with open(
        csv_path,
        "r",
        newline="",
        encoding="utf-8-sig"
    ) as infile:


        reader = csv.DictReader(
            infile
        )


        field_names = (
            reader.fieldnames
            or []
        )


        if (
            "Longitude" not in field_names
            or
            "Latitude" not in field_names
        ):

            raise ValueError(
                "Prediction CSV does not contain "
                "Longitude and Latitude fields."
            )


        # The Fig9B filtered CSV may already contain only
        # MNI + ElasticNet records.
        is_filtered_file = (

            "Target" not in field_names

            or

            "Model" not in field_names
        )


        for row in reader:


            if not is_filtered_file:


                target = str(
                    row.get(
                        "Target",
                        ""
                    )
                ).strip().lower()


                target = target.replace(
                    " ",
                    ""
                ).replace(
                    "-",
                    "_"
                )


                model = str(
                    row.get(
                        "Model",
                        ""
                    )
                ).strip().lower()


                model = model.replace(
                    " ",
                    ""
                ).replace(
                    "-",
                    "_"
                )


                valid_targets = {
                    "mni"
                }


                valid_models = {

                    "elasticnet",

                    "elastic_net"
                }


                if target not in valid_targets:

                    continue


                if model not in valid_models:

                    continue


            try:

                lon = float(
                    row["Longitude"]
                )

                lat = float(
                    row["Latitude"]
                )


            except (
                TypeError,
                ValueError,
                KeyError
            ):

                continue


            lon_values.append(
                lon
            )


            lat_values.append(
                lat
            )


    if len(
        lon_values
    ) == 0:

        raise ValueError(
            "No valid MNI ElasticNet "
            "prediction locations were found."
        )


    return (
        lon_values,
        lat_values
    )


point_lon, point_lat = read_mni_points(
    PREDICTION_CSV
)


# ============================================================
# 12. CONVERT POINTS TO RASTER COORDINATE SYSTEM
# ============================================================

WGS84 = arcpy.SpatialReference(
    4326
)


point_x = []
point_y = []


for lon, lat in zip(
    point_lon,
    point_lat
):


    geom = arcpy.PointGeometry(

        arcpy.Point(
            lon,
            lat
        ),

        WGS84
    )


    if zone_sr.factoryCode != 4326:

        geom = geom.projectAs(
            zone_sr
        )


    p = geom.firstPoint


    point_x.append(
        float(p.X)
    )


    point_y.append(
        float(p.Y)
    )


print("")
print(
    "MNI prediction locations loaded:",
    len(point_x)
)


# ============================================================
# 13. READ STUDY BOUNDARY
# ============================================================

boundary_parts = []


boundary_sr = arcpy.Describe(
    BOUNDARY_SOURCE
).spatialReference


with arcpy.da.SearchCursor(
    BOUNDARY_SOURCE,
    ["SHAPE@"]
) as cursor:


    for row in cursor:


        geom = row[0]


        # Project boundary to raster spatial reference
        # if required.

        if (
            boundary_sr.name
            !=
            zone_sr.name
        ):

            geom = geom.projectAs(
                zone_sr
            )


        for part in geom:


            xs = []
            ys = []


            for pnt in part:


                if pnt:


                    xs.append(
                        float(pnt.X)
                    )


                    ys.append(
                        float(pnt.Y)
                    )


                else:


                    if len(xs) > 1:

                        boundary_parts.append(
                            (xs, ys)
                        )


                    xs = []
                    ys = []


            if len(xs) > 1:

                boundary_parts.append(
                    (xs, ys)
                )


# ============================================================
# 14. DEGREE COORDINATE FORMATTERS
#
# Raster remains in original projected CRS.
# Only displayed labels are converted to WGS84 degrees.
# ============================================================

WGS84_DISPLAY = arcpy.SpatialReference(
    4326
)


def projected_xy_to_lonlat(
    x,
    y
):


    geom = arcpy.PointGeometry(

        arcpy.Point(
            float(x),
            float(y)
        ),

        zone_sr
    )


    if zone_sr.factoryCode != 4326:

        geom = geom.projectAs(
            WGS84_DISPLAY
        )


    p = geom.firstPoint


    return (
        float(p.X),
        float(p.Y)
    )


# ============================================================
# 15. LONGITUDE FORMATTER
# ============================================================

def format_longitude(
    x,
    pos=None
):


    lon, lat = projected_xy_to_lonlat(
        x,
        ymid
    )


    direction = (
        "E"
        if lon >= 0
        else "W"
    )


    return (
        f"{abs(lon):.2f}°{direction}"
    )


# ============================================================
# 16. LATITUDE FORMATTER
# ============================================================

def format_latitude(
    y,
    pos=None
):


    lon, lat = projected_xy_to_lonlat(
        xmid,
        y
    )


    direction = (
        "N"
        if lat >= 0
        else "S"
    )


    return (
        f"{abs(lat):.2f}°{direction}"
    )


