# ============================================================

PREDICTION_CSV_CANDIDATES = [

    r"D:\GIS_TMP\Fig9_Relative_Fertility_Zones"
    r"\Fig9C_MiNI_predictions.csv",

    r"D:\SR University\Scieitific Reports"
    r"\Hanumakonda_DSM_ML\06_ml_tables"
    r"\Hanumakonda_SFI_regularized_ML_predictions.csv"
]


