# ============================================================
# 6. FIND EXISTING RELATIVE-ZONE RASTER
# ============================================================

def resolve_raster(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path) or arcpy.Exists(path):

            print("")
            print(label + " found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " was not found.\n\nChecked:\n"
        + "\n".join(candidates)
    )


ZONE_RASTER = resolve_raster(
    ZONE_RASTER_CANDIDATES,
    "Fig. 9D SFI_5core relative-zone raster"
)


# ============================================================
# 7. FIND PREDICTION CSV
# ============================================================

def resolve_file(
    candidates,
    label
):

    for path in candidates:

        if os.path.exists(path):

            print("")
            print(label + " found:")
            print(path)

            return path

    raise FileNotFoundError(
        label
        + " was not found.\n\nChecked:\n"
        + "\n".join(candidates)
    )


