# ============================================================
# 13. READ STUDY BOUNDARY
# ============================================================

boundary_parts = []


boundary_sr = arcpy.Describe(
    BOUNDARY_SOURCE
).spatialReference


with arcpy.da.SearchCursor(
    BOUNDARY_SOURCE,
    ["SHAPE@"]
) as cursor:


    for row in cursor:


        geom = row[0]


        if (
            boundary_sr.name
            !=
            zone_sr.name
        ):

            geom = geom.projectAs(
                zone_sr
            )


        for part in geom:


            xs = []

            ys = []


            for pnt in part:


                if pnt:


                    xs.append(
                        float(pnt.X)
                    )


                    ys.append(
                        float(pnt.Y)
                    )


                else:


                    if len(xs) > 1:

                        boundary_parts.append(
                            (xs, ys)
                        )


                    xs = []

                    ys = []


            if len(xs) > 1:

                boundary_parts.append(
                    (xs, ys)
                )


# ============================================================
# 14. DISPLAY COORDINATES AS LONGITUDE/LATITUDE
#
# IMPORTANT:
# Raster itself remains unchanged.
# Only displayed axis labels are transformed.
# ============================================================

WGS84_DISPLAY = arcpy.SpatialReference(
    4326
)


def projected_xy_to_lonlat(
    x,
    y
):


    geom = arcpy.PointGeometry(

        arcpy.Point(
            float(x),
            float(y)
        ),

        zone_sr
    )


    if zone_sr.factoryCode != 4326:

        geom = geom.projectAs(
            WGS84_DISPLAY
        )


    point = geom.firstPoint


    return (
        float(point.X),
        float(point.Y)
    )


# ============================================================
# 15. LONGITUDE FORMATTER
# ============================================================

def format_longitude(
    x,
    pos=None
):


    lon, lat = projected_xy_to_lonlat(
        x,
        ymid
    )


    direction = (
        "E"
        if lon >= 0
        else "W"
    )


    return (
        f"{abs(lon):.2f}°{direction}"
    )


# ============================================================
# 16. LATITUDE FORMATTER
# ============================================================

def format_latitude(
    y,
    pos=None
):


    lon, lat = projected_xy_to_lonlat(
        xmid,
        y
    )


    direction = (
        "N"
        if lat >= 0
        else "S"
    )


    return (
        f"{abs(lat):.2f}°{direction}"
    )


