# ============================================================
# 6. COLUMN FINDER
#
# Allows small differences in column naming without
# breaking the code.
# ============================================================

def find_column(
    dataframe,
    candidates,
    label
):

    for candidate in candidates:

        if candidate in dataframe.columns:

            print(
                label,
                "=",
                candidate
            )

            return candidate


    raise KeyError(
        label
        + " column was not found.\n"
        + "Checked names: "
        + str(candidates)
    )


