FIGSIZE = (
    9.5,
    7.5
)


PANEL_FONT_SIZE = 25

STATS_FONT_SIZE = 16

SCATTER_SIZE = 58

SCATTER_ALPHA = 0.88

TREND_LINE_WIDTH = 2.8


# ============================================================
# 11. SAVE FUNCTION
# ============================================================

def save_panel(
    fig,
    outputs
):


    # TIFF
    try:

        fig.savefig(

            outputs["tif"],

            dpi=DPI,

            format="tiff",

            bbox_inches="tight",

            facecolor="white",

            pil_kwargs={
                "compression":
                    "tiff_lzw"
            }
        )


    except TypeError:

        fig.savefig(

            outputs["tif"],

            dpi=DPI,

            format="tiff",

            bbox_inches="tight",

            facecolor="white"
        )


    # PNG
    fig.savefig(

        outputs["png"],

        dpi=DPI,

        format="png",

        bbox_inches="tight",

        facecolor="white"
    )


    # VECTOR PDF
    fig.savefig(

        outputs["pdf"],

        format="pdf",

        bbox_inches="tight",

        facecolor="white"
    )


    plt.close(
        fig
    )


# ============================================================
# 12. COMMON AXIS STYLE
# ============================================================

def style_axis(
    ax
):


    ax.tick_params(

        axis="both",

        which="major",

        labelsize=16,

        width=1.5,

        length=7,

        pad=7
    )


    ax.grid(

        True,

        linestyle="--",

        linewidth=0.6,

        alpha=0.28
    )


    for spine in ax.spines.values():

        spine.set_linewidth(
            1.5
        )


# ============================================================
# 13. PANEL LETTER
# ============================================================

def add_panel_letter(
    ax,
    letter
):


    ax.text(

        0.02,
        0.98,

        letter,

        transform=ax.transAxes,

        ha="left",

        va="top",

        fontsize=PANEL_FONT_SIZE,

        fontweight="bold",

        bbox=dict(

            facecolor="white",

            edgecolor="none",

            alpha=0.85,

            pad=2.5
        ),

        zorder=20
    )


# ============================================================
# 14. P-VALUE FORMATTER
# ============================================================

def p_text(
    value
):


    if value < 0.001:

        return "< 0.001"


    return (
        f"= {value:.3f}"
    )


# ============================================================
# 15. SCATTER-PLOT FUNCTION
#
# Used for panels B, C, D and E.
#
# Statistics are recalculated directly from the same data.
# ============================================================

def create_scatter_panel(

    panel_letter,

    x_col,

    x_label,

    title,

    outputs
):


    temp = df[
        [
            x_col,
            YIELD_COL
        ]
    ].dropna().copy()


    if len(temp) < 3:

        raise ValueError(
            "Too few valid observations for "
            + title
        )


    x = temp[
        x_col
    ].to_numpy(
        dtype=float
    )


    y = temp[
        YIELD_COL
    ].to_numpy(
        dtype=float
    )


    # --------------------------------------------------------
    # Pearson correlation
    # --------------------------------------------------------

    pearson_r, pearson_p = pearsonr(
        x,
        y
    )


    # --------------------------------------------------------
    # Spearman correlation
    # --------------------------------------------------------

    spearman_rho, spearman_p = spearmanr(
        x,
        y
    )


    # --------------------------------------------------------
    # Linear trend used only as graphical trend line.
    # --------------------------------------------------------

    slope, intercept = np.polyfit(
        x,
        y,
        1
    )


    x_line = np.linspace(

        np.min(x),

        np.max(x),

        300
    )


    y_line = (
        slope * x_line
        + intercept
    )


    # --------------------------------------------------------
    # Figure
    # --------------------------------------------------------

    fig, ax = plt.subplots(

        figsize=FIGSIZE,

        dpi=DPI
    )


    # --------------------------------------------------------
    # Data points
    # --------------------------------------------------------

    ax.scatter(

        x,

        y,

        s=SCATTER_SIZE,

        c="#2f5d7c",

        edgecolors="white",

        linewidths=0.7,

        alpha=SCATTER_ALPHA,

        zorder=5
    )


    # --------------------------------------------------------
    # Trend line
    # --------------------------------------------------------

    ax.plot(

        x_line,

        y_line,

        color="#b44a4a",

        linewidth=TREND_LINE_WIDTH,

        zorder=6
    )


    # --------------------------------------------------------
    # Panel letter
    # --------------------------------------------------------

    add_panel_letter(
        ax,
        panel_letter
    )


    # --------------------------------------------------------
    # Title
    # --------------------------------------------------------

    ax.set_title(

        title,

        fontsize=22,

        fontweight="bold",

        pad=17
    )


    # --------------------------------------------------------
    # Axis labels
    # --------------------------------------------------------

    ax.set_xlabel(

        x_label,

        fontsize=19,

        fontweight="bold",

        labelpad=11
    )


    ax.set_ylabel(

        r"Yield (q acre$^{-1}$)",

        fontsize=19,

        fontweight="bold",

        labelpad=11
    )


    style_axis(
        ax
    )


    # --------------------------------------------------------
    # LARGE STATISTICAL ANNOTATION
    #
    # This directly addresses the Editor's Fig. 10 complaint.
    # --------------------------------------------------------

    stats_text = (

        f"n = {len(temp)}\n"

        f"Pearson r = {pearson_r:.3f} "
        f"(p {p_text(pearson_p)})\n"

        f"Spearman ρ = {spearman_rho:.3f} "
        f"(p {p_text(spearman_p)})"
    )


    ax.text(

        0.97,
        0.96,

        stats_text,

        transform=ax.transAxes,

        ha="right",

        va="top",

        fontsize=STATS_FONT_SIZE,

        fontweight="bold",

        linespacing=1.40,

        bbox=dict(

            boxstyle="round,pad=0.60",

            facecolor="white",

            edgecolor="black",

            linewidth=1.3,

            alpha=0.96
        ),

        zorder=20
    )


    # --------------------------------------------------------
    # Layout
    # --------------------------------------------------------

    fig.subplots_adjust(

        left=0.15,

        right=0.96,

        bottom=0.16,

        top=0.87
    )


    # --------------------------------------------------------
    # Save
    # --------------------------------------------------------

    save_panel(
        fig,
        outputs
    )


    # --------------------------------------------------------
    # Report
    # --------------------------------------------------------

    print("")
    print(
        "FIGURE 10"
        + panel_letter
        + " COMPLETE"
    )

    print(
        "n =",
        len(temp)
    )

    print(
        "Pearson r =",
        round(
            pearson_r,
            6
        )
    )

    print(
        "Pearson p =",
        pearson_p
    )

    print(
        "Spearman rho =",
        round(
            spearman_rho,
            6
        )
    )

    print(
        "Spearman p =",
        spearman_p
    )


