FIGSIZE = (
    12.8,
    7.6
)


PANEL_FONT = 25

INFO_FONT = 14.5

SCATTER_SIZE = 58


SCATTER_COLOR = (
    "#2f5d7c"
)


TREND_COLOR = (
    "#b44a4a"
)


TREND_WIDTH = 2.8


# ============================================================
# 11. COMMON YIELD AXIS FOR PANELS B-F
#
# Gives B, C, D, E and F the same vertical scale.
# ============================================================

_all_yield = df[
    YIELD_COL
].dropna().to_numpy(
    dtype=float
)


if len(
    _all_yield
) == 0:

    raise ValueError(
        "No valid yield values found."
    )


_yield_range = float(

    np.max(
        _all_yield
    )

    -

    np.min(
        _all_yield
    )
)


if _yield_range <= 0:

    _yield_range = 1.0


YIELD_YMIN = float(

    np.min(
        _all_yield
    )

    -

    0.06 * _yield_range
)


YIELD_YMAX = float(

    np.max(
        _all_yield
    )

    +

    0.06 * _yield_range
)


# ============================================================
# 12. CREATE FIGURE WITH DEDICATED INFORMATION COLUMN
#
# LEFT  = graph
# RIGHT = statistics / legend
#
# They physically cannot overlap.
# ============================================================

def new_figure():

    fig = plt.figure(
        figsize=FIGSIZE
    )


    gs = fig.add_gridspec(

        1,
        2,

        width_ratios=[
            4.35,
            1.75
        ],

        left=0.085,

        right=0.985,

        bottom=0.14,

        top=0.88,

        wspace=0.08
    )


    ax = fig.add_subplot(
        gs[
            0,
            0
        ]
    )


    info_ax = fig.add_subplot(
        gs[
            0,
            1
        ]
    )


    info_ax.set_axis_off()


    return (
        fig,
        ax,
        info_ax
    )


# ============================================================
# 13. COMMON GRAPH STYLE
# ============================================================

def style_axis(
    ax
):

    ax.tick_params(

        axis="both",

        which="major",

        labelsize=15,

        width=1.4,

        length=6,

        pad=6
    )


    ax.grid(

        True,

        linestyle="--",

        linewidth=0.6,

        alpha=0.25,

        zorder=0
    )


    ax.set_axisbelow(
        True
    )


    for spine in ax.spines.values():

        spine.set_linewidth(
            1.4
        )


# ============================================================
# 14. PANEL LETTER
# ============================================================

def add_panel_letter(
    ax,
    letter
):

    ax.text(

        0.015,
        0.985,

        letter,

        transform=ax.transAxes,

        ha="left",

        va="top",

        fontsize=PANEL_FONT,

        fontweight="bold",

        color="black",

        bbox=dict(

            facecolor="white",

            edgecolor="none",

            alpha=0.90,

            pad=2.0
        ),

        zorder=30
    )


# ============================================================
# 15. P-VALUE FORMATTER
# ============================================================

def format_p(
    p
):

    if p < 0.001:

        return "< 0.001"


    return (
        f"= {p:.3f}"
    )


# ============================================================
# 16. STATISTICS BOX
#
# IMPORTANT:
# This box is placed in info_ax,
# NEVER in the graph itself.
# ============================================================

def add_info_box(
    info_ax,
    lines,
    y=0.96
):

    info_ax.text(

        0.03,
        y,

        "\n".join(
            lines
        ),

        transform=info_ax.transAxes,

        ha="left",

        va="top",

        fontsize=INFO_FONT,

        fontweight="bold",

        linespacing=1.35,

        bbox=dict(

            boxstyle="round,pad=0.55",

            facecolor="white",

            edgecolor="black",

            linewidth=1.2,

            alpha=1.0
        )
    )


# ============================================================
# 17. EXTERNAL LEGEND / PLOT KEY
#
# Also placed OUTSIDE the graph.
# ============================================================

def add_key(
    info_ax,
    handles,
    labels,
    y=0.34,
    title="Plot key"
):

    info_ax.text(

        0.03,
        y + 0.18,

        title,

        transform=info_ax.transAxes,

        ha="left",

        va="top",

        fontsize=13.5,

        fontweight="bold"
    )


    info_ax.legend(

        handles,

        labels,

        loc="upper left",

        bbox_to_anchor=(
            0.00,
            y + 0.12
        ),

        frameon=False,

        fontsize=12.5,

        handlelength=2.2,

        borderaxespad=0.0,

        labelspacing=0.85
    )


# ============================================================
# 18. SAVE PANEL
# ============================================================

def save_panel(
    fig,
    outputs
):

    # --------------------------------------------------------
    # TIFF
    # --------------------------------------------------------

    try:

        fig.savefig(

            outputs[
                "tif"
            ],

            dpi=DPI,

            format="tiff",

            facecolor="white",

            bbox_inches="tight",

            pad_inches=0.08,

            pil_kwargs={
                "compression":
                    "tiff_lzw"
            }
        )


    except TypeError:

        fig.savefig(

            outputs[
                "tif"
            ],

            dpi=DPI,

            format="tiff",

            facecolor="white",

            bbox_inches="tight",

            pad_inches=0.08
        )


    # --------------------------------------------------------
    # PNG
    # --------------------------------------------------------

    fig.savefig(

        outputs[
            "png"
        ],

        dpi=DPI,

        format="png",

        facecolor="white",

        bbox_inches="tight",

        pad_inches=0.08
    )


    # --------------------------------------------------------
    # VECTOR PDF
    # --------------------------------------------------------

    fig.savefig(

        outputs[
            "pdf"
        ],

        format="pdf",

        facecolor="white",

        bbox_inches="tight",

        pad_inches=0.08
    )


    plt.close(
        fig
    )


# ============================================================
# 19. COMMON SCATTER-PLOT FUNCTION
#
# Used for 10B, 10C, 10D and 10E.
# ============================================================

def scatter_panel(

    letter,

    x_col,

    x_label,

    title,

    output
):

    temp = df[

        [
            x_col,
            YIELD_COL
        ]

    ].dropna().copy()


    if len(
        temp
    ) < 3:

        raise ValueError(
            "Too few observations for "
            + title
        )


    x = temp[
        x_col
    ].to_numpy(
        dtype=float
    )


    y = temp[
        YIELD_COL
    ].to_numpy(
        dtype=float
    )


    # --------------------------------------------------------
    # Pearson correlation
    # --------------------------------------------------------

    pearson_r, pearson_p = pearsonr(
        x,
        y
    )


    # --------------------------------------------------------
    # Spearman correlation
    # --------------------------------------------------------

    spearman_rho, spearman_p = spearmanr(
        x,
        y
    )


    # --------------------------------------------------------
    # Linear trend
    # --------------------------------------------------------

    slope, intercept = np.polyfit(
        x,
        y,
        1
    )


    x_line = np.linspace(

        np.min(
            x
        ),

        np.max(
            x
        ),

        300
    )


    y_line = (

        slope
        *
        x_line

        +

        intercept
    )


    # --------------------------------------------------------
    # Figure
    # --------------------------------------------------------

    fig, ax, info_ax = new_figure()


    # --------------------------------------------------------
    # Sample points
    # --------------------------------------------------------

    ax.scatter(

        x,

        y,

        s=SCATTER_SIZE,

        c=SCATTER_COLOR,

        edgecolors="white",

        linewidths=0.7,

        alpha=0.88,

        zorder=5
    )


    # --------------------------------------------------------
    # Linear trend
    # --------------------------------------------------------

    ax.plot(

        x_line,

        y_line,

        color=TREND_COLOR,

        linewidth=TREND_WIDTH,

        zorder=6
    )


    # --------------------------------------------------------
    # Panel letter
    # --------------------------------------------------------

    add_panel_letter(
        ax,
        letter
    )


    # --------------------------------------------------------
    # Title
    # --------------------------------------------------------

    ax.set_title(

        title,

        fontsize=21,

        fontweight="bold",

        pad=16
    )


    # --------------------------------------------------------
    # X label
    # --------------------------------------------------------

    ax.set_xlabel(

        x_label,

        fontsize=18,

        fontweight="bold",

        labelpad=10
    )


    # --------------------------------------------------------
    # Y label
    #
    # IMPORTANT:
    # Uses Matplotlib mathtext.
    # NO Unicode superscript minus.
    # Therefore NO square box appears.
    # --------------------------------------------------------

    ax.set_ylabel(

        r"Yield (q acre$^{-1}$)",

        fontsize=18,

        fontweight="bold",

        labelpad=10
    )


    style_axis(
        ax
    )


    # Same vertical scale for B-F

    ax.set_ylim(
        YIELD_YMIN,
        YIELD_YMAX
    )


    ax.margins(
        x=0.04
    )


    # ========================================================
    # STATISTICS OUTSIDE GRAPH
    # ========================================================

    add_info_box(

        info_ax,

        [

            f"n = {len(temp)}",

            "",

            f"Pearson $r$ = {pearson_r:.3f}",

            f"p {format_p(pearson_p)}",

            "",

            f"Spearman $\\rho$ = {spearman_rho:.3f}",

            f"p {format_p(spearman_p)}"
        ],

        y=0.96
    )


    # ========================================================
    # PLOT KEY OUTSIDE GRAPH
    # ========================================================

    point_handle = Line2D(

        [0],
        [0],

        marker="o",

        linestyle="None",

        markerfacecolor=SCATTER_COLOR,

        markeredgecolor="white",

        markeredgewidth=0.7,

        markersize=8
    )


    line_handle = Line2D(

        [0],
        [0],

        color=TREND_COLOR,

        linewidth=TREND_WIDTH
    )


    add_key(

        info_ax,

        [
            point_handle,
            line_handle
        ],

        [
            "Sampling point",
            "Linear trend"
        ],

        y=0.34,

        title="Plot key"
    )


    # ========================================================
    # SAVE
    # ========================================================

    save_panel(
        fig,
        output
    )


    # ========================================================
    # PRINT RESULTS
    # ========================================================

    print("")

    print(
        "Figure 10"
        + letter
        + " completed"
    )


    print(
        "n =",
        len(temp)
    )


    print(
        "Pearson r =",
        round(
            pearson_r,
            6
        )
    )


    print(
        "Pearson p =",
        pearson_p
    )


    print(
        "Spearman rho =",
        round(
            spearman_rho,
            6
        )
    )


    print(
        "Spearman p =",
        spearman_p
    )


# ============================================================
# ============================================================
# FIGURE 10A
# YIELD DISTRIBUTION
# ============================================================
# ============================================================

yield_data = df[
    YIELD_COL
].dropna().to_numpy(
    dtype=float
)


if len(
    yield_data
) == 0:

    raise ValueError(
        "No valid yield observations found."
    )


# ============================================================
# 20. DESCRIPTIVE STATISTICS
# ============================================================

