# ============================================================
# 31. STANDARDISE ZONE NAMES
# ============================================================

def normalize_zone(
    value
):

    text = str(
        value
    ).strip().lower()


    if (
        text in [
            "1",
            "1.0"
        ]

        or

        "low" in text
    ):

        return "Low"


    if (
        text in [
            "2",
            "2.0"
        ]

        or

        "moderate" in text
    ):

        return "Moderate"


    if (
        text in [
            "3",
            "3.0"
        ]

        or

        "high" in text
    ):

        return "High"


    return np.nan


