# ============================================================
# Available N - Yield Curvilinear Response Analysis
# Scientific Reports Revision 2
#
# Models:
# 1. Linear N
# 2. Log(N)
# 3. Quadratic N response
#
# Output:
# Supplementary Table for Editor Comment 3
# ============================================================


import os
import numpy as np
import pandas as pd

from sklearn.linear_model import LinearRegression
from sklearn.metrics import (
    r2_score,
    mean_squared_error
)

from scipy.stats import pearsonr


# ============================================================
# PATH
# ============================================================

csv_path = (
    r"D:\SR University\Scieitific Reports"
    r"\Hanumakonda_DSM_ML"
    r"\06_ml_tables"
    r"\Hanumakonda_SFI_yield_validation_dataset.csv"
)


output_csv = (
    r"D:\SR University\Scieitific Reports"
    r"\Hanumakonda_DSM_ML"
    r"\06_ml_tables"
    r"\Supplementary_Table_N_Yield_Response_Models.csv"
)


# ============================================================
# LOAD DATA
# ============================================================

df = pd.read_csv(
    csv_path
)


print(df.columns)


# ============================================================
# IDENTIFY VARIABLES
# ============================================================

yield_col = "Yield_q_acre"

N_col = "N"


data = df[
    [
        yield_col,
        N_col
    ]
].copy()


data = data.dropna()


# remove zero/negative N values
# because log transformation requires positive values

data = data[
    data[N_col] > 0
]


X_N = data[
    N_col
].values.reshape(
    -1,
    1
)


y = data[
    yield_col
].values


n = len(y)


print(
    "Samples used:",
    n
)


# ============================================================
# FUNCTION
# ============================================================

def calculate_metrics(
    name,
    X
):

    model = LinearRegression()

    model.fit(
        X,
        y
    )


    prediction = model.predict(
        X
    )


    r2 = r2_score(
        y,
        prediction
    )


    rmse = np.sqrt(
        mean_squared_error(
            y,
            prediction
        )
    )


    corr, p = pearsonr(
        prediction,
        y
    )


    residual = y - prediction


    aic = (

        n *
        np.log(
            np.sum(
                residual**2
            )
            /
            n
        )

        +

        2 *
        X.shape[1]

        +

        2

    )


    return {

        "Model": name,

        "Predictors": X.shape[1],

        "R2": r2,

        "RMSE": rmse,

        "Pearson_r_predicted_observed":
            corr,

        "Pearson_p":
            p,

        "AIC":
            aic,

        "Intercept":
            model.intercept_,

        "Coefficients":
            str(
                model.coef_
            )
    }


# ============================================================
# MODEL 1
# Linear N
# ============================================================

results = []


results.append(

    calculate_metrics(

        "Linear N",

        X_N
    )
)



# ============================================================
# MODEL 2
# Log transformed N
# ============================================================

X_logN = np.log(
    X_N
)


results.append(

    calculate_metrics(

        "Log(N)",

        X_logN
    )
)



# ============================================================
# MODEL 3
# Quadratic N
#
# Yield = b0 + b1*N + b2*N2
# ============================================================

X_quad = np.column_stack(

    [

        X_N[:,0],

        X_N[:,0]**2

    ]

)


results.append(

    calculate_metrics(

        "Quadratic N + N2",

        X_quad
    )
)



# ============================================================
# SAVE RESULTS
# ============================================================

result_df = pd.DataFrame(
    results
)


result_df.to_csv(

    output_csv,

    index=False

)


print("")
print(
    "=========================================="
)

print(
    "N-YIELD RESPONSE ANALYSIS COMPLETE"
)

print(
    "=========================================="
)


print(
    result_df
)


print("")
print(
    "Saved:"
)

print(
    output_csv
)


